code:
/**
 * API and realtime contracts shared by every service and client.
 * No service-specific business rules.
 *
 * Almost no runtime logic either, and the exceptions are all one kind of thing:
 * a rule both ends have to apply *identically* or the contract means nothing.
 * `listenPositionAt` is where a shared track has got to; `games/` is what a
 * board becomes when somebody plays a move. A server that computed either
 * differently from the clients reading it would be a session where nobody is
 * wrong and nobody agrees, so there is one implementation, in the package both
 * sides import.
 */

import type { GameId, GameSession } from './games';

// Named one by one rather than `export *`, and that is not a style choice: the
// package builds to CommonJS for the Node services, and the ESM clients import
// it through Node's interop, which finds named exports by *reading* the emitted
// file. A star re-export compiles to a runtime loop it cannot see through, so
// `GAMES` would exist at runtime and be missing at import - which is a check
// that fails and a renderer that does not.
export {
  GAMES,
  GAME_LIBRARY,
  gameRules,
  // Carrom: the board, the physics, and the shot both ends replay
  BASELINE,
  BASELINE_HALF_WIDTH,
  BLACK,
  BOARD,
  COIN_RADIUS,
  DT,
  PIECES,
  POCKETS,
  POCKET_INSET,
  POCKET_RADIUS,
  QUEEN,
  QUEEN_VALUE,
  STEPS_PER_FRAME,
  STRIKER,
  STRIKER_RADIUS,
  WHITE,
  aimOf,
  baselineY,
  carromPieces,
  carromShot,
  coin,
  coinsOf,
  lastShot,
  placeStriker,
  queenOwner,
  queenPending,
  simulate,
  // Ludo
  HOME,
  LAST_TRACK_STEP,
  ROLL,
  SAFE,
  START,
  TOKENS,
  TRACK,
  YARD,
  dieOf,
  lastCapture,
  lastRoll,
  lastTokenMoved,
  progressOf,
  tokenIndex,
  tokenMoves,
  trackSquare,
  gameReady,
  gameScore,
  isTurnOf,
  seatOf,
  // Connect Four
  COLUMNS,
  ROWS,
  connectFourAt,
  landing,
  winningRun,
  // Dots and Boxes
  CELLS,
  DOTS,
  LINES,
  boxLines,
  horizontal,
  vertical,
  // Reversi
  REVERSI_SIZE,
  reversiAt,
  flips,
  movesFor,
  // Tic-tac-toe
  lineWinner,
  winningLine,
} from './games';
export type {
  GameDefinition,
  GameId,
  GameRules,
  GameSeat,
  GameSession,
  GameState,
  Piece,
  RandomSource,
  ShotResult,
} from './games';

// --- Common ---

export interface ApiErrorBody {
  error: {
    code: string;
    message: string;
    requestId: string;
  };
}

export interface Paginated<T> {
  items: T[];
  /** Cursor to pass as `before` for the next (older) page. Null when exhausted. */
  nextCursor: string | null;
}

export interface LinkPreview {
  url: string;
  title: string | null;
  description: string | null;
  image: string | null;
  siteName: string | null;
  favicon: string | null;
}

// --- Auth ---

export interface RegisterRequest {
  email: string;
  username: string;
  password: string;
}

export interface LoginRequest {
  email: string;
  password: string;
}

export interface RefreshRequest {
  refreshToken: string;
}

export interface AuthTokens {
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
}

export type GlobalRole = 'USER' | 'ADMIN';

export interface PublicUser {
  id: string;
  email: string;
  username: string;
  displayName: string;
  avatarUrl: string | null;
  /**
   * The wide picture behind the name at the top of a profile, or null for the
   * flat accent band drawn before there was one.
   *
   * Not derivable from `avatarUrl` and therefore stored beside it: an avatar is
   * a square read at 32px in a member list, a cover is a 4:1 band read at
   * several hundred, and scaling one into the other gives a blurred crop of
   * somebody's face as a backdrop. See `COVER_ASPECT`.
   */
  coverUrl: string | null;
  /** Platform role, not server membership. ADMIN unlocks the admin panel. */
  role: GlobalRole;
  /** True for an account issued a generated password; it can do nothing else. */
  mustChangePassword: boolean;
  /** The line under the name on a profile card. See `ABOUT_MAX_LENGTH`. */
  about: string;
  /** Who may see when this account was last here. See `LastSeenVisibility`. */
  lastSeenVisibility: LastSeenVisibility;
  /**
   * This account's own disappearing-message window, in seconds, or null for
   * "keep everything".
   *
   * One-sided and personal: history older than the window is not returned to
   * this account on any of its devices, and every other participant's copy is
   * untouched. A server's own window outranks it, because that one deletes the
   * row rather than hiding it. See `DISAPPEARING_WINDOWS`.
   */
  messageTtlSeconds: number | null;
  createdAt: string;
}

export interface ChangePasswordRequest {
  currentPassword: string;
  newPassword: string;
}

// --- Forgotten passwords ---

export interface ForgotPasswordRequest {
  /** Email or username, the same field the login screen takes. */
  identifier: string;
}

/**
 * What the client should put on screen next, and nothing about whether the
 * account exists.
 *
 * `emailed` and `unknown` are deliberately indistinguishable in everything but
 * the word: both mean "we are not going to tell you whether that was a real
 * account", and both render the same sentence. The two that differ are the two
 * that have to: `reset` is an administrator having already authorised this one,
 * and `unavailable` is a deployment with no mail server, which is a fact about
 * the deployment rather than about the account.
 */
export type ForgotPasswordOutcome = 'emailed' | 'reset' | 'unavailable';

export interface ForgotPasswordResponse {
  outcome: ForgotPasswordOutcome;
  /**
   * Present only for `reset`: the single-use token that lets this client set a
   * new password now. It exists because an administrator put the account into
   * reset mode, which is the deployment's way back in when nothing can be
   * mailed. Expires, and is spent the first time it is used.
   */
  resetToken?: string;
  /** Present only for `unavailable`: what the operator wants people to be told. */
  message?: string;
}

export interface ResetPasswordRequest {
  token: string;
  newPassword: string;
}

// --- Username availability ---

export interface UsernameAvailability {
  username: string;
  available: boolean;
  /** Why not, when it is not: `taken` or `invalid`. */
  reason?: 'taken' | 'invalid';
}

/**
 * Who may see when an account was last here.
 *
 * `everyone` is the ceiling rather than the whole world: presence is already
 * scoped to the people who share a server or an accepted friendship with you,
 * so it means everyone who could already see your name. `friends` narrows that
 * to accepted friendships, and `nobody` switches the answer off.
 *
 * **`nobody` is reciprocal.** An account that hides when it was last here does
 * not get to read anybody else's either - WhatsApp's rule, and the only thing
 * that keeps the setting from being a one-way mirror everybody switches on the
 * moment it costs them nothing. It is enforced in `presence-service`; a client
 * hiding a value it was sent would not be hiding anything.
 *
 * It is not the same switch as `invisible`. Invisible hides that you are here
 * *now* and freezes the last-seen value where it stood; this decides who may
 * read that value at all, whichever status you are wearing.
 */
export type LastSeenVisibility = 'everyone' | 'friends' | 'nobody';

/** In the order the pickers draw them, widest first. */
export const LAST_SEEN_VISIBILITIES: LastSeenVisibility[] = ['everyone', 'friends', 'nobody'];

export interface UpdateAccountRequest {
  username?: string;
  displayName?: string;
  /** Storage URL of an uploaded picture; null clears it back to the initial. */
  avatarUrl?: string | null;
  /**
   * Storage URL of an uploaded cover picture; null clears it back to the flat
   * accent band. Must be one of ours for the same reason `avatarUrl` must: a
   * profile picture renders for everybody who can see the account, so an
   * arbitrary URL would be a beacon reporting who looked.
   */
  coverUrl?: string | null;
  /**
   * The line under the name on a profile card. Trimmed, and no longer than
   * `ABOUT_MAX_LENGTH`. An empty string is allowed and means the card draws no
   * line at all - which is different from never having changed it, where the
   * line is `DEFAULT_ABOUT`.
   */
  about?: string;
  /**
   * Who may see when this account was last here. Choosing `nobody` also stops
   * this account seeing anybody else's - the rule is reciprocal, and the
   * clients say so beside the option rather than letting it be discovered.
   */
  lastSeenVisibility?: LastSeenVisibility;
  /**
   * This account's personal disappearing window in seconds; null switches it
   * off. Must be one of `DISAPPEARING_WINDOWS`.
   */
  messageTtlSeconds?: number | null;
}

/**
 * The shape a cover picture is framed and stored at: width over height.
 *
 * One number, here, because three clients crop to it and a profile whose band
 * is 4:1 on a laptop and 3:1 on a phone is a picture that is composed for
 * neither. 4:1 is the band that survives being 660px wide on a settings page
 * and 360dp wide on a phone without the subject of the photograph leaving it -
 * a taller band eats the conversation below it on a phone, a flatter one stops
 * being a picture and becomes a stripe.
 */
export const COVER_ASPECT = 4;

/**
 * The widest a stored cover is kept, in pixels.
 *
 * Larger than an avatar's 512 because it is read wide rather than small, and
 * capped rather than unbounded because it is fetched by every client that
 * opens the profile and is not worth a megabyte. 1600x400 is a retina-sharp
 * band at every width any of the three clients draw one at.
 */
export const COVER_MAX_WIDTH = 1600;

/**
 * What a new account's about line says until its owner changes it.
 *
 * A default rather than an empty string, because an empty profile card is a
 * card that looks broken - and because the first thing anybody does with this
 * field is discover it exists by seeing somebody else's.
 */
export const DEFAULT_ABOUT = 'Hey, I’m on Between Us.';

/**
 * How long an about line may be, in characters.
 *
 * 140 is the length that still reads as one line under a heading at the widths
 * the profile card is drawn at on all three clients - a phone's card is about
 * 300dp across, and much past this the line becomes a paragraph and the card
 * stops being a card. WhatsApp settled on 139 for the same reason.
 *
 * Counted in code points rather than UTF-16 units wherever it is enforced, so a
 * line of emoji is measured the way somebody typing it counts.
 */
export const ABOUT_MAX_LENGTH = 140;

// --- OAuth login ---

/** Providers the operator has switched on, as the login screen sees them. */
export interface OAuthProviderSummary {
  provider: 'google' | 'github';
  label: string;
}

export interface OAuthExchangeRequest {
  /** One-time code handed to the redirect after the provider callback. */
  code: string;
  /**
   * The secret behind the challenge this sign-in was started with, when it was
   * started with one. Required for a flow that came back over a private-scheme
   * redirect, because that redirect is not exclusively ours - see
   * `APP_SCHEME` in the auth service.
   */
  verifier?: string;
}

/**
 * The scheme the mobile client's redirect uses.
 *
 * A phone has no loopback server to come back to, so the finished sign-in comes
 * back through a URL only the app is registered for. Android does not guarantee
 * that registration is exclusive - another app can claim the same scheme - so
 * this flow is bound to a secret the app keeps: see `OAuthExchangeRequest`.
 */
export const APP_REDIRECT_SCHEME = 'betweenus:';

// --- Admin panel ---

export interface AdminStatus {
  /** False until `pnpm admin:create` has been run; the panel explains that. */
  hasAdmin: boolean;
}

export interface AdminUser extends PublicUser {
  disabledAt: string | null;
  /** While this is in the future the account is in password-reset mode. */
  passwordResetUntil: string | null;
  /** Providers this account can also sign in with. */
  identities: string[];
  serverCount: number;
  lastSeenAt: string | null;
}

/**
 * One page of the directory, plus where the next one starts.
 *
 * A cursor rather than an offset: the list is ordered newest first and
 * registrations keep arriving, so paging by offset would show the same account
 * twice - once on page one, once again on page two after it was pushed down.
 */
export interface AdminUserPage {
  users: AdminUser[];
  /** Opaque; pass it back as `cursor`. Null when this was the last page. */
  nextCursor: string | null;
}

export interface AdminUserUpdate {
  role?: GlobalRole;
  disabled?: boolean;
  /**
   * True puts the account into reset mode: the next time somebody names it on
   * the forgot-password screen they are handed a single-use token and the
   * change-password form, without a mail server being involved. False cancels
   * a window that has not been used yet.
   */
  passwordReset?: boolean;
}

/** One thing an administrator did. Append-only; nothing edits or deletes it. */
export interface AdminAuditEntry {
  id: string;
  action: string;
  actorId: string | null;
  /** How the actor read at the time; null once their account is gone. */
  actorLabel: string | null;
  targetId: string | null;
  /** The subject as it read when it happened - it may not exist any more. */
  targetLabel: string | null;
  detail: Record<string, unknown> | null;
  createdAt: string;
}

export interface AdminAuditPage {
  entries: AdminAuditEntry[];
  nextCursor: string | null;
}

/** Never carries the secret itself - only whether one is stored. */
export interface AdminOAuthProvider {
  provider: 'google' | 'github';
  label: string;
  enabled: boolean;
  clientId: string;
  hasSecret: boolean;
  /** What to paste into the provider's console as the authorised callback. */
  callbackUrl: string;
}

export interface AdminOAuthProviderUpdate {
  enabled: boolean;
  clientId: string;
  /** Omitted means "keep the stored secret"; a value replaces it. */
  clientSecret?: string;
}

/**
 * The deployment's outgoing mail server, as the panel sees it. Never carries
 * the password - only whether one is stored, exactly like the OAuth secret.
 */
export interface AdminSmtpSettings {
  enabled: boolean;
  host: string;
  port: number;
  /** Implicit TLS on connect (465); false starts plain and upgrades (587). */
  secure: boolean;
  username: string;
  hasPassword: boolean;
  fromAddress: string;
  fromName: string;
}

export interface AdminSmtpUpdate {
  enabled: boolean;
  host: string;
  port: number;
  secure: boolean;
  username: string;
  /** Omitted means "keep the stored password"; a value replaces it. */
  password?: string;
  fromAddress: string;
  fromName: string;
}

/** What a test send did, so the panel can show the server's own refusal. */
export interface AdminSmtpTestResult {
  ok: boolean;
  /** The transport's message when it failed; absent when it did not. */
  error?: string;
}

export interface AdminSmtpTestRequest {
  /** Where to send it. Defaults to the administrator's own address. */
  to?: string;
}

// --- Admin: server health & storage ---

/**
 * Whether a dependency is answering, and how fast.
 *
 * Three states rather than a boolean, because "we could not reach it to ask"
 * and "it answered that it is unwell" want different reactions from whoever is
 * reading the panel at 3am, and collapsing them into `false` throws away the
 * only clue about which.
 */
export type AdminHealthState = 'up' | 'degraded' | 'down';

/** One dependency or service, as the panel draws it. */
export interface AdminComponentHealth {
  /** Stable key, e.g. `postgres`, `redis`, `chat-service`. */
  id: string;
  label: string;
  state: AdminHealthState;
  /** Round trip of the probe, in milliseconds. Null when it never answered. */
  latencyMs: number | null;
  /** Where the probe was sent. Never carries credentials - see `redactUrl`. */
  url: string | null;
  /** The failure in one sentence, when there is one. Never a stack trace. */
  error: string | null;
  /** Free-form extras the card shows as a definition list. */
  detail?: Record<string, string | number>;
}

/** What the host process itself reports about the machine it is on. */
export interface AdminRuntimeHealth {
  /** Seconds the reporting service has been up. */
  uptimeSeconds: number;
  /** Resident set size of the reporting process, in bytes. */
  memoryRssBytes: number;
  memoryHeapUsedBytes: number;
  memoryHeapTotalBytes: number;
  /** 1/5/15-minute load averages. Zeroes on Windows, which reports none. */
  loadAverage: [number, number, number];
  cpuCount: number;
  nodeVersion: string;
  platform: string;
  /** Deployment version, from the package or the release tag. */
  appVersion: string | null;
}

/** One Postgres table, biggest first. */
export interface AdminTableSize {
  table: string;
  /** Rows, from the planner's estimate - exact counts lock the table. */
  rowEstimate: number;
  /** Heap plus indexes plus TOAST, in bytes. */
  totalBytes: number;
  indexBytes: number;
}

export interface AdminDatabaseStorage {
  /** `pg_database_size` of the live database, in bytes. */
  totalBytes: number;
  /** Largest tables, already sorted descending. */
  tables: AdminTableSize[];
  /** Open backends, and what the server will allow. */
  connections: number;
  maxConnections: number;
  /** Server version string, e.g. `16.3`. */
  version: string | null;
}

/**
 * Where uploads live and how much of it they occupy.
 *
 * `driver` decides which of the two sizes is authoritative: a local disk can be
 * measured directly, an S3 bucket cannot be walked cheaply, so there the sum of
 * `Attachment.size` is the only honest number and `diskBytes` stays null.
 */
export interface AdminMediaStorage {
  driver: 'local' | 's3';
  /** Sum of every stored object's recorded size, in bytes. */
  recordedBytes: number;
  /** Measured on disk. Null for S3, where walking the bucket is not free. */
  diskBytes: number | null;
  /** Free space on the volume holding the uploads. Null for S3. */
  diskFreeBytes: number | null;
  attachmentCount: number;
  /** Attachments, split by broad content type. */
  byKind: Array<{ kind: string; count: number; bytes: number }>;
  /** Bucket name or the absolute directory, whichever applies. */
  location: string | null;
}

/**
 * What has moved, over a window.
 *
 * Call traffic is peer-to-peer and never touches this host - it is the clients'
 * own reported totals from `CallSession`, which is the only place it is
 * knowable at all. Attachment bytes are what this deployment actually served.
 */
export interface AdminBandwidth {
  /** Days the window covers. */
  windowDays: number;
  callBytes: number;
  callBytesSent: number;
  callBytesReceived: number;
  callSessions: number;
  attachmentBytes: number;
  attachmentCount: number;
  /** Oldest first, one entry per day, for the trend line. */
  daily: Array<{ date: string; callBytes: number; attachmentBytes: number }>;
}

/** A realtime endpoint, and how many sockets are on it right now. */
export interface AdminLiveEndpoint {
  id: string;
  label: string;
  /** The public URL a client dials, e.g. `wss://host/ws/chat`. */
  url: string;
  connections: number;
  state: AdminHealthState;
}

/** Who is connected, across the realtime surfaces. */
export interface AdminLiveConnections {
  /** Distinct users presence believes are online. */
  onlineUsers: number;
  /** Sockets, which exceeds users whenever somebody has two clients open. */
  totalSockets: number;
  /** Voice/video calls with at least one participant. */
  activeCalls: number;
  activeCallParticipants: number;
  /** Remote-desktop sessions currently relayed. */
  activeRemoteSessions: number;
  endpoints: AdminLiveEndpoint[];
}

/** Everything the Health & storage screen draws, in one response. */
/**
 * What one relay URL answered when asked for an allocation.
 *
 * `up` means the relay accepted the deployment's own credential and handed back
 * an address it would forward media through - the only evidence that actually
 * predicts a relayed call working. `unprobed` is a TLS or TCP listener, which
 * is checked with Trickle ICE rather than guessed at here.
 */
export interface RelayProbeResult {
  url: string;
  state: 'up' | 'down' | 'unprobed' | 'invalid';
  /** Round trip of the full allocate exchange, in milliseconds. */
  latencyMs: number | null;
  /** `XOR-RELAYED-ADDRESS`: where this relay would forward media. */
  relayedAddress: string | null;
  /** `XOR-MAPPED-ADDRESS`: how the relay sees the service that asked. */
  mappedAddress: string | null;
  /** The failure in one sentence, with what to change. Never a stack trace. */
  error: string | null;
}

/**
 * The deployment's TURN relay, as the panel draws it.
 *
 * Reported by `call-service` rather than by the service answering the admin
 * API, because `call-service` is what actually hands ICE to clients. A status
 * assembled from a second copy of `TURN_URLS` could show green while clients
 * were being given something else, which is the class of bug that removing the
 * hosted minting path was meant to end.
 */
export interface AdminRelayHealth {
  /** False when no relay is configured, which is a valid deployment. */
  configured: boolean;
  /** The username clients are given. The credential is never returned. */
  username: string | null;
  /** One entry per URL in `TURN_URLS`, probed in order. */
  probes: RelayProbeResult[];
  /** Worst state across `probes`; `up` when nothing is configured to fail. */
  state: AdminHealthState;
  /**
   * Why `call-service` could not be asked at all, when that is what happened.
   * Distinct from a relay that answered badly - this is the reporter being
   * unreachable, not the relay.
   */
  error: string | null;
}

export interface AdminServerHealth {
  /** When the snapshot was taken, ISO 8601. */
  at: string;
  /** Worst state across `components` - what the header badge shows. */
  overall: AdminHealthState;
  components: AdminComponentHealth[];
  runtime: AdminRuntimeHealth;
  database: AdminDatabaseStorage;
  media: AdminMediaStorage;
  bandwidth: AdminBandwidth;
  live: AdminLiveConnections;
  /** The TURN relay, live-probed. See `AdminRelayHealth`. */
  relay: AdminRelayHealth;
}

export interface AuthResponse extends AuthTokens {
  user: PublicUser;
}

/** Decoded access-token payload. Services trust this only after signature check. */
export interface JwtAccessPayload {
  sub: string;
  email: string;
  username: string;
  type: 'access';
  iat?: number;
  exp?: number;
}

export interface JwtRefreshPayload {
  sub: string;
  jti: string;
  type: 'refresh';
  iat?: number;
  exp?: number;
}

// --- Servers ---

export type ServerRole = 'OWNER' | 'ADMIN' | 'MODERATOR' | 'MEMBER' | 'GUEST';

export interface Server {
  id: string;
  name: string;
  slug: string;
  iconUrl: string | null;
  ownerId: string;
  /**
   * How long a message sent in this server's channels lives, in seconds, or
   * null for "for ever".
   *
   * Binding on every member and enforced by deleting the row, which is what
   * makes it outrank anybody's personal window: a member may choose to see
   * less than the server keeps, never more. See `DISAPPEARING_WINDOWS`.
   */
  messageTtlSeconds: number | null;
  createdAt: string;
}

export interface ServerWithRole extends Server {
  role: ServerRole;
  /** What the caller may do here, role defaults and overrides already applied. */
  permissions: string[];
}

export interface CreateServerRequest {
  name: string;
}

export interface UpdateServerRequest {
  name?: string;
  iconUrl?: string | null;
  /**
   * The server's disappearing window in seconds; null switches it off. Needs
   * MANAGE_SERVER, and must be one of `DISAPPEARING_WINDOWS`.
   */
  messageTtlSeconds?: number | null;
}

/** An invite as whoever manages the server sees it. */
export interface ServerInvite {
  code: string;
  serverId: string;
  createdById: string | null;
  /** Null for an invite with no expiry - a choice, not the only option. */
  expiresAt: string | null;
  /** Null for unlimited. */
  maxUses: number | null;
  uses: number;
  revokedAt: string | null;
  createdAt: string;
  /**
   * Whether it would work right now. Derived, so a client never has to
   * re-implement "expired or revoked or spent" and get one of the three wrong.
   */
  active: boolean;
}

export interface CreateServerInviteRequest {
  /** Null or absent for an invite that never expires. */
  expiresInHours?: number | null;
  /** Null or absent for unlimited uses. */
  maxUses?: number | null;
}

/**
 * What an invite is worth accepting, before it is accepted.
 *
 * A link used to join the moment it was opened, which is the one thing an
 * invite should never do: the person following it has no idea whose server it
 * is until they are already in it. So a code is looked up first and answered
 * with enough to decide - whose server, how big it is, and how much of it is
 * awake.
 *
 * It is deliberately thin. Anyone holding a code can ask for this, so it says
 * what the invite itself already promises and nothing more: no member list, no
 * channels, no ids belonging to anyone.
 */
export interface InvitePreview {
  code: string;
  serverId: string;
  name: string;
  iconUrl: string | null;
  memberCount: number;
  /**
   * How many of those members are online, or null when presence could not be
   * reached. Null rather than 0: "nobody is here" and "nobody could be asked"
   * are different things, and a card that shows the second as the first is
   * lying about an empty server.
   */
  onlineCount: number | null;
  /** Already in. The link then opens the server rather than joining it. */
  member: boolean;
}

export interface JoinServerRequest {
  /** An invite code. The server's slug is not one, and no longer opens a door. */
  code: string;
}

/**
 * One of a server's own emoji.
 *
 * The name is what people type between colons and the URL is an ordinary
 * picture upload - public, like every avatar, because an `<img>` cannot carry
 * an Authorization header and an emoji is drawn a hundred times a screen.
 */
export interface ServerEmoji {
  id: string;
  serverId: string;
  /** Lowercase letters, digits and underscores. `:name:` is how it is written. */
  name: string;
  url: string;
  /** A GIF or an animated WebP. Recorded rather than sniffed by every client. */
  animated: boolean;
  createdById: string | null;
  createdAt: string;
}

/** What the name and picture rules are, so a client can say no before the server does. */
export const EMOJI_NAME_PATTERN = /^[a-z0-9_]{2,32}$/;

/**
 * How many a server may hold.
 *
 * Not a licensing tier - a picker is a grid somebody has to look through, and
 * past a couple of hundred it stops being one. Raise it here if a deployment
 * disagrees; nothing else depends on the number.
 */
export const MAX_SERVER_EMOJI = 200;

export interface CreateServerEmojiRequest {
  name: string;
  /** Storage URL of a picture already uploaded through `/api/v1/uploads/picture`. */
  url: string;
  animated?: boolean;
}

export interface ServerMember {
  id: string;
  userId: string;
  username: string;
  displayName: string;
  avatarUrl: string | null;
  role: ServerRole;
  /** Effective permissions: the role's defaults plus grants, minus denials. */
  permissions: string[];
  /** Held beyond the role. Shown as the toggles an administrator switched on. */
  grantedPermissions: string[];
  /** Withheld despite the role. Deny wins over grant. */
  deniedPermissions: string[];
  /** Ids of the custom roles this member holds, highest rank first. */
  roleIds: string[];
  /** From the highest-ranked custom role that has one; null if none does. */
  colour: string | null;
  /** The line under the name on this member's profile card. See `UserSummary`. */
  about: string;
  /** The band behind the name when this member's full profile is opened. */
  coverUrl: string | null;
  joinedAt: string;
}

/**
 * A role a server invented for itself.
 *
 * Additive on top of the five built-in `ServerRole` rungs rather than replacing
 * them: the built-ins are the hierarchy - who may edit whom, who may hand out
 * what - and a hierarchy anyone can extend is a hierarchy anyone can climb.
 */
export interface ServerCustomRole {
  id: string;
  serverId: string;
  name: string;
  /** `#rrggbb`, or null for the default colour. */
  colour: string | null;
  /** Higher is further up the list. Ordering only; it grants nothing. */
  rank: number;
  permissions: string[];
  /** How many members hold it. */
  memberCount: number;
}

export interface CreateServerRoleRequest {
  name: string;
  colour?: string | null;
  rank?: number;
  permissions?: string[];
}

/** Every field is optional; only what is sent is changed. */
export type UpdateServerRoleRequest = Partial<CreateServerRoleRequest>;

/**
 * Adds someone to a server directly, by the username they can be told. The
 * alternative - handing out the slug and waiting - cannot be done from the
 * members screen, which is where an administrator is already standing.
 */
export interface AddServerMemberRequest {
  username: string;
  /**
   * Let them read what was said before they arrived.
   *
   * Absent and false mean the same thing and are the default: a newcomer holds
   * no earlier channel key, nobody offers them one, and the conversation before
   * this moment stays sealed. Setting it records the opposite decision on the
   * membership, which the key directory then acts on - see `E2EE.md`.
   */
  shareHistory?: boolean;
}

/** Every field is optional; only what is sent is changed. */
export interface UpdateServerMemberRequest {
  role?: ServerRole;
  grantedPermissions?: string[];
  deniedPermissions?: string[];
  /** Replaces the whole set of custom roles this member holds. */
  roleIds?: string[];
}

// --- Channels ---

export type ChannelType = 'TEXT' | 'VOICE' | 'DM';

export interface Channel {
  id: string;
  /** Null for a direct message, which belongs to its two participants. */
  serverId: string | null;
  name: string;
  type: ChannelType;
  topic: string | null;
  /** Visible only to the users on its allowlist - see `ChannelMember`. */
  isPrivate: boolean;
  createdAt: string;
}

export interface CreateChannelRequest {
  serverId: string;
  name: string;
  type?: ChannelType;
  isPrivate?: boolean;
  /**
   * Who may see a private channel. The creator is always added, so an empty
   * list makes a channel only its creator can open.
   */
  memberIds?: string[];
}

export interface UpdateChannelRequest {
  name?: string;
  topic?: string | null;
}

/** One user allowed into a private channel. */
export interface ChannelMember {
  userId: string;
  username: string;
  displayName: string;
  avatarUrl: string | null;
  addedAt: string;
}

/**
 * Replaces the allowlist wholesale. The caller is always kept on it, because
 * removing yourself from a private channel you are editing locks you out of the
 * screen you are standing on.
 */
export interface SetChannelMembersRequest {
  userIds: string[];
}

// --- Webhooks ---
//
// A URL an outside system POSTs to in order to say something in a channel:
// Discord's shape, because it is the one every CI runner, alerting stack and
// "send to chat" integration already speaks. One opaque URL carrying its own
// authority, a JSON body with a `content` field, and no account or bot
// framework anywhere near it - a webhook that needed a client library would not
// be reachable from the `curl` in somebody's deploy script, which is the whole
// reason to have one.
//
// **A webhook body is stored and delivered in the clear.** It is the single
// documented exception to this app's sealed-envelope rule, and it is made
// visible rather than hidden: `Message.kind` is `'WEBHOOK'`, every client draws
// the row with a badge saying so, and the channel says a webhook is attached.
// The alternative was handing a channel key to a shell script, which is handing
// away the channel. See `Webhook` in the Prisma schema, and
// `docs/docs/services/webhooks.md`.

/** How a webhook is drawn on a message it posted. */
export interface MessageWebhook {
  /** Null once the webhook has been deleted; the messages it sent stay. */
  id: string | null;
  /**
   * The name to draw over the author's.
   *
   * Frozen onto the message rather than only read through the relation, so a
   * deleted webhook's history still says who said it instead of collapsing on
   * to the account that happened to create it.
   */
  name: string;
  avatarUrl: string | null;
}

/** A webhook as its channel's settings list it. Never carries the token. */
export interface WebhookSummary {
  id: string;
  channelId: string;
  name: string;
  avatarUrl: string | null;
  /** Who opened it. Shown so a list of robots still has a person beside each. */
  createdBy: UserSummary;
  /** Null until something has posted through it - the first thing anybody asks. */
  lastUsedAt: string | null;
  createdAt: string;
}

/**
 * A webhook plus the one thing that is never shown again.
 *
 * The token is stored as a SHA-256 hash, so this response and the one from
 * rotating are the only two moments it exists in readable form. Discord keeps
 * its webhook URLs re-readable; a token a database can be asked for is a token
 * a database dump hands over, and losing this one costs a rotation rather than
 * an account.
 */
export interface WebhookWithToken extends WebhookSummary {
  /** The full URL to hand to the other system. Shown once. */
  url: string;
}

export interface CreateWebhookRequest {
  channelId: string;
  /** 1-80 characters. A label on a robot, not a username: it need not be unique. */
  name: string;
  /** An uploaded picture, or omitted for the initial drawn from `name`. */
  avatarUrl?: string | null;
}

export interface UpdateWebhookRequest {
  name?: string;
  avatarUrl?: string | null;
}

/**
 * What an outside system POSTs. Discord's field names, deliberately, so an
 * integration already pointed at Discord works by changing only the URL.
 */
export interface ExecuteWebhookRequest {
  /** The message. Required unless `embeds` carries the whole thing. */
  content?: string;
  /**
   * Accepted and **ignored**, and the response says so.
   *
   * Discord lets one URL post under several names. Carrying that would mean a
   * column on every message to hold the name, where making a second webhook is
   * a button - so the trade is one row of UI against a schema change, and the
   * button wins. The message posts under the webhook's own name.
   */
  username?: string;
  /**
   * Accepted and **ignored**, and the response says so.
   *
   * Discord fetches whatever URL is given here. Doing that would make every
   * client fetch an arbitrary host when it draws a message - a beacon
   * reporting who read the channel - and would make this service fetch it too.
   * The webhook's own stored picture is used instead.
   */
  avatar_url?: string;
  /**
   * Discord's embed objects, rendered as the subset this app has a use for:
   * a title, a description, a colour bar, a URL and fields. Anything else in
   * the object is ignored rather than refused, because integrations send a lot
   * of Discord-specific furniture and refusing it would break them wholesale.
   */
  embeds?: WebhookEmbed[];
}

/** The part of a Discord embed this app draws. */
export interface WebhookEmbed {
  title?: string;
  description?: string;
  url?: string;
  /** Discord sends a decimal integer, e.g. `5814783` for `#58b9ff`. */
  color?: number;
  fields?: Array<{ name: string; value: string; inline?: boolean }>;
  footer?: { text: string };
  timestamp?: string;
}

/** How long a webhook name may be. Discord's limit, for the same reason. */
export const WEBHOOK_NAME_MAX_LENGTH = 80;

/**
 * The longest body a webhook may post, in characters.
 *
 * The same ceiling a person's message has before the client turns it into a
 * text file. A webhook has no client to do that for it, so this is a refusal
 * rather than a conversion, and the error says which limit was hit.
 */
export const WEBHOOK_CONTENT_MAX_LENGTH = 2000;

/** How many embeds one webhook message may carry. Discord's number. */
export const WEBHOOK_EMBED_MAX = 10;

// --- Friends and direct messages ---

/** The public face of an account: what a search result or a DM header shows. */
export interface UserSummary {
  id: string;
  username: string;
  displayName: string;
  avatarUrl: string | null;
  /**
   * The wide picture behind the name at the top of a profile, or null for the
   * flat accent band drawn before there was one.
   *
   * Not derivable from `avatarUrl` and therefore stored beside it: an avatar is
   * a square read at 32px in a member list, a cover is a 4:1 band read at
   * several hundred, and scaling one into the other gives a blurred crop of
   * somebody's face as a backdrop. See `COVER_ASPECT`.
   */
  coverUrl: string | null;
  /**
   * The line under the name on a profile card.
   *
   * Carried on the summary rather than fetched per person when a card opens:
   * a card that appears on hover has no room for a spinner, and 140 characters
   * beside a name that is already being sent is cheaper than the request that
   * would otherwise fetch it.
   */
  about: string;
}

export type FriendshipStatus = 'PENDING' | 'ACCEPTED';

export interface Friend {
  user: UserSummary;
  status: FriendshipStatus;
  /**
   * Who asked, seen from the caller's side. Null once the friendship is
   * accepted - by then it does not matter, and the UI stops asking.
   */
  direction: 'incoming' | 'outgoing' | null;
  since: string;
}

export interface SendFriendRequestRequest {
  /** Username rather than id: it is what the person can actually be told. */
  username: string;
}

/** A direct message channel, named by the person on the other end of it. */
export interface DirectChannel {
  channelId: string;
  participant: UserSummary;
  createdAt: string;
}

export interface OpenDirectChannelRequest {
  userId: string;
}

/**
 * What to clear. One conversation, or - with no `channelId` - every one of
 * them.
 *
 * The same endpoint for both, because they are the same act at two scopes and
 * a client should not have to know which of two routes it wants. The scope is
 * the argument, which is also what makes the answer able to say which happened.
 */
export interface ClearChatsRequest {
  /** Omitted or null clears every conversation this account can see. */
  channelId?: string | null;
}

/**
 * What `POST /api/v1/messages/clear` answers with: the instant everything at or
 * before it stopped being visible to this account, and where.
 */
export interface ClearChatsResponse {
  clearedAt: string;
  /** The conversation that was cleared, or null when all of them were. */
  channelId: string | null;
}

// --- Blocking ---

/** Somebody this account has blocked, as the block list shows them. */
export interface BlockedUser {
  user: UserSummary;
  blockedAt: string;
}

export interface BlockUserRequest {
  userId: string;
}

// --- Status (phase 30) ---
//
// A post that expires after 24 hours and is seen by accepted friends. Not a
// message: no channel, no conversation, and an audience that is a set rather
// than a room. See `model Status` in the Prisma schema.
//
// End-to-end encrypted, like everything under "Messages" above, and sealed the
// only way a post with no channel can be: the audience is frozen at post time.
// The author mints one key per post, seals the caption and the media under it,
// and wraps that key once per *device* of every friend it had when it posted.
//
// That is not a compromise, it is the rule the feature wanted. Somebody who
// becomes your friend tomorrow does not get yesterday's post - the same thing
// every app with this feature does, and the same thing a channel does when
// somebody joins it. The server holds ciphertext and a table of wraps it
// cannot open, and "who may read this" stops being a question it answers.

export type StatusKind = 'PHOTO' | 'VIDEO' | 'TEXT';

/** How long a post lives. Twenty-four hours, which is what the word means. */
export const STATUS_TTL_MS = 24 * 60 * 60 * 1000;

/** The caption under a photo, or the whole of a TEXT status, as typed. */
export const STATUS_CAPTION_MAX_LENGTH = 700;

/**
 * What the server will take for a caption, which is the sealed envelope rather
 * than the words.
 *
 * Base64 of AES-GCM over 700 UTF-8 characters, plus the envelope's own keys,
 * lands under 4 KB in the worst case. The server cannot count characters in a
 * ciphertext, so this is the only cap it can enforce - the readable one above
 * is enforced by the composer, where the words still exist.
 */
export const STATUS_CAPTION_SEALED_MAX_LENGTH = 4096;

/**
 * How long a photo or a text status is held on screen before the viewer moves
 * on, in milliseconds. A video runs for its own length instead.
 *
 * Five seconds is WhatsApp's step and Instagram's, and it is the number every
 * person using this has already been trained on.
 */
export const STATUS_PHOTO_MS = 5000;

/**
 * How much of a video a status plays, in milliseconds.
 *
 * A cap on playback rather than on the file: the clip is stored whole and the
 * viewer stops after this, which is what the progress bar is timed against.
 * Re-encoding in the client to cut the file down would mean a video encoder in
 * every client to save a few megabytes on a post that is deleted within a day.
 *
 * Thirty seconds is the length every app with this feature settled on, and
 * long enough that almost nothing is cut.
 */
export const STATUS_VIDEO_MAX_MS = 30_000;

/**
 * The colours a TEXT status can be drawn on.
 *
 * A fixed palette rather than a colour picker: it is the whole visual identity
 * of a text post, every one of these is legible under white text, and a picker
 * is how you get white-on-yellow. Stored as the hex string, so a client that
 * does not know a value still renders it.
 */
export const STATUS_BACKGROUNDS = [
  '#075E54',
  '#128C7E',
  '#1F6FEB',
  '#6D28D9',
  '#BE185D',
  '#B45309',
  '#334155',
  '#0F172A',
] as const;

/** One post, as everybody who can see it reads it. */
export interface StatusEntry {
  id: string;
  authorId: string;
  kind: StatusKind;
  /**
   * Where the photo or video is, rooted at `/api/v1/uploads/status/...`, or
   * null for TEXT. It needs the caller's token like any attachment does: it is
   * fetched as bytes and turned into an object URL, never put in a bare `src`.
   */
  mediaUrl: string | null;
  /** The IV the media was sealed with. Null for TEXT, and for nothing else. */
  mediaIv: string | null;
  /**
   * What the bytes are once opened - `image/jpeg`, `video/mp4`. Sent by the
   * author and stored in the clear: the server holds ciphertext and cannot
   * sniff it, and a `<video>` will not decode a blob with no type on it.
   */
  mediaType: string | null;
  /** The sealed caption, as an `EncryptedEnvelope`. Opened by the client. */
  caption: string | null;
  /** The colour a TEXT status is drawn on. Null for media. */
  background: string | null;
  /** A video's length in milliseconds; null for a photo or text. */
  durationMs: number | null;
  createdAt: string;
  expiresAt: string;
  /** Whether the caller has opened this one. Always true for your own. */
  seen: boolean;
  /** How many people opened it. Only filled in on your own posts; else null. */
  viewCount: number | null;
  /**
   * This post's key, wrapped for the reader's own devices - one entry per
   * machine they had signed in when the author posted.
   *
   * A list rather than one entry, and for the same reason `ChannelKeysResponse`
   * is: the server cannot tell which of somebody's machines is asking without
   * trusting a device id it was handed, so it sends every copy addressed to the
   * account and the client keeps whichever its private half opens.
   *
   * Empty means nothing was addressed to this account: the friendship is newer
   * than the post, or the device is. Both draw as a post that cannot be opened
   * rather than as an error, because neither is one.
   */
  keys: StatusKeyEntry[];
}

/**
 * One post's key, sealed for one device.
 *
 * The same shape as a `ChannelKeyEntry` minus the epoch - a status has exactly
 * one key and never rotates, because it is gone in a day.
 */
export interface StatusKeyEntry {
  recipientUserId: string;
  recipientDeviceId: string;
  /** The author's ECDH public key (JWK): the recipient derives against it. */
  senderPublicKey: string;
  wrappedKey: string;
  iv: string;
}

/**
 * One person's live posts, which is the unit every screen actually draws: a
 * ring is per person, a tap opens their whole run, and the count under a name
 * is the length of this list.
 */
export interface StatusFeedEntry {
  author: UserSummary;
  statuses: StatusEntry[];
  /** The newest post's time - what the list is ordered by. */
  latestAt: string;
  /** True while any post in the run is unopened, which is what draws the ring. */
  unseen: boolean;
}

/**
 * The whole tray: your own run, and everybody else's.
 *
 * `mine` is separate rather than the first row of `others` because it is drawn
 * differently everywhere - it is the add button when it is empty, it shows view
 * counts, and it can be deleted from.
 */
export interface StatusFeed {
  mine: StatusEntry[];
  others: StatusFeedEntry[];
}

/**
 * Posting. The media, where there is any, travels in the same request as its
 * caption: a two-step upload leaves an orphaned blob every time somebody
 * changes their mind between the two, and there is nothing here big enough to
 * need the multipart path.
 */
export interface CreateStatusRequest {
  kind: StatusKind;
  /** The sealed caption - an `EncryptedEnvelope`, not the words. */
  caption?: string;
  background?: string;
  durationMs?: number;
  /** The IV the media was sealed with. Required with a file, refused without. */
  mediaIv?: string;
  /** What the sealed bytes are once opened. Stored in the clear; see `StatusEntry`. */
  mediaType?: string;
  /** Which device did the sealing. Every wrap in the bundle came from it. */
  senderDeviceId: string;
  /**
   * The post's key, wrapped once per device that may read it - every device of
   * every friend at this moment, and the author's own. This list *is* the
   * audience: a friendship made after it was written adds nothing to it.
   */
  keys: StatusKeyEntry[];
}

/** Somebody who opened your post, newest first. */
export interface StatusViewer {
  user: UserSummary;
  viewedAt: string;
}

// --- Messages ---

export interface MessageAuthor {
  id: string;
  username: string;
  displayName: string;
  avatarUrl: string | null;
}

/**
 * What a row in a conversation is.
 *
 * `USER` is something somebody wrote, and `content` is ciphertext. Anything
 * else was written by the server, carries an empty `content`, and is drawn from
 * the kind and the author alone - the wording belongs to the client, so it is
 * in the reader's language rather than in whatever the service was written in.
 */
export type MessageKind = 'USER' | 'MEMBER_JOIN' | 'WEBHOOK';

/**
 * Which kinds of row actually carry a body.
 *
 * An allowlist rather than `kind !== 'USER'`, and the difference matters. That
 * test meant "anything the server wrote", which was true while `MEMBER_JOIN`
 * was the only other kind - and silently became "a webhook message has no
 * text" the moment a second one existed. A row that carries words is not the
 * same question as a row a person wrote.
 *
 * Still an allowlist and not a denylist, so the original property survives: a
 * client that has never heard of some future kind draws nothing for it rather
 * than drawing the wrong thing.
 */
export const BODIED_MESSAGE_KINDS: MessageKind[] = ['USER', 'WEBHOOK'];

/** Whether this row has a body to open at all. See `BODIED_MESSAGE_KINDS`. */
export function hasBody(kind: MessageKind | undefined): boolean {
  // Absent means a build older than the column, where every row was a person's.
  return kind === undefined || BODIED_MESSAGE_KINDS.includes(kind);
}

export interface Message {
  id: string;
  channelId: string;
  /** Absent on a message from a build older than the column; read it as `USER`. */
  kind?: MessageKind;
  content: string;
  author: MessageAuthor;
  /**
   * Present exactly when `kind` is `'WEBHOOK'`. What the client draws the name
   * and picture from - `author` is the account that created the webhook, which
   * is not who the row is from, and drawing that would attribute a build
   * server's output to a person.
   *
   * Its presence is also what turns on the "not encrypted" badge: a webhook
   * body is plaintext because the poster holds no channel key. See
   * `WebhookSummary`.
   */
  webhook?: MessageWebhook;
  createdAt: string;
  editedAt: string | null;
  /**
   * Set once the message is deleted. The row survives as a tombstone with an
   * empty body, so a conversation reads as "this was here and is gone" instead
   * of silently re-flowing around a hole.
   */
  deletedAt: string | null;
  /** Whoever deleted it, when that was not the author. */
  deletedBy: MessageAuthor | null;
  pinnedAt: string | null;
  /** One entry per distinct emoji. */
  reactions: MessageReactionSummary[];
  /**
   * When this message stops existing, stamped from the server's disappearing
   * window as it was sent. Null means it stays until somebody deletes it.
   *
   * Clients draw a countdown from it and drop their own cached copy when it
   * passes, so a device that has been offline since before the window closed
   * does not show what the server has already destroyed.
   */
  expiresAt: string | null;
  /** A one-time message: each recipient may open its media once. */
  viewOnce: boolean;
  /**
   * Who has already spent their look, by user id.
   *
   * A list rather than a single "has it been opened" stamp, because a one-time
   * message holds one look per person who can see it. The single stamp meant
   * the first person to open one in a channel destroyed it for everybody else,
   * who were then shown "Opened" for something they had never seen.
   *
   * Every client works out its own state from this - `viewedBy.includes(me)` -
   * which is why it is a list of ids and not a per-caller boolean: the same
   * message object is broadcast to every subscriber, so a flag computed for
   * whoever caused the change would be wrong for all the others. It is the
   * same reasoning as `MessageReactionSummary.userIds`.
   *
   * The message is destroyed, and this stops mattering, once it covers
   * everyone who could see it apart from the author.
   */
  viewedBy: string[];
}

/**
 * One emoji on one message, grouped across the people who chose it.
 *
 * It carries the user ids rather than a count and a "mine" flag, because the
 * same object is broadcast to everyone: a flag computed for whoever caused the
 * change would be wrong for every other recipient. The client counts the list
 * and looks for itself in it.
 */
export interface MessageReactionSummary {
  emoji: string;
  userIds: string[];
}

export interface CreateMessageRequest {
  channelId: string;
  content: string;
  /**
   * Storage keys of the blobs this message carries, so the server can tie them
   * to it and remove them when it is deleted. The manifest that names them is
   * inside `content` and unreadable to any service, so a client that wants its
   * files swept has to say which they are; the keys alone reveal nothing the
   * upload route did not already know.
   */
  attachmentKeys?: string[];
  /**
   * Send this as a one-time message. Its media may be opened once by somebody
   * other than the author, and that opening destroys the row and its blobs.
   *
   * Outside `content` because the server has to act on it, and a server that
   * cannot read the body cannot be told by the body.
   */
  viewOnce?: boolean;
}

/** Replaces the body; the author only, and it stamps `editedAt`. */
export interface UpdateMessageRequest {
  content: string;
}

/** Emoji as a literal character (or a short sequence), never a shortcode. */
export interface ReactToMessageRequest {
  emoji: string;
}

/**
 * The disappearing windows anything may be set to, in seconds.
 *
 * A fixed list rather than a free number, and both ends check against it. A
 * free number is a footgun in both directions: a window of three seconds is a
 * conversation nobody can read, and a window of ten years is a retention
 * policy pretending to be a privacy feature. These are the durations every
 * other messenger settled on, and a short list keeps the picker a picker
 * instead of a form.
 */
export const DISAPPEARING_WINDOWS = [3600, 28800, 86400, 604800] as const;

export type DisappearingWindow = (typeof DISAPPEARING_WINDOWS)[number];

/** Whether a window came off the list. Null - "off" - is always allowed. */
export function isDisappearingWindow(seconds: number | null | undefined): boolean {
  return (
    seconds === null ||
    seconds === undefined ||
    (DISAPPEARING_WINDOWS as readonly number[]).includes(seconds)
  );
}

/** What a window is called on screen. One spelling, so every client agrees. */
export function disappearingWindowLabel(seconds: number | null): string {
  switch (seconds) {
    case null:
      return 'Off';
    case 3600:
      return '1 hour';
    case 28800:
      return '8 hours';
    case 86400:
      return '24 hours';
    case 604800:
      return '7 days';
    default:
      return `${seconds}s`;
  }
}

/**
 * What an avatar or a server icon URL is allowed to look like. It has to be an
 * object this deployment stored: a picture renders in every client that can see
 * the account or the server, so an arbitrary URL would be a beacon reporting
 * back who looked at it, and an http one would be a mixed-content warning too.
 *
 * Either a path served by a service (`/api/v1/uploads/pictures/...`) or an
 * https bucket URL - the operator chooses the host, so the check is on the
 * shape and on the `pictures/` prefix the upload route generates.
 */
export const UPLOADED_PICTURE_URL = /^(\/|https:\/\/)[^\s]*\/pictures\/[^\s]+$/;

// --- Attachments ---
//
// An attachment is a file encrypted under the channel key and uploaded on its
// own; what identifies it - the name, the real content type, the nonce that
// opens it - travels inside the encrypted message body, never as a column. The
// server therefore stores an opaque blob and a ciphertext, and knows neither
// what the file is called nor what it contains.

/** What the upload routes answer with, whatever driver stored the bytes. */
export interface UploadedObject {
  key: string;
  size: number;
  contentType: string;
  url: string;
}

/** Opened by `POST /uploads/multipart`; the ticket is the whole session. */
export interface StartMultipartResponse {
  ticket: string;
  /** Largest body one part may have, so the client can size its chunks. */
  maxPartBytes: number;
}

export interface UploadedPart {
  partNumber: number;
  etag: string;
}

export interface MessageAttachment {
  /** Storage key of the ciphertext. */
  key: string;
  /** Where the ciphertext is fetched from. */
  url: string;
  /** The name the sender's file had. */
  name: string;
  /** The real content type, once decrypted. */
  contentType: string;
  /** Plaintext size in bytes, before encryption. */
  size: number;
  /** Base64 AES-GCM nonce for the file itself. */
  iv: string;
  /** Channel-key generation the file was sealed under. */
  epoch: number;
  /** Set when the plaintext was gzipped before it was encrypted. */
  gzip?: boolean;
  /** Pixel size of an image, so the layout can be reserved before it loads. */
  width?: number;
  height?: number;
  /** Set when the client turned an over-long message into this text file. */
  overflow?: boolean;
  /**
   * How long an audio or video attachment runs, in seconds.
   *
   * Carried so a voice message can say "0:07" before a byte of it has been
   * fetched. Without it the player has to download and decode the whole file
   * to fill in a label, which is the one number somebody wants *before*
   * deciding to listen.
   */
  duration?: number;
  /**
   * The shape of a voice message, as bar heights from 0 to 1.
   *
   * Measured on the sender while it was being recorded - an amplitude sample
   * every hundred milliseconds, downsampled to `VOICE_WAVEFORM_BARS` - rather
   * than derived on each receiver. Three reasons, in order of how much they
   * matter:
   *
   * 1. A receiver cannot compute it without decoding the whole file, which
   *    means downloading it first. The waveform is meant to be visible *before*
   *    that, which is the entire point of drawing one.
   * 2. Decoding audio to PCM is cheap in a browser and genuinely awkward on
   *    Android. Measuring once, on the one device that already has the raw
   *    signal in its hands, is less total code than two decoders.
   * 3. Every client then draws the same shape for the same message. A waveform
   *    that differs between a phone and a laptop is a waveform nobody trusts as
   *    a position indicator.
   *
   * Absent for audio that was picked from disk rather than recorded, and for
   * anything sent before this existed - the player falls back to a flat bar in
   * both cases, and still plays.
   */
  waveform?: number[];
}

/**
 * How many bars a voice message is drawn with.
 *
 * A fixed count rather than one bar per sample, so a three-second message and a
 * three-minute one are the same width and the same shape of thing. Forty-eight
 * is enough to read as a voice and few enough to stay legible in a bubble on a
 * phone; past about sixty the bars are thinner than the gaps between them.
 */
export const VOICE_WAVEFORM_BARS = 48;

/**
 * How long a message's stored `content` may be.
 *
 * Counted on the ciphertext envelope, not on what was typed: the envelope also
 * carries the attachment manifest - a key, a url, a name, a size and a content
 * type per file - and base64 makes all of it a third longer again. A cap sized
 * for prose refuses a perfectly ordinary message the moment it carries a
 * handful of pictures, which is what a cap of 8000 here used to do.
 */
export const MAX_MESSAGE_CONTENT_LENGTH = 32000;

/**
 * How many files one message may carry.
 *
 * Past this the point is a folder, not a chat - and every client caps its
 * picker here so the manifest can never grow past
 * [MAX_MESSAGE_CONTENT_LENGTH]. Refused where the files are chosen, which is
 * the only place it can be explained.
 */
export const MAX_ATTACHMENTS_PER_MESSAGE = 10;

/**
 * Whether an attachment should be drawn as a voice message rather than as a
 * file with a player stapled to it.
 *
 * Two signals, and either is enough. A recorded note carries a waveform, which
 * nothing else does. One sent before waveforms existed is recognised by the
 * name this client gives them - which is also how a *picked* audio file avoids
 * being mistaken for one: somebody sharing an album track wants its name and a
 * download, not a voice bubble.
 */
export function isVoiceNote(attachment: MessageAttachment): boolean {
  return (
    attachment.contentType.startsWith('audio/') &&
    ((attachment.waveform?.length ?? 0) > 0 || /^voice_\d{8}_\d{6}\./.test(attachment.name))
  );
}

/**
 * What a message is a reply to.
 *
 * The author and a snippet are copied in rather than looked up, and that is
 * deliberate on two counts. The quoted message may be a thousand messages back
 * and not on this device at all - a reply has to render without fetching
 * anything. And it lives inside the encrypted body, so the server learns
 * nothing about who is answering whom: a reply is an ordinary message to it.
 *
 * The consequence is that a quote is a snapshot. Editing the quoted message
 * does not rewrite the quotes of it, which is the same thing every chat app
 * does and is honest about what was being answered at the time.
 */
export interface MessageReply {
  /** The message being replied to, for the jump-to-it click. */
  id: string;
  /** Who wrote it, as they were named when the reply was sent. */
  author: string;
  /** The first line or so of it. Empty for a message that was only files. */
  preview: string;
}

/**
 * The plaintext inside `Message.content` once a message carries more than
 * text. A message that is only text is still encoded as bare text, so
 * everything written before this existed keeps rendering.
 */
/**
 * A custom emoji carried inside a message.
 *
 * The text keeps the literal `:name:`, and this says what to draw for it. Both,
 * on purpose:
 *
 * - The picture travels with the message, so a reader who is not in the server
 *   that owns the emoji still sees it - a shortcode forwarded into a direct
 *   message would otherwise render as a word.
 * - The text stays readable. A client that has never heard of custom emoji
 *   shows `:party_parrot:`, which is what it meant, rather than a marker.
 *
 * Nothing is leaked by carrying it: the URL is public and the server already
 * holds the row. What the server still cannot see is which message used it.
 */
export interface MessageCustomEmoji {
  name: string;
  url: string;
  animated: boolean;
}

/**
 * Where a forwarded message came from.
 *
 * A forward is a new message, not a pointer to the old one - it has to be,
 * because the body is sealed under the key of the channel it was written in
 * and nobody in the channel it lands in holds that key. So the plaintext is
 * re-sealed for the destination and this rides along to say whose words they
 * were, which is the whole of what the "Forwarded" tag on a bubble reports.
 *
 * A snapshot, like [MessageReply]. Editing the original does not rewrite the
 * forwards of it, and there is no id here on purpose: a jump-to-it link would
 * point at a channel the reader may not be allowed to open.
 */
export interface MessageForward {
  /** Who wrote it, as they were named when it was forwarded. */
  author: string;
  /** The channel it was taken from, by name. */
  channel: string;
}

export interface MessageBody {
  text: string;
  attachments: MessageAttachment[];
  replyTo?: MessageReply;
  /** Custom emoji appearing in `text`, by the name written between colons. */
  emoji?: MessageCustomEmoji[];
  /** Set when this message is somebody else's, carried in from elsewhere. */
  forwardedFrom?: MessageForward;
}

// --- End-to-end encryption ---
//
// The server stores and routes only the ciphertext shapes below. Key material
// exists in plaintext exclusively inside a client. See development/E2EE.md.

/** What a client actually puts in `Message.content`. */
export interface EncryptedEnvelope {
  /** Envelope version, so a future format change stays readable. */
  v: 1;
  /** Which channel-key generation encrypted this. */
  epoch: number;
  /** Base64 AES-GCM nonce (12 bytes). */
  iv: string;
  /** Base64 AES-GCM ciphertext with appended tag. */
  ct: string;
}

/** A user's published ECDH P-256 public key, JWK-serialised. */
/**
 * One machine's public identity key.
 *
 * A list per user rather than one key per account. The single key was copied to
 * every machine the account signed in on, which made "revoke this laptop" mean
 * "rotate the identity every other machine is also using" - so nobody could,
 * and a key that cannot be revoked is a key that is trusted forever.
 */
export interface DeviceKey {
  userId: string;
  /** Client-minted and stable for an installation. */
  deviceId: string;
  publicKey: string;
  /** What to call it in a list. Client-supplied, and not to be trusted as identity. */
  label: string | null;
  /** Set once the owner revoked it. Nothing is ever wrapped for a revoked device. */
  revokedAt: string | null;
  lastSeenAt: string;
  createdAt: string;
}

export interface RegisterDeviceKeyRequest {
  deviceId: string;
  publicKey: string;
  label?: string;
}

/** One channel key sealed for one device. */
export interface ChannelKeyEntry {
  recipientUserId: string;
  /** Which of that user's devices this copy is for. */
  recipientDeviceId: string;
  senderUserId: string;
  senderDeviceId: string;
  /** Sender's ECDH public key (JWK) - the recipient needs it to derive the secret. */
  senderPublicKey: string;
  wrappedKey: string;
  iv: string;
}

export interface PublishChannelKeysRequest {
  channelId: string;
  epoch: number;
  /** Which device did the sealing. Every entry in the bundle came from it. */
  senderDeviceId: string;
  entries: Array<Omit<ChannelKeyEntry, 'senderUserId' | 'senderDeviceId'>>;
}

export interface ChannelKeysResponse {
  channelId: string;
  /** Highest epoch that exists for this channel, 0 when the channel has no key yet. */
  epoch: number;
  /** Entries addressed to the caller, oldest epoch first. */
  keys: Array<ChannelKeyEntry & { epoch: number }>;
  /**
   * Devices with a published key and no entry at `epoch` - each needs a
   * re-wrap. One entry per device, not per person: somebody who signed in on a
   * second machine yesterday is missing exactly one of their two.
   */
  missingRecipients: DeviceKey[];
  /**
   * True when somebody who is no longer a member holds the current epoch's key.
   *
   * Removing somebody from a private channel's allowlist takes away the listing
   * and the history endpoint, and takes away nothing at all from the key they
   * already have: every future message would still be sealed with a key sitting
   * on their machine. Whoever holds the key rotates it when they see this, which
   * is the only place it can happen - the server cannot mint a key it must not
   * be able to read.
   *
   * It says nothing about *who*: a client re-wraps for the current membership,
   * which it has to fetch anyway.
   */
  rekeyNeeded: boolean;
  /**
   * Machines missing an epoch *their owner already holds somewhere else*, over
   * every epoch the channel has had, newest first. This is what lets a second
   * machine read history rather than only what is written after it arrives.
   *
   * `missingRecipients` covers the current epoch only, which is enough to keep
   * the next message readable and nothing else. A machine that signs in today
   * is missing every epoch before today: it cannot re-wrap them for itself
   * (it holds none of them), and nothing else was looking, so it mints a fresh
   * epoch and everything written before it stays a padlock for good.
   *
   * "Their owner already holds it" is the boundary, and it is load-bearing:
   * without it this would hand the whole history to somebody who joined
   * yesterday, which is the opposite of the rule everything else here keeps. It
   * repairs one person's access on their own second machine and nothing else.
   *
   * A client that holds an epoch fills these gaps. The server already lets a
   * holder add to an existing epoch, so this needs no new permission - only
   * somebody to notice, which is what this field is.
   *
   * Empty for a channel with no key yet.
   */
  gaps: Array<{ epoch: number; devices: DeviceKey[] }>;
}

/**
 * What secret opens an identity backup.
 *
 * `password` is the account password, so signing in on a new device restores
 * the identity with no extra step. `passphrase` is a separate secret the user
 * set themselves - the only option for an account that signs in with a
 * provider and has no password to derive from.
 */
export type BackupSecretKind = 'password' | 'passphrase';

/**
 * The device identity key, sealed with a key derived from a secret the server
 * never receives. Restoring it on a second machine is what makes the account
 * (and its history) portable instead of tied to one installation.
 */
export interface IdentityBackup {
  /** Format version of the sealed blob. */
  v: 1;
  kind: BackupSecretKind;
  /** Only `PBKDF2-SHA256` today; named so a stronger KDF can be added later. */
  kdf: 'PBKDF2-SHA256';
  iterations: number;
  /** Base64 KDF salt (16 bytes). */
  salt: string;
  /** Base64 AES-GCM nonce (12 bytes). */
  iv: string;
  /** Base64 AES-GCM ciphertext of the identity key pair, with tag. */
  ct: string;
  /**
   * The identity's public half, in the clear. It is public by definition, and
   * having it lets a client tell "this backup is for the key the directory
   * already knows" from "this backup is stale" before asking for a secret.
   */
  publicKey: string;
  updatedAt?: string;
}

export type PutIdentityBackupRequest = Omit<IdentityBackup, 'updatedAt'>;

export interface IdentityBackupResponse {
  /**
   * Every backup this account holds, at most one per {@link BackupSecretKind}.
   *
   * A list rather than a single blob because the two kinds answer different
   * questions and an account is allowed both. The password one is what a fresh
   * sign-in can open unaided; the passphrase one is for somebody whose threat
   * model includes the running server. Keying the table on the account alone
   * meant setting the second destroyed the first, and a device that can open
   * neither mints its own identity - which reads every message ever sent to the
   * account as a padlock, permanently.
   */
  backups: IdentityBackup[];
  /**
   * @deprecated Read {@link backups}. Kept so a client older than per-kind
   * backups still finds one: the password blob when there is one, because that
   * is the secret such a client has at sign-in, otherwise whatever there is.
   */
  backup: IdentityBackup | null;
}

// --- Calls ---

export interface CallIceRequest {
  channelId: string;
}

/**
 * How to find a path to the other peer. Deliberately not "where the media
 * server is": there is no media server, and no client is ever told to dial one.
 */
export interface CallIceResponse {
  /**
   * STUN first, then TURN when the deployment configures one.
   *
   * STUN is address discovery, not a relay: a peer asks what its own public
   * address looks like and offers that to the other side. TURN *is* a relay,
   * for the pairs of networks - symmetric NAT, carrier-grade NAT - that cannot
   * form a direct path at all; a deployment with none configured gets STUN
   * alone and those calls fail rather than being quietly relayed.
   */
  iceServers: IceServer[];
}

/**
 * "Come into this call" - a ring aimed at one person.
 *
 * The roster announcement (`CallPushData`) is the ambient half: it says a call
 * is happening in a channel somebody can hear, and it deliberately does not
 * ring a phone for a server's voice channel, because a phone that rings every
 * time anybody joins any channel is a phone somebody turns notifications off
 * on.
 *
 * This is the other half, and the difference is that a person chose to send it.
 * It rings - a full-screen incoming call on a locked phone, a modal on the
 * desktop - because it was aimed rather than broadcast.
 */
export interface CallRingRequest {
  channelId: string;
  /** Who to ring. Must be able to see the channel; the server checks. */
  userId: string;
}

/**
 * "I have said no to that, here."
 *
 * Who declined is the authenticated user and is never in the body: this is the
 * one thing a decline says, and a decline that could name its own sender would
 * be a way to silence somebody else's phone.
 *
 * It goes nowhere near the caller. Declining is not a message to whoever rang -
 * a ring is not a handshake, and it rings out for them either way - it is this
 * account telling its *own* other devices to stop.
 */
export interface CallDeclineRequest {
  channelId: string;
}

/**
 * One call somebody was in, as their own log reads it back.
 *
 * Written from the gateway's own knowledge of when the socket joined and left,
 * so it is not a client's account of its own call. The one number that is the
 * client's is `bytes`: nothing on the server is in the media path to measure.
 */
export interface CallHistoryEntry {
  id: string;
  channelId: string;
  channelName: string;
  /** Null for a direct message, which belongs to no server. */
  serverId: string | null;
  serverName: string | null;
  joinedAt: string;
  /** Null for a call that never got an ending written - the process died. */
  endedAt: string | null;
  /** Whole seconds, or null when there is no ending to measure to. */
  durationSeconds: number | null;
  /** Everybody else who was in it while this person was, as they are named now. */
  peers: Array<{ id: string; username: string; displayName: string }>;
  /** Sent plus received, as this person's client counted it. */
  bytes: number;
  /** The same total split by direction. Both zero when nothing was reported. */
  bytesSent: number;
  bytesReceived: number;
  /**
   * One entry per peer connection this client held during the call, empty for a
   * call whose client never reported - an older build, or one that was killed.
   */
  links: CallLinkReport[];
}

/**
 * What one peer connection did, as the client at this end measured it.
 *
 * The unit of a mesh call is the link, not the call: two people in the same
 * call can have completely different answers about whether it went direct, and
 * "why was that one call bad" is a question only a per-link reading answers.
 * Nothing on the server can check any of it, so it is clamped rather than
 * trusted - see `usage.ts` in call-service.
 */
export interface CallLinkReport {
  /** Who the connection was with. Resolved to a current name when read back. */
  userId: string;
  /** How they were named at the time, so a deleted account still reads. */
  username: string;
  bytesSent: number;
  bytesReceived: number;
  /** Round trip on the pair that carried the call, when it was ever known. */
  roundTripMs: number | null;
  packetsLost: number;
  packetsReceived: number;
  /**
   * `direct` when the media went straight between the two machines, `relay`
   * when it went through TURN, null when the client never worked it out. It is
   * the difference between a call that cost the network nothing and one that
   * cost an operator's relay bandwidth, and it is invisible without this.
   */
  transport: CallTransport | null;
}

export type CallTransport = 'direct' | 'relay';

/**
 * The account's own calls, added up: what a month of them cost.
 *
 * Read from the same rows the log is, so the two can never disagree. Bucketed
 * by local date on the server's clock - a day boundary an hour out is not worth
 * a timezone round trip on a page about roughly how much data a week used.
 */
export interface CallAnalytics {
  /** How far back this covers, in days, ending today. */
  days: number;
  totals: CallUsageTotals;
  /** Oldest first, one entry per day in the window - including empty ones, so a
   * chart drawn straight from this has no gaps to invent. */
  daily: Array<{ date: string } & CallUsageTotals>;
  /** Where the time went, busiest first. */
  channels: Array<{
    channelId: string;
    channelName: string;
    serverName: string | null;
  } & CallUsageTotals>;
  /** Who it was spent with, most first. */
  peers: Array<{
    id: string;
    username: string;
    displayName: string;
    calls: number;
    seconds: number;
  }>;
  /** How the media got there, across every link reported in the window. */
  transport: { direct: number; relay: number; unknown: number };
}

export interface CallUsageTotals {
  calls: number;
  seconds: number;
  bytesSent: number;
  bytesReceived: number;
}

/** One entry of a WebRTC `RTCConfiguration.iceServers`. */
export interface IceServer {
  urls: string[];
  username?: string;
  credential?: string;
}

/**
 * Somebody else in the call.
 *
 * Keyed by `peerId`, not `userId`: one account can have two windows open, and
 * each is a separate end of a separate peer connection.
 */
export interface CallPeer {
  peerId: string;
  userId: string;
  username: string;
}

/** A plain `RTCIceCandidateInit`, spelled out so Node can name the type too. */
export interface IceCandidatePayload {
  candidate: string;
  sdpMid?: string | null;
  sdpMLineIndex?: number | null;
  usernameFragment?: string | null;
}

/**
 * What one peer sends another. `call-service` relays these without reading
 * them - it stamps who they came from and forwards the rest verbatim.
 *
 * `fingerprintProof` is `HMAC-SHA256(channel key, the DTLS fingerprint in this
 * SDP)`, base64. It is what stops the relay from substituting a fingerprint of
 * its own and sitting in the middle of a connection both ends believe is
 * direct: the server has never held a channel key, so it cannot produce one.
 */
export type CallSignal =
  | { kind: 'offer'; sdp: string; fingerprintProof: string }
  | { kind: 'answer'; sdp: string; fingerprintProof: string }
  | { kind: 'ice'; candidate: IceCandidatePayload };

/**
 * --- Listen Together ---
 *
 * A shared listening session inside a voice call: everybody hears the same
 * track at the same moment, and anybody in the call can change what it is.
 *
 * The thing to understand before reading the rest: **no audio crosses the
 * wire.** Each client plays the track itself, from the provider, over its own
 * connection. What the gateway relays is a few dozen bytes of transport state -
 * which track, playing or paused, where in it, and when that was true. That is
 * why this belongs on `/ws/call` beside the SDP and not anywhere near the mesh:
 * it is signalling, it is small, it is text, and it is exactly what a
 * Cloudflare Tunnel carries.
 *
 * It is also why this is not a screen share with the sound on. A share costs
 * the sharer one upload per other participant, re-encodes the music through a
 * codec tuned for speech, and gives everyone else whatever survived the trip.
 * Here every client streams the original at full quality, the uplink cost is
 * zero, and the only thing that has to stay in step is a number.
 */
export type ListenProvider = 'youtube';

/** One entry in the shared queue. */
export interface ListenTrack {
  /** Queue-entry id, minted by whoever added it. The same video can be queued twice. */
  id: string;
  provider: ListenProvider;
  /** The provider's own id - for YouTube, the eleven-character video id. */
  ref: string;
  /**
   * What to call it on screen.
   *
   * Filled in by the first client whose player learns it, because nothing on
   * the server may talk to YouTube: an outbound call from a backend service to
   * fetch a title would be a service that needs an API key, an egress rule and
   * an opinion about who is listening to what. The clients already have the
   * player open, and it tells them.
   */
  title: string;
  /** Milliseconds; 0 until a player reports it. */
  durationMs: number;
  addedByUserId: string;
  addedByUsername: string;
}

/**
 * The whole of a listening session, as the gateway holds it.
 *
 * `positionMs` is where the track was at `atServerMs`, not where it is now.
 * Sending "now" would be a lie by the time it arrived: a client reads its
 * position as `positionMs + (serverNow - atServerMs)` while playing, which
 * makes one message good for as long as nothing changes. See
 * `services/listen-sync.ts` for the arithmetic and the drift correction.
 */
export interface ListenSession {
  /**
   * Bumped by the gateway on every change.
   *
   * The gateway is the only thing that can order two people pressing pause at
   * the same moment, for the same reason it arbitrates the screen share: a mesh
   * has no ordering of its own. A client drops any state with a `rev` it has
   * already seen, so its own echo cannot undo somebody else's later change.
   */
  rev: number;
  queue: ListenTrack[];
  /** Index into `queue`. A session always has at least one track. */
  index: number;
  paused: boolean;
  positionMs: number;
  /** The gateway's clock when this state was made. */
  atServerMs: number;
  /** Who last touched it, for the line that says who skipped. */
  byUserId: string | null;
}

/**
 * Where the needle is at `nowMs`, on a clock shared with the gateway.
 *
 * Part of the contract rather than of either side, because it is the whole
 * meaning of `positionMs` and `atServerMs`: a server that advanced the position
 * differently from the clients reading it would be a session where nobody is
 * wrong and nobody agrees. One formula, in the package both sides import.
 *
 * Clamped to the track's length once one is known, so a session left playing
 * while everybody was away does not report a position in the next hour.
 */
export function listenPositionAt(session: ListenSession, nowMs: number): number {
  const elapsed = session.paused ? 0 : Math.max(0, nowMs - session.atServerMs);
  const raw = session.positionMs + elapsed;
  const duration = session.queue[session.index]?.durationMs ?? 0;
  return duration > 0 ? Math.min(raw, duration) : Math.max(0, raw);
}

export type ClientCallEvent =
  | { type: 'join'; channelId: string }
  /**
   * `bytes` is what this client's peer connections moved over the whole call,
   * sent plus received. Only the client can know it - the gateway is not in the
   * media path and has nothing to count - so it is reported on the way out and
   * clamped by the server, which treats it as the cosmetic number it is.
   */
  | { type: 'leave'; bytes?: number; bytesSent?: number; bytesReceived?: number; links?: CallLinkReport[] }
  | { type: 'signal'; to: string; data: CallSignal }
  /**
   * "I am about to share my screen" / "I have stopped".
   *
   * One share at a time in a call, and the claim is what decides whose. It is
   * arbitrated here rather than between clients because two people pressing the
   * button at the same moment need a single answer, and a mesh has no ordering
   * to give one - the gateway holds the sockets, so it is the thing that can
   * say "this one, and the other one stops".
   */
  | { type: 'screen.claim' }
  | { type: 'screen.release' }
  /**
   * Listen Together. Anybody in the call may send any of these - there is no
   * host, because a host is a person who has to leave eventually and take the
   * music with them. The gateway sequences them and tells everybody the result.
   */
  /**
   * Queue a track. `playNow` also jumps to it, which is what pressing a video
   * means: somebody who clicked a song wants to hear that song, not to hear it
   * after the four already in the queue.
   */
  | {
      type: 'listen.add';
      provider: ListenProvider;
      ref: string;
      title?: string;
      playNow?: boolean;
    }
  | { type: 'listen.remove'; trackId: string }
  /** Resume, or jump to `index` in the queue. */
  | { type: 'listen.play'; index?: number }
  | { type: 'listen.pause'; positionMs: number }
  | { type: 'listen.seek'; positionMs: number }
  | { type: 'listen.skip'; delta: number }
  /** Close the session for everybody. */
  | { type: 'listen.stop' }
  /**
   * "My player reached the end of this track."
   *
   * Every client sends it, and the gateway advances once: the track id is
   * checked against the one playing, so the second and third arrivals are about
   * a track that is no longer current and do nothing. Idempotent by
   * construction rather than by election - electing a reporter means the queue
   * stops when that person's window closes.
   */
  | { type: 'listen.ended'; trackId: string }
  /**
   * "My player has learned what this track is called and how long it is."
   *
   * The title cannot be known when a track is added, because at that point it
   * is a link somebody pasted - only a player that has loaded it knows. And
   * nothing on the server may go and ask: an outbound call from a backend
   * service to fetch a title is a service that needs an API key, an egress rule
   * and an opinion about who is listening to what. So the clients, which have
   * the player open anyway, fill it in. First one to know, wins; the rest are
   * about a field that is already set and change nothing.
   */
  | { type: 'listen.meta'; trackId: string; title?: string; durationMs?: number }
  /**
   * Play Together. Anybody in the call may open a game or take an empty chair;
   * only the person sitting in a seat may move it, and only on their turn.
   *
   * A move is a number - a square, a column, a line - and the gateway is the
   * referee: it applies the rules from `games/` and broadcasts the board that
   * came out. Nothing here is trusted from the client except which move was
   * asked for, because a client that could send a board could send any board.
   */
  | { type: 'game.open'; gameId: GameId }
  /** Take an empty chair, or move to one. Standing up is `seat: -1`. */
  | { type: 'game.sit'; seat: number }
  /**
   * A move, and - for a game where a move is not an index - the numbers that
   * complete it. A carrom shot is where the striker sits, which way it points
   * and how hard it is hit; packing three numbers into one would be an encoding
   * the two ends could disagree about.
   *
   * The gateway checks them and runs the physics itself. What is never sent is
   * a board: a client that could send twenty coin positions could send twenty
   * coins in the pockets.
   */
  | { type: 'game.move'; move: number; params?: number[] }
  /** Deal again with the same people in the same chairs. */
  | { type: 'game.rematch' }
  /** Close the game for everybody. */
  | { type: 'game.close' }
  | { type: 'ping' };

export type ServerCallEvent =
  | { type: 'ready'; peerId: string }
  | { type: 'joined'; channelId: string; peers: CallPeer[] }
  | { type: 'peer.joined'; peer: CallPeer }
  | { type: 'peer.left'; peerId: string }
  | { type: 'signal'; from: string; data: CallSignal }
  /**
   * This account joined a call from somewhere else, so this connection is no
   * longer the one carrying it. One call per account across every device, which
   * is what stops a phone and a desktop from both being in a room, and what
   * makes joining on a second device feel like moving rather than duplicating.
   */
  | { type: 'superseded'; channelId: string }
  /**
   * Who is sharing their screen in this call, or null when nobody is.
   *
   * Sent to everybody on every change, including to the peer that just took it.
   * A client that sees somebody else here while it is sharing stops: taking
   * over is what the button does, the way Teams does it, rather than two
   * screens on one stage and no way to tell which is which.
   */
  | { type: 'screen.holder'; peerId: string | null; userId: string | null }
  /**
   * The listening session in this call, or null when there is not one.
   *
   * Always the whole session rather than a delta: it is a few hundred bytes,
   * it changes when a person presses a button rather than continuously, and a
   * client that missed one message would otherwise hold a queue nobody else
   * has. Sent to everybody on every change, the joiner included.
   */
  | { type: 'listen.state'; session: ListenSession | null }
  /**
   * The game being played in this call, or null when there is not one.
   *
   * Whole board rather than a move, for the same reason `listen.state` is whole:
   * a client that missed one message would otherwise hold a position nobody
   * else has, and two people playing different boards is a failure neither of
   * them can see. It is a few hundred bytes and it is sent when somebody moves.
   */
  | { type: 'game.state'; session: GameSession | null }
  /**
   * `serverMs` is the gateway's clock, which is what makes the shared position
   * mean anything: two machines disagree about what time it is by whatever
   * their NTP daemons last decided, and a listening session that trusted local
   * clocks would be as far out of step as they are. The client subtracts half
   * the round trip and keeps the offset. See `services/listen-sync.ts`.
   */
  | { type: 'pong'; serverMs?: number }
  | { type: 'error'; code: string; message: string };

// --- Presence ---

/**
 * What a user chose to appear as. `offline` is not choosable - it is what a
 * disconnected client, or an invisible one, looks like to everybody else.
 */
export type ActiveStatus = 'online' | 'idle' | 'dnd' | 'invisible';

export type PresenceStatus = ActiveStatus | 'offline';

export interface PresenceState {
  userId: string;
  status: PresenceStatus;
  /**
   * When this account was last connected and visible, ISO-8601, or undefined
   * when nobody has ever seen it go - a brand new account, or one whose only
   * sessions predate the column.
   *
   * Only meaningful while `status` is `offline`: somebody who is here now was
   * last seen now, and a client that drew "last seen a moment ago" over a green
   * dot would be saying the same thing twice and one of them wrong.
   *
   * Never sent for an account that is invisible. Invisibility that still
   * published when you were last here would not be invisibility, so the value
   * stops being written the moment the status is chosen and freezes at the last
   * time the account was genuinely visible.
   *
   * And never sent to somebody the subject's `LastSeenVisibility` excludes, or
   * to an account that has hidden its own. The field is absent in both cases,
   * which is the same thing a client draws for an account nobody has ever seen
   * go offline - so a missing timestamp says nothing about which of the three
   * reasons produced it.
   *
   * Only ever sent in reply to a `presence.query`. A `presence.changed` that is
   * broadcast to an audience cannot carry it: the answer is different per
   * recipient, and a broadcast has one payload for all of them.
   */
  lastSeenAt?: string;
}

/** Who is currently connected to a voice channel's room. */
export interface VoiceState {
  channelId: string;
  userIds: string[];
}

// --- Presence WebSocket protocol (/ws/presence) ---

export type ClientPresenceEvent =
  | { type: 'status.set'; status: ActiveStatus }
  | { type: 'typing.start'; channelId: string }
  /**
   * "This channel is on screen in front of me, in a focused window."
   *
   * Sent when a channel is opened in a focused window and again on a heartbeat
   * while it stays that way; `channel.blur` is sent when the window loses
   * focus or the channel is left. It is what stops a push waking a phone for a
   * conversation its owner is already reading somewhere else - see
   * `docs/docs/architecture/push-suppression.md`.
   */
  | { type: 'channel.focus'; channelId: string }
  | { type: 'channel.blur'; channelId: string }
  | { type: 'voice.join'; channelId: string }
  | { type: 'voice.leave'; channelId: string }
  /**
   * "When were these people last here?"
   *
   * Asked when a profile card opens or a direct message is put on screen, and
   * answered with one `presence.changed` per user the caller is allowed to hear
   * about - which is the same audience scoping every other presence event goes
   * through, so this cannot be used to probe for accounts a stranger shares
   * nothing with.
   *
   * A pull rather than part of `presence.sync`, because a sync carries who is
   * online and the people a last-seen time is interesting for are exactly the
   * ones who are not: sending every offline account's timestamp on connect
   * would be the whole user table.
   */
  | { type: 'presence.query'; userIds: string[] }
  | { type: 'ping' };

export type ServerPresenceEvent =
  | { type: 'ready'; userId: string }
  /**
   * The caller's own status, as chosen - the only place `invisible` is ever
   * sent, because everyone else is told `offline` instead.
   */
  | { type: 'status.self'; status: ActiveStatus }
  /** Full snapshot on connect, then deltas. */
  | { type: 'presence.sync'; users: PresenceState[]; voice: VoiceState[] }
  | { type: 'presence.changed'; user: PresenceState }
  | { type: 'typing'; channelId: string; userId: string; username: string }
  | { type: 'voice.changed'; voice: VoiceState }
  /**
   * Somebody is ringing this account into a call, right now.
   *
   * The same thing `CallRingPushData` carries, delivered to the clients that
   * are already running. A push exists for the ones that are not; a client
   * that is up would otherwise find out about a ring only if it happened to be
   * a phone, which is the wrong way round for the client somebody is sitting
   * in front of.
   */
  | {
      type: 'call.ring';
      channelId: string;
      channelName: string;
      callerId: string;
      callerName: string;
      callerAvatarUrl?: string;
    }
  /**
   * The same thing `CallHandledPushData` carries, for the clients that are
   * running. Answering is visible to a running client already - it can see
   * itself arrive in the roster - but declining is not: nothing about it
   * reaches a roster, so without this a laptop would go on ringing after
   * somebody said no on their phone.
   */
  | { type: 'call.handled'; channelId: string; how: CallHandled }
  | { type: 'pong' }
  | { type: 'error'; code: string; message: string };

// --- Notifications ---

/**
 * Notification preferences, owned by the account rather than the client, so a
 * mute set on one machine holds on the next one.
 */
export interface NotificationPreferences {
  enabled: boolean;
  /**
   * Quiet hours as minutes from midnight on the client's own clock (so the
   * server needs no timezone). Null on either end means no quiet hours; a
   * window may wrap midnight - start 1320, end 480 is 22:00 to 08:00.
   */
  quietStartMinute: number | null;
  quietEndMinute: number | null;
  mutedChannelIds: string[];
  /**
   * Channels that raise a notification only when this account is mentioned.
   *
   * The client decides what counts as a mention, because the server cannot: a
   * message body is sealed with the channel key. A channel in both lists is
   * silent - the stronger setting wins.
   */
  mentionOnlyChannelIds: string[];
  /**
   * People this account never wants raised, wherever they write.
   *
   * A channel mute is the wrong tool for one loud person in five channels, and
   * leaving is the wrong tool for a colleague. Applied on the client for the
   * same reason mentions are: the author is on the envelope, but nothing else
   * about the message is legible to a service.
   */
  mutedUserIds: string[];
}

/** What a channel's bell is set to. Three states, in order of loudness. */
export type ChannelNotificationLevel = 'all' | 'mentions' | 'none';

export interface UpdateNotificationPreferencesRequest {
  enabled?: boolean;
  mutedUserIds?: string[];
  quietStartMinute?: number | null;
  quietEndMinute?: number | null;
  /** Replaces the whole list; send the list you want, not a delta. */
  mutedChannelIds?: string[];
  mentionOnlyChannelIds?: string[];
}

/** Messages a user has not read in one channel, derived from the read marker. */
export interface ChannelUnread {
  channelId: string;
  count: number;
  lastReadAt: string | null;
}

/** "I am looking at this channel now" - the marker is always the current time. */
export interface MarkChannelReadRequest {
  channelId: string;
}

/**
 * Somebody else's read marker in a channel: who has read it, and up to when.
 *
 * Read receipts are derived from these rather than stored per message. A
 * marker is one row per person per channel and it only moves forwards, so
 * "who has seen this message" is "whose marker is at or past its timestamp" -
 * which needs no new table and cannot fall out of step with the unread count,
 * because it is the same row the unread count is derived from.
 */
export interface ChannelReadReceipt {
  user: MessageAuthor;
  readAt: string;
}

// --- Push devices (phase 27) ---

/** The transports a push token can belong to. One per client family. */
export type DevicePlatform = 'android' | 'ios' | 'web';

/**
 * One installation's push token.
 *
 * Keyed on (user, device) rather than on the token: a token rotates - FCM mints
 * a new one after a restore, a clear-data or its own schedule - and a registry
 * keyed on it would grow a row per rotation and push to every dead one. The
 * device id is the client-minted installation id that already identifies this
 * machine to the key directory, so one phone is one row for as long as the app
 * is installed.
 */
export interface RegisterDeviceRequest {
  /**
   * How to reach this installation. Never logged.
   *
   * For `android` and `ios` it is the FCM registration token. For `web` it is
   * a Web Push subscription, serialised - see `WebPushSubscription`, which
   * says why one column carries both.
   */
  token: string;
  platform: DevicePlatform;
  /** Client-minted, stable per installation - the same id `DeviceKey` uses. */
  deviceId: string;
  /** What to call it in a list: "Pixel 8". Untrusted, display only. */
  label?: string;
  /** The client build, so a push that a version cannot render can be skipped. */
  appVersion?: string;
}

/**
 * A browser's push subscription: where to send, and the keys to seal it with.
 *
 * This is what `PushManager.subscribe` hands back, and it is what stands in for
 * an FCM token on the web. There is no Firebase in this path at all: a
 * deployment with VAPID keys and no Firebase project can push to browsers and
 * not to phones, and one with Firebase and no VAPID keys does the opposite.
 * Neither is a broken deployment.
 *
 * **It is stored in the same column an FCM token is.** That column means "how
 * to reach this installation", and for a browser the answer happens to be four
 * fields rather than one, so it travels as JSON. The alternative was two more
 * nullable columns and a migration that only ever applies to one platform.
 *
 * ponytail: a serialised object in a string column. If a third transport ever
 * needs its own shape, that is the moment to give the registry a typed address
 * rather than a string.
 */
export interface WebPushSubscription {
  /** The push service's URL for this browser. Unique, so it keys the row. */
  endpoint: string;
  keys: {
    /** The subscription's public key, base64url. */
    p256dh: string;
    /** The auth secret, base64url. */
    auth: string;
  };
}

/**
 * The application server key a browser needs before it can subscribe.
 *
 * Null when the deployment has configured no VAPID keys, which is the same
 * answer as "this deployment does not do web push" - the client asks once and
 * stops rather than failing at `subscribe`.
 */
export interface PushKeyResponse {
  vapidPublicKey: string | null;
}

/** What the registry answers with. Deliberately never the token itself. */
export interface RegisteredDevice {
  deviceId: string;
  platform: DevicePlatform;
  label: string | null;
  lastSeenAt: string;
}

/**
 * The data-only push a client is woken with.
 *
 * Data-only, and never `notification`: the body is sealed with the channel key,
 * so the only side that can write a notification worth reading is the client -
 * which is also the only side that knows whether that channel is already on
 * screen. Every field here is either on the message envelope already or is a
 * preference the recipient set themselves.
 *
 * All values are strings: FCM's data map has no other type.
 */
export interface MessagePushData {
  type: 'message.created';
  messageId: string;
  channelId: string;
  authorId: string;
  authorName: string;
  authorAvatarUrl?: string;
  /** The sealed envelope, so a client that holds the key can show the words. */
  content: string;
  createdAt: string;
  /** "1" when this channel is mentions-only for this recipient. */
  mentionsOnly?: string;
}

/**
 * A message was deleted, and a notification drawn for it is now a lie.
 *
 * The only push that exists to take something *off* a screen. It carries no
 * words because it needs none - the id is enough to find the line and drop it,
 * and the notification is rebuilt without it or cancelled if it was the only
 * one left.
 */
export interface MessageDeletedPushData {
  type: 'message.deleted';
  messageId: string;
  channelId: string;
}

/**
 * This account read a channel somewhere else.
 *
 * The mirror image of a message push: it exists to take a notification *off* a
 * screen rather than to put one on it. A phone that buzzed on the way to a desk
 * should not still be showing the notification once the message has been read
 * on the laptop.
 *
 * It carries no words and no message id - "everything in this channel up to
 * now" is the whole of what a read marker means, and the notification for that
 * channel is what gets cancelled. Sent to every device of the account,
 * including the one that did the reading, which has already cleared its own and
 * has nothing to do.
 */
export interface ChannelReadPushData {
  type: 'channel.read';
  channelId: string;
  /** ISO 8601, so a client can ignore one that arrives out of order. */
  at: string;
}

/**
 * Somebody asked to be friends, or said yes.
 *
 * Nothing here is sealed: a friend request has no body, and the name and
 * picture are already public. The client still writes the notification, for the
 * same reason every other one does - it is the only side that knows whether the
 * friends screen is already open.
 */
export interface FriendPushData {
  type: 'friend.request' | 'friend.accepted';
  actorId: string;
  actorName: string;
  actorAvatarUrl?: string;
}

/** Added to a server by somebody who was allowed to. */
export interface ServerMemberPushData {
  type: 'server.member.added';
  serverId: string;
  serverName: string;
  serverIconUrl?: string;
}

/**
 * Who is in a call, sent to the people who can hear it and are not.
 *
 * The whole roster rather than the one who joined, because it is one
 * notification per channel that is rewritten as people come and go - and
 * because the roster is the only thing that can also say a call has *ended*.
 * `count` of `"0"` is exactly that, and is what cancels the notification.
 */
export interface CallPushData {
  type: 'call.roster';
  channelId: string;
  channelName: string;
  /** Already joined for reading: "Ayaan and Bob". Empty when the call ended. */
  participants: string;
  /** FCM data values are strings, so a number has to travel as one. */
  count: string;
}

/**
 * Somebody is ringing this account into a call.
 *
 * Directed, unlike `CallPushData`: one person pressed a button with this
 * account's name under it, which is what earns the full-screen ringer, the
 * ringtone and the Doze exemption that `call.roster` deliberately does not get
 * for a server's voice channel.
 *
 * It carries no words to seal - a name, a channel and who is calling - so
 * every client, including a service worker holding no keys, can draw it in
 * full.
 */
export interface CallRingPushData {
  type: 'call.ring';
  channelId: string;
  channelName: string;
  callerId: string;
  callerName: string;
  callerAvatarUrl?: string;
}

/**
 * Somebody is on one of this account's machines.
 *
 * Sent to the machine's owner and to nobody else - the person driving it
 * already knows, and nobody else is entitled to know. This is the one
 * notification in the app that exists because of what it would mean if it
 * arrived unexpectedly: remote access is exactly the capability whose misuse
 * is invisible to the person it happens to, since they are by definition not
 * sitting at the machine.
 *
 * `state` carries the ending as well as the start, for the same reason
 * `CallPushData` carries a roster of nobody: it is the only thing that can take
 * the notification away again.
 */
export interface RemoteSessionPushData {
  type: 'remote.session';
  sessionId: string;
  machineId: string;
  machineName: string;
  actorId: string;
  actorName: string;
  state: 'started' | 'ended';
}

/** Everything that can arrive as a data-only push. */
/**
 * How a ring stopped mattering to the account it was aimed at.
 *
 * The two ways a person deals with a ringing phone. They are one value rather
 * than two push types because the effect is the same everywhere it lands - the
 * ringer comes down - and the difference is only what the device should
 * remember afterwards. See {@link CallHandledPushData}.
 */
export type CallHandled = 'answered' | 'declined';

/**
 * This account has dealt with that ring, on one of its devices.
 *
 * The third push here whose only job is to take something *off* a screen, and
 * for the same reason as `channel.read`: a ring is aimed at an account and
 * lands on every device it owns, so dealing with it on one of them leaves the
 * rest ringing at somebody who has already answered or already said no.
 *
 * Nothing could tell them before. Answering is invisible to the fan-out - the
 * roster announcement is addressed to everyone who can hear the channel *minus
 * whoever is in the call*, so the one account that needs to hear "you
 * answered" is the exact account it skips - and declining was not sent
 * anywhere at all. Either way the other devices rang on until they timed out.
 *
 * `how` is what the receiving device does *after* taking the ringer down.
 * `declined` has to be remembered for the rest of the call, or the next thing
 * that would have rung - a roster this device has not seen yet, a second push
 * arriving late - asks a question that has already been answered with no.
 *
 * Carries no names: there is nothing to draw. It is a cancel.
 */
export interface CallHandledPushData {
  type: 'call.handled';
  channelId: string;
  how: CallHandled;
}

export type PushData =
  | MessagePushData
  | MessageDeletedPushData
  | ChannelReadPushData
  | FriendPushData
  | ServerMemberPushData
  | CallPushData
  | CallRingPushData
  | CallHandledPushData
  | RemoteSessionPushData;

// --- Chat WebSocket protocol (/ws/chat) ---

export type ClientChatEvent =
  | { type: 'channel.subscribe'; channelId: string }
  | { type: 'channel.unsubscribe'; channelId: string }
  /**
   * Membership changes are server-wide, not channel-wide, so a socket says
   * which servers it is watching. Membership is re-checked on every subscribe.
   */
  | { type: 'server.subscribe'; serverId: string }
  | { type: 'server.unsubscribe'; serverId: string }
  | { type: 'ping' };

/**
 * Two shapes of server event: one carries what changed, the other only says
 * that something did. A message is carried because the client has to render it
 * without a round trip; a friendship or a member list is announced, because the
 * list is small, the change is rare, and refetching it is one call rather than
 * a per-recipient payload the server would have to compose twice.
 */
export type ServerChatEvent =
  | { type: 'ready'; userId: string }
  | { type: 'message.created'; message: Message }
  /**
   * An edit, a deletion, a pin and a reaction are all "this message is not what
   * you last saw", so they share one event carrying the whole message. A
   * deletion is not a separate event any more: the tombstone arrives here with
   * `deletedAt` set, which is exactly what the client has to render.
   */
  | { type: 'message.updated'; message: Message }
  /**
   * A message that left no tombstone: a one-time message somebody opened, or
   * one whose disappearing window closed.
   *
   * Separate from `message.updated` because there is nothing to carry. The row
   * is destroyed, and the client's instruction is "forget this, and forget
   * whatever you cached of its files" rather than "draw this differently".
   */
  | { type: 'message.gone'; messageId: string; channelId: string }
  /** Sent to both sides of a request, an acceptance or a removal. */
  | { type: 'friends.changed' }
  /**
   * Somebody this account can see posted a status, deleted one, or had one
   * expire. Announced rather than carried, like a friendship: the tray is one
   * call, it is small, and carrying a post would mean composing a different
   * payload per recipient because `seen` and `viewCount` differ per reader.
   *
   * `authorId` is there so a client can ignore its own echo without refetching.
   */
  | { type: 'status.changed'; authorId: string }
  /** Sent to everyone watching the server, and to whoever joined or left it. */
  | { type: 'server.members.changed'; serverId: string }
  /**
   * Somebody changed their picture or their name.
   *
   * The exception to "announce, do not carry": a profile is drawn in every
   * message that account ever sent, in the member list, in the friend list and
   * in a DM header, so announcing it would be one refetch per list on every
   * client that shares a room with them. Four fields are cheaper than any of
   * that, and every one of those lists holds exactly those four.
   *
   * Reaches everyone who can see them: the members of every server they are in,
   * everyone they are friends with, and their own other devices.
   */
  | { type: 'user.updated'; user: UserSummary }
  /**
   * A server was renamed or given a new picture. Carried for the same reason,
   * and sent to everyone watching that server.
   */
  | { type: 'server.updated'; serverId: string; name: string; iconUrl: string | null }
  /**
   * Somebody read a channel this socket is subscribed to. It carries the
   * marker rather than the receipts, because every client can already derive
   * "who has seen this message" from a marker and a timestamp - and a payload
   * per reader would be the same fact said once per person.
   */
  | { type: 'channel.read'; channelId: string; userId: string; at: string }
  /**
   * This account cleared its own history. Sent only to its own sockets - it is
   * a fact about one person's view and nobody else's copy moved.
   *
   * Carried rather than announced because the client cannot refetch its way to
   * the answer: every device holds a local cache of decrypted messages, and
   * what they each have to do is drop everything at or before `clearedAt`.
   *
   * `channelId` is the conversation it applies to, or null for all of them.
   */
  | { type: 'chats.cleared'; clearedAt: string; channelId: string | null }
  | { type: 'pong' }
  | { type: 'error'; code: string; message: string };

// --- Remote desktop (phase 17) ---
//
// A remote session is deliberately its own vocabulary: nothing here is reused
// from chat or calls, so a change to one cannot quietly widen the other.

export type RemotePermission =
  | 'REMOTE_VIEW'
  | 'REMOTE_CONTROL'
  | 'REMOTE_FILE_TRANSFER'
  | 'REMOTE_CLIPBOARD'
  | 'REMOTE_AUDIO'
  | 'REMOTE_ADMIN';

/** A machine as the person looking at the list sees it. */
export interface RemoteMachineSummary {
  id: string;
  name: string;
  platform: string;
  ownerId: string;
  ownerUsername: string;
  /** True when the agent currently holds a socket to the gateway. */
  online: boolean;
  lastSeenAt: string | null;
  /** What the caller may do here, expiry already applied. */
  permissions: RemotePermission[];
  /** When the caller's access lapses. Null for the owner and for open-ended. */
  expiresAt: string | null;
  createdAt: string;
}

/** Enrolment. The token comes back once and is never returned again. */
export interface EnrolMachineRequest {
  name: string;
  platform: string;
  /** Re-enrolling an existing machine rotates its token instead of adding one. */
  machineId?: string;
}

export interface EnrolMachineResponse {
  machine: RemoteMachineSummary;
  agentToken: string;
}

export interface RemoteGrantSummary {
  userId: string;
  username: string;
  displayName: string;
  avatarUrl: string | null;
  permissions: RemotePermission[];
  expiresAt: string | null;
}

export interface SetRemoteGrantRequest {
  userId: string;
  /** An empty list revokes: there is no separate delete. */
  permissions: RemotePermission[];
  /** ISO date; omitted or null is open-ended. */
  expiresAt?: string | null;
}

export interface StartRemoteSessionRequest {
  machineId: string;
}

/**
 * The screen goes directly from the agent to the controller over WebRTC, the
 * same way a call does. `remote-gateway` relays the offer, the answer and the
 * ICE candidates that set that up, along with input and the audit trail; it
 * never carries a pixel, and neither does the tunnel in front of it.
 */
export interface RemoteSessionResponse {
  sessionId: string;
  machineId: string;
  machineName: string;
  /** Frozen when the session started; the gateway enforces these, not the UI. */
  permissions: RemotePermission[];
  /** STUN, and TURN when the deployment configures one. See `CallIceResponse`. */
  iceServers: IceServer[];
}

/**
 * One end of a remote session describing itself to the other.
 *
 * Deliberately without the `fingerprintProof` a call's signal carries: the two
 * machines in a remote session share no secret the gateway has never seen, so
 * there is nothing to sign it with. The screen is still end-to-end encrypted -
 * DTLS-SRTP directly between them, with no server holding a decodable frame -
 * but an actively malicious gateway could substitute a fingerprint, which a
 * call's channel key makes impossible. See "Known limits" in E2EE.md.
 */
export type RemoteSignal =
  | { kind: 'offer'; sdp: string }
  | { kind: 'answer'; sdp: string }
  | { kind: 'ice'; candidate: IceCandidatePayload };

/**
 * One of the machine's displays, as the controller picks between them.
 *
 * A machine with two monitors has to be asked which one, and the answer has to
 * travel with its size: the controller maps a click to a fraction of the screen
 * it is looking at, and only the agent knows what that screen measures.
 */
export interface RemoteScreen {
  /** The platform's display id, stable for as long as the display is attached. */
  id: string;
  label: string;
  width: number;
  height: number;
  primary: boolean;
}

export interface RemoteAuditEntry {
  id: string;
  action: string;
  actorId: string | null;
  actorUsername: string | null;
  sessionId: string | null;
  detail: Record<string, unknown> | null;
  createdAt: string;
}

/**
 * A file on its way to the machine being controlled.
 *
 * The offer, the answer and the cancel travel over the gateway's socket, and
 * the bytes do not: they go down the session's data channel, directly between
 * the two machines, the same way the screen does. That split is not an
 * optimisation - it is what keeps `REMOTE_FILE_TRANSFER` enforceable. A
 * permission the gateway never sees a message for is a permission that does not
 * exist, so the thing it can check is the thing that asks, and the bulk that
 * follows is meaningless without it.
 *
 * One transfer at a time per session, which is what lets the data channel carry
 * nothing but bytes: the receiver knows how many to expect from the offer it
 * accepted, and counts. A second file waits for the first.
 */
export interface RemoteTransferOffer {
  transferId: string;
  name: string;
  /** Bytes. The receiver counts up to exactly this and then closes the file. */
  size: number;
}

/**
 * The ceiling on one transfer. Generous rather than principled: the receiving
 * side streams to disk and never holds the file, so this is a guard against a
 * mistake and a hostile controller rather than a memory limit.
 */
export const REMOTE_TRANSFER_MAX_BYTES = 4 * 1024 * 1024 * 1024;

/** Sent by a controller's socket. Input is refused unless the session allows it. */
export type ClientRemoteEvent =
  | { type: 'input.mouse'; action: 'move' | 'down' | 'up' | 'wheel'; x: number; y: number; button?: 'left' | 'right' | 'middle'; deltaY?: number }
  | { type: 'input.key'; action: 'down' | 'up'; key: string; code: string; modifiers: string[] }
  | { type: 'clipboard.set'; text: string }
  /**
   * Asks the machine for the mouse and keyboard, the way RDP does. Answered
   * immediately when the session was already granted control; otherwise it is
   * put to whoever is sitting at the machine, who is the one authority higher
   * than a stored grant.
   */
  | { type: 'control.request' }
  /** Hands control back without ending the session. */
  | { type: 'control.release' }
  /** Switches which of the machine's displays is being shared. */
  | { type: 'screen.select'; screenId: string }
  /** Relayed straight to the agent; the gateway does not read it. */
  | { type: 'rtc.signal'; data: RemoteSignal }
  /**
   * Asks to send a file. Checked against `REMOTE_FILE_TRANSFER` and audited
   * before it reaches the machine; the bytes follow on the data channel only
   * once the machine has answered.
   */
  | ({ type: 'file.offer' } & RemoteTransferOffer)
  /** Gives up on a transfer, from either end. Also sent when the file is short. */
  | { type: 'file.cancel'; transferId: string; reason?: string }
  | { type: 'session.end' }
  | { type: 'ping' };

/** Sent by an agent's socket. */
export type AgentRemoteEvent =
  | { type: 'agent.ready'; screens: number }
  | { type: 'session.accepted'; sessionId: string }
  | { type: 'session.refused'; sessionId: string; reason: string }
  | { type: 'session.ended'; sessionId: string }
  | { type: 'clipboard.text'; sessionId: string; text: string }
  /** What this machine has to offer, and which one is on the wire right now. */
  | { type: 'screens'; sessionId: string; screens: RemoteScreen[]; activeId: string }
  | { type: 'control.granted'; sessionId: string }
  | { type: 'control.denied'; sessionId: string; reason?: string }
  /** Relayed straight to that session's controller; the gateway does not read it. */
  | { type: 'rtc.signal'; sessionId: string; data: RemoteSignal }
  /** The machine's answer to a `file.offer`. Bytes may start after this. */
  | { type: 'file.accepted'; sessionId: string; transferId: string }
  | { type: 'file.refused'; sessionId: string; transferId: string; reason: string }
  /** Every byte arrived and the file is closed. `path` is where it landed. */
  | { type: 'file.done'; sessionId: string; transferId: string; path: string }
  | { type: 'pong' };

/** Sent by the gateway to either kind of socket. */
export type ServerRemoteEvent =
  | { type: 'ready'; role: 'agent' | 'controller'; machineId?: string; sessionId?: string }
  | {
      type: 'session.start';
      sessionId: string;
      /** For the agent: who is asking, and what they were granted. */
      controllerId: string;
      controllerName: string;
      permissions: RemotePermission[];
      /**
       * How to reach the controller. The agent is the one with a screen to
       * send, so it is the one that offers.
       */
      iceServers: IceServer[];
    }
  | { type: 'session.ended'; sessionId: string; reason: string }
  | { type: 'agent.state'; sessionId: string; state: 'accepted' | 'refused'; reason?: string }
  | { type: 'input.mouse'; action: 'move' | 'down' | 'up' | 'wheel'; x: number; y: number; button?: 'left' | 'right' | 'middle'; deltaY?: number }
  | { type: 'input.key'; action: 'down' | 'up'; key: string; code: string; modifiers: string[] }
  | { type: 'clipboard.set'; text: string }
  /** To the controller: the machine's displays, and which one it is sending. */
  | { type: 'screens'; screens: RemoteScreen[]; activeId: string }
  /** To the agent: send that display instead. */
  | { type: 'screen.select'; sessionId: string; screenId: string }
  /** To the agent: somebody is asking for control and the machine must answer. */
  | { type: 'control.requested'; sessionId: string; controllerName: string }
  /**
   * Relayed between the two ends of one session, in both directions. The
   * gateway stamps nothing and reads nothing; `sessionId` is present on the way
   * to an agent, which may hold several sessions at once, and absent on the way
   * to a controller, which has exactly one.
   */
  | { type: 'rtc.signal'; sessionId?: string; data: RemoteSignal }
  /**
   * File transfer, relayed between the two ends. The shapes going to the agent
   * are the controller's own, forwarded once the permission has been checked;
   * the ones coming back are the machine's answer, with the `sessionId` the
   * agent stamped stripped on the way to a controller that holds only one.
   */
  | ({ type: 'file.offer' } & RemoteTransferOffer)
  | { type: 'file.cancel'; transferId: string; reason?: string }
  | { type: 'file.accepted'; transferId: string }
  | { type: 'file.refused'; transferId: string; reason: string }
  | { type: 'file.done'; transferId: string; path: string }
  /**
   * To the controller: what this session may do now. Sent whenever control is
   * taken, granted, refused or released - the client renders from this rather
   * than from what it asked for.
   */
  | {
      type: 'control.changed';
      sessionId: string;
      permissions: RemotePermission[];
      granted: boolean;
      reason?: string;
    }
  | { type: 'pong' }
  | { type: 'error'; code: string; message: string };

// --- Health ---

/**
 * The client/server contract, bumped when a change lands that an older client
 * cannot survive - a route that moved, an envelope shape that changed, a
 * permission that means something new.
 *
 * Not the product version, and deliberately not derived from `package.json`:
 * most releases change nothing a client can notice, and a number that moves
 * every release trains people to ignore the warning it raises.
 *
 * 1: the contract as of the first deployment anyone runs.
 * 2: the key directory is per device rather than per account, and channel keys
 *    are wrapped per device. A client from before this cannot read the
 *    directory it is handed, and a server from before it cannot store what a
 *    new client sends.
 */
export const API_CONTRACT_VERSION = 2;

/** What `GET /api/v1/auth/version` answers. Public: it is asked before sign-in. */
export interface ServerVersion {
  /** The deployment's `API_CONTRACT_VERSION`. */
  contract: number;
  /** Human-readable, for a support conversation. Never parsed by a client. */
  release: string;
}

export interface HealthResponse {
  status: 'ok' | 'degraded';
  service: string;
  uptime: number;
}

// MVP schema. One schema shared by auth-, server- and chat-service; each
// service touches only the models it owns. Splitting per service is tracked in
// development/TODO.md (cross-cutting debt).

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

enum ServerRole {
  OWNER
  ADMIN
  MODERATOR
  MEMBER
  GUEST
}

enum ChannelType {
  TEXT
  VOICE
  /// A direct message between two people. It is a channel with no server, so
  /// history, paging, realtime fanout and encryption are the ones that already
  /// exist - see development/PLANNING.md (phase 12).
  DM
}

enum FriendshipStatus {
  PENDING
  ACCEPTED
}

/// Platform-wide role, distinct from ServerRole: ADMIN grants the admin
/// panel, not membership rights inside any server.
enum GlobalRole {
  USER
  ADMIN
}

/// Who may see when this account was last here.
///
/// EVERYONE is the ceiling rather than the whole world: presence is already
/// scoped to the people who share a server or an accepted friendship with you,
/// so "everyone" means everyone who could already see your name. FRIENDS
/// narrows that to accepted friendships, and NOBODY switches the answer off.
///
/// NOBODY is reciprocal - see `User.lastSeenVisibility`.
enum LastSeenVisibility {
  EVERYONE
  FRIENDS
  NOBODY
}

model User {
  id                 String     @id @default(uuid())
  email              String     @unique
  username           String     @unique
  displayName        String
  passwordHash       String
  avatarUrl          String?
  /// The wide picture behind the name at the top of a profile.
  ///
  /// Separate from `avatarUrl` and not derivable from it: an avatar is cropped
  /// square and read at 32px in a member list, a cover is a 4:1 band read at
  /// several hundred. Scaling one into the other gives a blurred crop of
  /// somebody's face as a backdrop, which is why every app that has both
  /// stores both. Null means the client draws the accent colour it drew before
  /// this column existed.
  coverUrl           String?
  /// A line about yourself, shown on the profile card everywhere the app draws
  /// one. Not encrypted and not private: it is a caption on a name, the same
  /// way an avatar is, and every client that can see the name renders it.
  /// Capped at ABOUT_MAX_LENGTH (140) by the DTO, which is the length that
  /// still reads as one line under a heading.
  about              String     @default("Hey, I’m on Between Us.")
  /// The last moment presence-service saw this account connected and visible.
  ///
  /// Redis holds the live value while somebody is online (`presence:lastseen`);
  /// this column is what it is flushed to when the last window goes, so a
  /// person who has been away for a week still has an answer after a Redis
  /// wipe or a service restart. Never written while the account is invisible -
  /// a status that hid you but kept publishing when you were last here would
  /// not be hiding you.
  lastSeenAt         DateTime?
  /// Who may read `lastSeenAt`.
  ///
  /// **NOBODY is reciprocal**: an account that hides when it was last here does
  /// not get to read anybody else's either. That is WhatsApp's rule and it is
  /// the only thing that keeps the setting from being a one-way mirror - a
  /// feature everybody switches on the moment it costs them nothing.
  ///
  /// Enforced server-side in `presence-service`, never by the client hiding a
  /// value it was sent: a timestamp that reaches a client is a timestamp that
  /// account can read, whatever the UI does with it.
  lastSeenVisibility LastSeenVisibility @default(EVERYONE)
  role               GlobalRole @default(USER)
  /// Set for accounts created with a generated password (the bootstrap admin);
  /// they can do nothing until they choose their own.
  mustChangePassword Boolean    @default(false)
  /// A disabled account keeps its data but cannot log in or refresh.
  disabledAt         DateTime?
  /// While this is in the future the account is in administrator-granted reset
  /// mode: naming it on the forgot-password screen mints a single-use reset
  /// token instead of sending mail. It is how a deployment with no SMTP server
  /// still has a way back in - see `PasswordReset`.
  passwordResetUntil DateTime?
  /// Messages older than this are not returned to *this* account, in any
  /// channel, on any of its devices. Nobody else's copy is touched: the row is
  /// still there and the other side still reads it, which is the only honest
  /// thing a "clear my chats" button can mean in a two-party conversation.
  ///
  /// One column on the account rather than a marker per channel, because the
  /// feature asked for is "clear everything" and a per-channel column would be
  /// a fan-out write over every channel the account is in to answer it.
  chatsClearedAt     DateTime?
  /// This account's own disappearing-message window, in seconds, or null for
  /// "keep everything". Personal and one-sided: it hides messages older than
  /// the window from *this* account on every one of its devices, and touches
  /// nobody else's copy. A server's own window (`Server.messageTtlSeconds`)
  /// outranks it - that one actually deletes rows, for everyone.
  messageTtlSeconds  Int?
  createdAt          DateTime   @default(now())
  updatedAt          DateTime   @updatedAt

  refreshTokens   RefreshToken[]
  ownedServers    Server[]             @relation("ServerOwner")
  memberships     ServerMember[]
  channelSeats    ChannelMember[]
  friendshipsA    Friendship[]         @relation("FriendshipA")
  friendshipsB    Friendship[]         @relation("FriendshipB")
  messages        Message[]
  deletedMessages Message[]            @relation("MessageDeletedBy")
  pinnedMessages  Message[]            @relation("MessagePinnedBy")
  reactions       MessageReaction[]
  /// One per machine this account has signed in on - see DeviceKey.
  deviceKeys      DeviceKey[]
  /// One per installation that can be pushed to - see DeviceToken.
  deviceTokens    DeviceToken[]
  identityBackups IdentityBackup[]
  identities      UserIdentity[]
  notifications   NotificationSetting?
  channelReads    ChannelRead[]
  serverInvites   ServerInvite[]       @relation("ServerInviteCreatedBy")
  remoteMachines  RemoteMachine[]      @relation("RemoteMachineOwner")
  remoteGrants    RemoteGrant[]        @relation("RemoteGrantUser")
  remoteGranted   RemoteGrant[]        @relation("RemoteGrantGrantedBy")
  remoteSessions  RemoteSession[]      @relation("RemoteSessionUser")
  remoteAudit     RemoteAudit[]        @relation("RemoteAuditActor")
  adminAudit      AdminAudit[]         @relation("AdminAuditActor")
  attachments     Attachment[]         @relation("AttachmentUploader")
  messageViews    MessageView[]
  callSessions    CallSession[]        @relation("CallSessionUser")
  passwordResets  PasswordReset[]
  /// People this account has blocked, and the blocks pointed back at it.
  blocksMade      UserBlock[]          @relation("BlockAuthor")
  blocksAgainst   UserBlock[]          @relation("BlockTarget")
  /// Webhooks this account opened. See Webhook.
  webhooks        Webhook[]            @relation("WebhookCreatedBy")
  /// Statuses this account has posted, and the ones it has opened. See Status.
  statuses        Status[]             @relation("StatusAuthor")
  statusViews     StatusView[]         @relation("StatusViewer")

  @@map("users")
}

/// One account refusing another.
///
/// Directional, unlike `Friendship`, which stores an ordered pair: a block is
/// something one person does and the other is not told about, so "A blocked B"
/// and "B blocked A" are two different facts and either one on its own has to
/// close the conversation. The gate reads both directions - see
/// `isBlockedBetween` in `@betweenus/database`.
model UserBlock {
  id        String   @id @default(uuid())
  blockerId String
  blockedId String
  createdAt DateTime @default(now())

  blocker User @relation("BlockAuthor", fields: [blockerId], references: [id], onDelete: Cascade)
  blocked User @relation("BlockTarget", fields: [blockedId], references: [id], onDelete: Cascade)

  @@unique([blockerId, blockedId])
  // "Who has blocked me" is asked as often as "who have I blocked": the first is
  // what closes a channel for the other side.
  @@index([blockedId])
  @@map("user_blocks")
}

/// A single-use permission to set a password without knowing the old one.
///
/// Only the SHA-256 of the token is stored, for the same reason `RefreshToken`
/// stores a hash: a leaked database must not be a pile of live reset links.
/// `source` records which of the two doors it came through - a link mailed by
/// the SMTP server, or an administrator putting the account into reset mode -
/// because those are worth telling apart afterwards.
model PasswordReset {
  id        String    @id @default(uuid())
  userId    String
  /// SHA-256 of the token handed to the client. Never logged.
  tokenHash String    @unique
  /// email | admin
  source    String
  expiresAt DateTime
  /// Set the moment it is spent; a spent token is kept as the record that it was.
  usedAt    DateTime?
  createdAt DateTime  @default(now())

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@index([userId])
  @@map("password_resets")
}

/// The deployment's outgoing mail server, configured from the admin panel.
///
/// One row, like `OAuthProvider` is one row per provider: this is operator
/// configuration and not user data. No row - or a row with `enabled` false -
/// is a deployment that cannot send mail at all, and every screen that would
/// have offered to mail something says "ask your administrator" instead.
model SmtpSetting {
  id          String  @id @default("smtp")
  enabled     Boolean @default(false)
  host        String  @default("")
  port        Int     @default(587)
  /// True for implicit TLS on connect (port 465); false starts plain and
  /// upgrades with STARTTLS, which is what 587 wants.
  secure      Boolean @default(false)
  username    String  @default("")
  /// Sealed with AES-256-GCM under SETTINGS_SECRET, exactly as
  /// `OAuthProvider.clientSecret` is. It never leaves the server in either
  /// direction - the panel can replace it but never read it back.
  password    String  @default("")
  /// The envelope sender. Providers reject mail whose From they do not own.
  fromAddress String  @default("")
  fromName    String  @default("BetweenUs")

  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  @@map("smtp_settings")
}

/// Append-only record of what an administrator did in the admin panel.
///
/// The subject of an admin action is very often an account that no longer
/// exists - deleting somebody is the action most worth having a record of - so
/// the target is stored as a label as well as an id. The id goes null with the
/// account; the label is what the log still reads back afterwards.
model AdminAudit {
  id          String  @id @default(uuid())
  /// Null once the administrator's own account is deleted. The row outlives it.
  actorId     String?
  /// Who or what it was done to: a user id, or a provider name for OAuth.
  targetId    String?
  /// How the target read at the time - `@ayaan`, `google`. Never updated.
  targetLabel String?
  /// user.role.changed, user.disabled, user.enabled, user.deleted,
  /// oauth.updated.
  action      String
  detail      Json?

  createdAt DateTime @default(now())

  actor User? @relation("AdminAuditActor", fields: [actorId], references: [id], onDelete: SetNull)

  @@index([createdAt])
  @@map("admin_audit")
}

/// Per-account notification settings, owned by notification-service. One row
/// per user, written the first time anything is changed - an account with no
/// row is an account with the defaults.
model NotificationSetting {
  userId                String   @id
  /// Off entirely; the client raises nothing while this is false.
  enabled               Boolean  @default(true)
  /// Quiet hours as minutes from midnight on the client's own clock, so the
  /// server never has to know a timezone. Null on either end means no quiet
  /// hours. A window is allowed to wrap midnight (start 1320, end 480).
  quietStartMinute      Int?
  quietEndMinute        Int?
  /// Channels this account never wants raised.
  /// ponytail: an array column, not a join table - the list is small and is
  /// only ever read whole. Split it out when a mute grows its own settings.
  mutedChannelIds       String[] @default([])
  /// Channels that only raise a notification when this account is mentioned -
  /// the middle setting between everything and nothing, and the one a busy
  /// server actually needs. A channel in both lists is silent: the stronger
  /// setting wins, so a mute is never weakened by another list.
  ///
  /// Whether a message mentions somebody is decided on the client, because the
  /// server cannot read it: bodies are sealed with the channel key and this
  /// service stores a preference, not a message.
  mentionOnlyChannelIds String[] @default([])
  /// People this account never wants raised, wherever they write.
  ///
  /// A channel mute is the wrong tool for one loud person in five channels, and
  /// leaving is the wrong tool for a colleague. Same shape and same reasoning
  /// as the two lists above: small, read whole, and applied on the client -
  /// which is the only side that knows who wrote a sealed message, since the
  /// author is on the envelope but the decision to raise anything is not.
  mutedUserIds          String[] @default([])
  updatedAt             DateTime @updatedAt

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@map("notification_settings")
}

/// How far a user has read a channel. Unread counts are derived from it rather
/// than stored, so they survive a restart and follow the account to another
/// machine instead of living in one client's memory.
model ChannelRead {
  userId     String
  channelId  String
  lastReadAt DateTime  @default(now())
  /// Messages older than this are not returned to this user *in this channel*.
  /// The per-conversation half of `User.chatsClearedAt`, and it lives here
  /// rather than in a table of its own because this row is already the one
  /// thing keyed on exactly (user, channel) - a second table would be the same
  /// key, the same cascade and the same lookup, twice.
  ///
  /// The two are read together: the floor is whichever is later.
  clearedAt  DateTime?

  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)
  channel Channel @relation(fields: [channelId], references: [id], onDelete: Cascade)

  @@id([userId, channelId])
  @@index([channelId])
  @@map("channel_reads")
}

/// One installation's push token, owned by notification-service.
///
/// Keyed on (user, device) and not on the token. A registration token rotates -
/// FCM mints a new one after a restore, a clear-data, or on its own schedule -
/// so a registry keyed on the token grows a row per rotation and then pushes to
/// every dead one. `deviceId` is the same client-minted installation id
/// `DeviceKey` uses, which makes one phone one row for as long as the app is
/// installed.
///
/// The token is also unique on its own, because the *device* can move between
/// accounts: signing out and into another account on the same phone gives that
/// account the same token, and the row it used to belong to has to go rather
/// than keep pushing somebody else's messages at it.
model DeviceToken {
  id         String   @id @default(uuid())
  userId     String
  /// Client-minted, stable per installation.
  deviceId   String
  /// The FCM registration token. Never logged - see section 23 of CLAUDE.md.
  token      String   @unique
  /// android | ios | web. A string rather than an enum: adding a transport
  /// should not be a migration.
  platform   String
  /// What to call it in a list: "Pixel 8". Client-supplied and untrusted.
  label      String?
  /// The client build, so a push a version cannot render can be skipped.
  appVersion String?
  lastSeenAt DateTime @default(now())
  createdAt  DateTime @default(now())
  updatedAt  DateTime @updatedAt

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([userId, deviceId])
  @@index([userId])
  @@map("device_tokens")
}

/// A third-party login linked to an account. The provider's own user id is what
/// identifies the person on the next login; email can change on their side.
model UserIdentity {
  id                String   @id @default(uuid())
  userId            String
  provider          String
  providerAccountId String
  email             String?
  createdAt         DateTime @default(now())

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([provider, providerAccountId])
  @@index([userId])
  @@map("user_identities")
}

/// OAuth provider credentials, configured from the admin panel rather than the
/// environment, so enabling a login is an operator action and not a redeploy.
/// `clientSecret` is stored sealed - see packages/auth `sealSecret`.
model OAuthProvider {
  provider     String   @id
  enabled      Boolean  @default(false)
  clientId     String
  clientSecret String
  createdAt    DateTime @default(now())
  updatedAt    DateTime @updatedAt

  @@map("oauth_providers")
}

/// One machine's end-to-end encryption identity key (ECDH P-256, JWK, public
/// half only). The private half never leaves that machine in the clear.
///
/// A list per user rather than one row per user, which is the difference
/// between "this account has a key" and "this laptop has a key". It buys two
/// things the single row could not: a device can be revoked on its own, without
/// rotating an identity every other machine is also using, and a channel key is
/// wrapped for the devices that should have it rather than for an identity that
/// has been copied to who-knows-where.
///
/// `deviceId` is minted by the client and is stable for an installation. A
/// revoked row is kept rather than deleted: the wraps addressed to it go, but
/// the record of what was trusted and when it stopped being trusted is the only
/// thing anybody can audit afterwards.
model DeviceKey {
  id         String    @id @default(uuid())
  userId     String
  /// Client-minted, stable per installation.
  deviceId   String
  publicKey  String
  /// What to call it in a list: "Ada's laptop", "Pixel 8". Client-supplied.
  label      String?
  /// Set when the owner revoked it. Nothing is wrapped for a revoked device.
  revokedAt  DateTime?
  lastSeenAt DateTime  @default(now())
  createdAt  DateTime  @default(now())
  updatedAt  DateTime  @updatedAt

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([userId, deviceId])
  @@index([userId])
  @@map("device_keys")
}

/// The identity private key, sealed on the client with a key derived from a
/// secret the server never receives (PBKDF2 over the account password, or over
/// a passphrase the user set). Without it, wiping an installation - or signing
/// in on a second machine - meant a new identity and a history nobody could
/// open. The server stores the blob and hands it back to its owner; it holds
/// nothing that opens it.
model IdentityBackup {
  id         String   @id @default(uuid())
  userId     String
  version    Int      @default(1)
  /// "password" or "passphrase": what the client must ask the user for.
  kind       String
  kdf        String
  iterations Int
  salt       String
  iv         String
  ciphertext String
  /// Public half of the sealed pair, so a client can recognise a stale backup.
  publicKey  String
  createdAt  DateTime @default(now())
  updatedAt  DateTime @updatedAt

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  /// One backup per secret kind, not one per account. A recovery passphrase
  /// used to replace the password-sealed blob, which quietly took away the
  /// only thing a fresh sign-in can open on its own - see development/devdocs/E2EE.md.
  @@unique([userId, kind])
  @@index([userId])
  @@map("identity_backups")
}

/// A channel's symmetric content key, wrapped once per recipient. The server
/// stores only ciphertext it cannot open: `wrappedKey` is sealed with the ECDH
/// secret between `senderPublicKey` and the recipient's device key.
model ChannelKey {
  id                String   @id @default(uuid())
  channelId         String
  epoch             Int
  recipientUserId   String
  /// Which of that user's devices this copy is sealed for. One row per device,
  /// because a wrap is to a key and a key belongs to a machine.
  recipientDeviceId String
  senderUserId      String
  /// Which machine did the sealing, so a wrap can be attributed after the fact.
  senderDeviceId    String
  senderPublicKey   String
  wrappedKey        String
  iv                String
  createdAt         DateTime @default(now())

  channel Channel @relation(fields: [channelId], references: [id], onDelete: Cascade)

  @@unique([channelId, epoch, recipientUserId, recipientDeviceId])
  @@index([channelId, recipientUserId])
  @@map("channel_keys")
}

model RefreshToken {
  // `id` is the JWT `jti`, so revoking a token is a delete by id.
  id        String    @id
  userId    String
  // The sign-in this token descends from: the `id` of the token that sign-in
  // minted, carried forward by every rotation of it. One device is one family,
  // so a token replayed on a phone cannot sign the same account out of a
  // laptop - which is what revoking by `userId` did.
  familyId  String
  tokenHash String
  expiresAt DateTime
  createdAt DateTime  @default(now())
  revokedAt DateTime?

  user User @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@index([userId])
  @@index([familyId])
  @@map("refresh_tokens")
}

model Server {
  id        String   @id @default(uuid())
  name      String
  slug      String   @unique
  iconUrl   String?
  ownerId   String
  /// How long a message sent in this server's channels lives, in seconds, or
  /// null for "for ever". Set by whoever holds MANAGE_SERVER, and it binds
  /// every member: the sweeper destroys the row and its blobs when the window
  /// closes, so this is a deletion and not a filter.
  ///
  /// Stamped onto each message as it is sent rather than evaluated at read
  /// time, so changing the window governs what is sent next and never
  /// retroactively resurrects or condemns what is already there.
  messageTtlSeconds Int?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  owner    User               @relation("ServerOwner", fields: [ownerId], references: [id], onDelete: Cascade)
  members  ServerMember[]
  channels Channel[]
  invites  ServerInvite[]
  roles    ServerCustomRole[]
  emoji    ServerEmoji[]

  @@index([ownerId])
  @@map("servers")
}

/// A role a server invented for itself: a name, a colour, a place in the list,
/// and a bundle of permissions.
///
/// It does not replace `ServerRole`. The five built-ins are the hierarchy - who
/// may edit whom, who may hand out what - and that stays a ladder with a fixed
/// number of rungs, because a hierarchy anyone can extend is a hierarchy anyone
/// can climb. A custom role is additive: it grants permissions on top, and a
/// member's denials still win over it, so taking a capability away from one
/// person never depends on which roles they happen to hold.
model ServerCustomRole {
  id          String   @id @default(uuid())
  serverId    String
  name        String
  /// `#rrggbb`, or null for a role that takes the default colour. A member
  /// shows the colour of the highest-ranked role they hold that has one.
  colour      String?
  /// Higher is further up the list. Display order, and the tie-break for whose
  /// colour a member wears; it grants nothing by itself.
  rank        Int      @default(0)
  /// Names from the assignable set. Unknown strings are ignored when resolving,
  /// so a role written by a newer build cannot break an older one.
  permissions String[] @default([])
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  server  Server             @relation(fields: [serverId], references: [id], onDelete: Cascade)
  members ServerMemberRole[]

  /// Two roles with the same name in one server are a support ticket.
  @@unique([serverId, name])
  @@index([serverId, rank])
  @@map("server_custom_roles")
}

/// One member holding one custom role. A member may hold any number.
model ServerMemberRole {
  memberId   String
  roleId     String
  assignedAt DateTime @default(now())

  member ServerMember     @relation(fields: [memberId], references: [id], onDelete: Cascade)
  role   ServerCustomRole @relation(fields: [roleId], references: [id], onDelete: Cascade)

  @@id([memberId, roleId])
  @@index([roleId])
  @@map("server_member_roles")
}

/// A way in that can be taken away again.
///
/// The slug was the only way to join, and a slug is permanent, public and
/// guessable from the server's name: handing it to one person handed it to
/// everyone they ever forward it to, forever. An invite is a code with an
/// optional expiry and an optional cap on how many times it may be used, and
/// revoking it is a column rather than renaming the server.
model ServerInvite {
  id          String    @id @default(uuid())
  /// Random and unguessable, not derived from the server's name.
  code        String    @unique
  serverId    String
  /// Null once the account that made it is deleted; the invite is the server's,
  /// not theirs, so it outlives them.
  createdById String?
  /// Null for an invite that does not expire, which is a deliberate choice
  /// somebody has to make rather than the only behaviour available.
  expiresAt   DateTime?
  /// Null for unlimited. Counted rather than decremented so a spent invite
  /// still says how popular it was.
  maxUses     Int?
  uses        Int       @default(0)
  revokedAt   DateTime?
  createdAt   DateTime  @default(now())

  server    Server @relation(fields: [serverId], references: [id], onDelete: Cascade)
  createdBy User?  @relation("ServerInviteCreatedBy", fields: [createdById], references: [id], onDelete: SetNull)

  @@index([serverId])
  @@map("server_invites")
}

model ServerMember {
  id                 String     @id @default(uuid())
  serverId           String
  userId             String
  role               ServerRole @default(MEMBER)
  /// Permissions this member holds beyond the role's defaults, so an
  /// administrator can hand one person one capability without inventing a role.
  grantedPermissions String[]   @default([])
  /// Permissions withheld even though the role would grant them. Deny wins.
  deniedPermissions  String[]   @default([])
  /// Whether this member was let in *with* what was said before they arrived.
  ///
  /// A newcomer normally reads from the moment they join and no further back:
  /// they hold no earlier epoch, nobody may hand them one, and every message
  /// before that stays a padlock. That is the right default and it stays the
  /// default. But it is a decision somebody should be able to make, and the
  /// server cannot make it - it holds no key - so this is the flag the clients
  /// act on: with it set, the key directory offers this member's devices every
  /// epoch of every channel in the server rather than only the ones they
  /// already hold somewhere, and the first member's machine to open the channel
  /// seals them. See `gaps()` in chat-service's e2ee service.
  ///
  /// It is not retroactive in the other direction: clearing it takes nothing
  /// back, because a key that has been sealed for a device has been sealed.
  historyShared      Boolean    @default(false)
  joinedAt           DateTime   @default(now())

  server Server             @relation(fields: [serverId], references: [id], onDelete: Cascade)
  user   User               @relation(fields: [userId], references: [id], onDelete: Cascade)
  roles  ServerMemberRole[]

  @@unique([serverId, userId])
  @@index([userId])
  @@map("server_members")
}

model Channel {
  id        String      @id @default(uuid())
  /// Null for a direct message, which belongs to its two participants rather
  /// than to a server.
  serverId  String?
  name      String
  type      ChannelType @default(TEXT)
  topic     String?
  /// A private channel is visible only to the users listed in `members`. Server
  /// membership grants nothing here - not even to an administrator, who has to
  /// be added like anyone else. See development/PLANNING.md (phase 12).
  isPrivate Boolean     @default(false)
  createdAt DateTime    @default(now())
  updatedAt DateTime    @updatedAt

  server   Server?         @relation(fields: [serverId], references: [id], onDelete: Cascade)
  members  ChannelMember[]
  messages Message[]
  keys     ChannelKey[]
  reads    ChannelRead[]
  webhooks Webhook[]

  @@unique([serverId, name])
  @@map("channels")
}

/// A URL an outside system can POST to in order to say something in a channel.
///
/// Discord's shape, because it is the one every CI runner, alerting stack and
/// "send to chat" integration already speaks: one opaque URL carrying its own
/// authority, a JSON body with a `content` field, and no account, OAuth flow
/// or bot framework anywhere near it. A webhook that needed its own client
/// library would not be reachable from the `curl` in somebody's deploy script,
/// which is the entire point of having one.
///
/// **This is the one place a message body is stored in the clear, and it is a
/// deliberate, visible exception rather than a hole.** The sealed-envelope
/// design assumes every author holds the channel key; a build server does not,
/// cannot be given one (handing a channel key to a script is handing away the
/// channel), and could not use one without shipping this project's crypto to
/// every language anybody writes a deploy script in. So the trade is made
/// explicitly and shown to people rather than hidden: `Message.kind` is
/// `WEBHOOK`, and every client draws the row with a badge saying it was not
/// encrypted. A channel with a webhook on it is a channel whose E2EE guarantee
/// is now "everything except what the robots say", and the clients say exactly
/// that instead of implying more.
///
/// The token is stored as a SHA-256 hash and shown once, at creation - the same
/// rule as `RemoteMachine.agentTokenHash` and `PasswordReset.tokenHash`.
/// Discord shows its webhook URLs again on demand, which requires keeping them
/// reversible; a token that can be re-read out of a database is a token a
/// database dump hands over. Losing it is recoverable by rotating it, which is
/// what the endpoint exists for.
model Webhook {
  id          String    @id @default(uuid())
  channelId   String
  /// SHA-256 of the token half of the URL. Unique, so a delivery is one indexed
  /// lookup rather than a scan of every webhook on the deployment.
  tokenHash   String    @unique
  /// What the messages are signed with. Not a username and not unique: it is a
  /// label on a robot, and two servers may both have one called "deploys".
  name        String
  /// An uploaded picture, or null for the initial drawn from `name`.
  avatarUrl   String?
  /// Who made it. Kept for the audit trail and for `Message.authorId`, which is
  /// not nullable - a webhook row is attributed to the person who opened the
  /// door, and the clients draw the webhook's name over the top.
  createdById String
  /// Null until something has actually posted through it. The first thing
  /// anybody wants to know about a webhook that "isn't working".
  lastUsedAt  DateTime?
  createdAt   DateTime  @default(now())
  updatedAt   DateTime  @updatedAt

  channel   Channel   @relation(fields: [channelId], references: [id], onDelete: Cascade)
  createdBy User      @relation("WebhookCreatedBy", fields: [createdById], references: [id], onDelete: Cascade)
  messages  Message[]

  @@index([channelId])
  @@map("webhooks")
}

/// One row per user allowed into a private channel. Rows on a public channel
/// are ignored, so making a channel private later needs no backfill.
model ChannelMember {
  id        String   @id @default(uuid())
  channelId String
  userId    String
  addedAt   DateTime @default(now())

  channel Channel @relation(fields: [channelId], references: [id], onDelete: Cascade)
  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([channelId, userId])
  @@index([userId])
  @@map("channel_members")
}

/// One row per relationship, not one per direction: a request and a friendship
/// are the same thing in two states. The pair is stored with the lower user id
/// first so the unique constraint catches two people requesting each other.
model Friendship {
  id          String           @id @default(uuid())
  userAId     String
  userBId     String
  /// Who sent the request. Only the other side may accept it.
  requesterId String
  status      FriendshipStatus @default(PENDING)
  createdAt   DateTime         @default(now())
  updatedAt   DateTime         @updatedAt

  userA User @relation("FriendshipA", fields: [userAId], references: [id], onDelete: Cascade)
  userB User @relation("FriendshipB", fields: [userBId], references: [id], onDelete: Cascade)

  @@unique([userAId, userBId])
  @@index([userBId])
  @@map("friendships")
}

/// A server's own emoji: a picture and a name people type between colons.
///
/// The picture is an ordinary upload under `pictures/`, which is the one thing
/// this deployment serves without authentication - it has to be, because an
/// `<img>` tag cannot carry a header, and an emoji is drawn a hundred times a
/// screen. So an emoji is public by construction, and nothing about it is
/// secret: the name and the image are exactly what everybody in the server is
/// meant to see.
///
/// What is *not* here is any link to a message. A message body is sealed, so
/// which emoji a message uses is not a question this table could answer even
/// if it wanted to - the client carries the manifest inside the envelope.
model ServerEmoji {
  id          String   @id @default(uuid())
  serverId    String
  /// Lowercase letters, digits and underscores - what fits between two colons.
  name        String
  /// Storage URL of the picture, rooted at `/api/v1/uploads/pictures/...`.
  url         String
  /// True for a GIF or an animated WebP. Stored rather than sniffed so a client
  /// can decide whether to draw it still until it is hovered.
  animated    Boolean  @default(false)
  /// Null once the uploader's account is gone; the emoji outlives them.
  createdById String?
  createdAt   DateTime @default(now())

  server Server @relation(fields: [serverId], references: [id], onDelete: Cascade)

  @@unique([serverId, name])
  @@index([serverId])
  @@map("server_emoji")
}

/// What a row in a conversation *is*.
///
/// `USER` is a message somebody wrote, and its body is ciphertext nothing here
/// can read. `MEMBER_JOIN` is the conversation noting that somebody arrived -
/// written by the server, addressed to nobody, and carrying no body at all.
///
/// The two are separated by a column rather than by a marker inside the body
/// for the obvious reason: the server writes the second kind and cannot write
/// the first, because it holds no key. A client reads the kind and draws the
/// line itself, which is also why nothing about the phrasing is stored.
enum MessageKind {
  USER
  MEMBER_JOIN
  /// Posted by an outside system through a `Webhook`. Unlike `USER`, `content`
  /// is **plaintext**: the sender holds no channel key and cannot seal it. See
  /// the `Webhook` model for why that is a deliberate, visible exception.
  WEBHOOK
}

model Message {
  id          String    @id @default(uuid())
  channelId   String
  authorId    String
  /// Which sort of row this is; see [MessageKind]. `USER` unless the server
  /// wrote it, which keeps every row that existed before this column correct.
  kind        MessageKind @default(USER)
  // Opaque to the server: clients store a serialised `EncryptedEnvelope` here.
  /// Empty for every kind but `USER`: there is nothing to say that the kind and
  /// the author do not already say, and an empty string is honest about that in
  /// a way a server-written sentence in one language would not be.
  content     String
  createdAt   DateTime  @default(now())
  editedAt    DateTime?
  deletedAt   DateTime?
  /// Who deleted it, when that was not the author - a client shows "deleted by
  /// NAME" rather than pretending the author took it back.
  deletedById String?
  pinnedAt    DateTime?
  pinnedById  String?
  /// When this message stops existing, stamped from the server's disappearing
  /// window at send time. Null means it stays until somebody deletes it. The
  /// disappearing sweeper destroys the row outright rather than tombstoning
  /// it: a tombstone that says "a message was here" for ever is not what a
  /// disappearing message was asked to be.
  expiresAt   DateTime?
  /// A one-time message: each recipient may open its media once, and it is
  /// destroyed once every one of them has.
  ///
  /// The flag is outside the encrypted body because the server has to act on
  /// it - burning is a row update and a blob delete, and a server that cannot
  /// read the body cannot be told by the body. What leaks is that some message
  /// was one-time, which is a fact both clients already draw on screen.
  viewOnce    Boolean           @default(false)
  /// When the *first* recipient opened it. Not the gate - `views` is - but the
  /// stamp a backstop expiry is measured from, so a one-time message nobody
  /// finishes opening still leaves eventually.
  viewedAt    DateTime?
  /// Which webhook posted this, when one did. Set exactly when `kind` is
  /// `WEBHOOK`, and what a client reads the name and picture off - `author` is
  /// the account that created the webhook, which is not who the row is from.
  webhookId   String?

  channel     Channel           @relation(fields: [channelId], references: [id], onDelete: Cascade)
  author      User              @relation(fields: [authorId], references: [id], onDelete: Cascade)
  deletedBy   User?             @relation("MessageDeletedBy", fields: [deletedById], references: [id], onDelete: SetNull)
  pinnedBy    User?             @relation("MessagePinnedBy", fields: [pinnedById], references: [id], onDelete: SetNull)
  /// `SetNull` rather than `Cascade`: deleting a webhook must not delete what
  /// it has already said. The rows stay and fall back to the name frozen into
  /// their own body.
  webhook     Webhook?          @relation(fields: [webhookId], references: [id], onDelete: SetNull)
  reactions   MessageReaction[]
  attachments Attachment[]
  views       MessageView[]

  // History paging reads newest-first within a channel.
  @@index([channelId, createdAt])
  // The pinned panel lists one channel's pins, newest pin first.
  @@index([channelId, pinnedAt])
  // The disappearing sweeper reads whatever is past its window, oldest first.
  @@index([expiresAt])
  @@map("messages")
}

/// One person's one look at a one-time message.
///
/// A row per viewer rather than a single `viewedAt` on the message, because a
/// one-time message has as many looks in it as there are people who can see
/// it. The single stamp meant the first person to open one in a channel
/// destroyed it for everybody else, who then saw "Opened" for something they
/// had never been shown - which is not one look each, it is one look in total
/// and a race to it.
///
/// The message is destroyed when this table covers everyone who could see it,
/// minus the author - who is not a viewer, because re-reading what you sent
/// spends nobody's look.
model MessageView {
  id        String   @id @default(uuid())
  messageId String
  userId    String
  viewedAt  DateTime @default(now())

  message Message @relation(fields: [messageId], references: [id], onDelete: Cascade)
  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([messageId, userId])
  @@index([messageId])
  @@map("message_views")
}

/// One person's one emoji on one message.
///
/// The emoji is stored in the clear, unlike everything else about a message.
/// That is a deliberate, documented leak (see development/E2EE.md): the server
/// has to group and count reactions for people who hold no channel key at the
/// moment they ask, and an encrypted-per-recipient reaction would cost a key
/// exchange per thumbs-up.
model MessageReaction {
  id        String   @id @default(uuid())
  messageId String
  userId    String
  emoji     String
  createdAt DateTime @default(now())

  message Message @relation(fields: [messageId], references: [id], onDelete: Cascade)
  user    User    @relation(fields: [userId], references: [id], onDelete: Cascade)

  @@unique([messageId, userId, emoji])
  @@index([messageId])
  @@map("message_reactions")
}

/// One uploaded blob, and which message claims it.
///
/// This row exists for one reason: nothing else can say which object belongs to
/// which message. The manifest naming a message's files is *inside* the
/// encrypted body, so no service can read it, and without a row here a deleted
/// message left its ciphertext in storage for ever. The alternative - the
/// deleting client removing what it can read - leaves behind everything a
/// moderator deletes, which is exactly the case that matters.
///
/// What this costs is one small piece of metadata: the server learns that some
/// number of blobs, of some size, belong to one message. It already knew the
/// blobs and their sizes; the name, the type and the contents stay sealed.
///
/// Neither foreign key cascades, deliberately. A row destroyed by somebody
/// else's cascade is a blob nothing will ever name again, so both go null
/// instead and the sweeper - which looks for rows no message claims - collects
/// the object. That makes one mechanism cover a deleted message, a deleted
/// channel, a deleted server, a deleted account and an upload nobody ever sent.
model Attachment {
  id         String   @id @default(uuid())
  /// The storage key. Unique: one row per object, so claiming twice is caught.
  key        String   @unique
  /// Null once the account that uploaded it is gone. See the note above.
  uploaderId String?
  /// Ciphertext length, which is not the plaintext size and is not meant to be.
  size       Int
  /// Null until the message carrying it is sent, and null again if that message
  /// row is destroyed rather than tombstoned.
  messageId  String?
  createdAt  DateTime @default(now())

  uploader User?    @relation("AttachmentUploader", fields: [uploaderId], references: [id], onDelete: SetNull)
  message  Message? @relation(fields: [messageId], references: [id], onDelete: SetNull)

  @@index([messageId])
  /// The sweeper reads unclaimed rows oldest first.
  @@index([createdAt])
  @@map("attachments")
}

// --- Remote desktop (phase 17) ------------------------------------------------
//
// Kept apart from chat and media on purpose: a remote session is the most
// dangerous thing this platform can do, so it has its own service, its own
// permission set that no role grants by default, and its own audit trail.

/// A machine that has enrolled an agent. The agent connects outbound to
/// remote-gateway; nothing ever dials the machine, and no inbound port is
/// opened on it.
model RemoteMachine {
  id       String @id @default(uuid())
  /// Whoever enrolled it. The owner always has every remote permission on it
  /// and is the only one who may hand them out.
  ownerId  String
  name     String
  platform String

  /// The agent's credential, stored as a SHA-256 hash the way a password is.
  /// It is shown once, at enrolment, and rotated by enrolling again.
  ///
  /// ponytail: a shared secret, not a device keypair. It is what cloudflared
  /// and every other outbound agent uses; a signed handshake is the upgrade if
  /// a stolen token at rest ever becomes the threat that matters.
  ///
  /// Unique, and indexed by being so: an agent connecting is one lookup rather
  /// than a scan of every machine's hash.
  agentTokenHash String    @unique
  /// Null until the agent has connected once.
  lastSeenAt     DateTime?
  createdAt      DateTime  @default(now())
  updatedAt      DateTime  @updatedAt

  owner    User            @relation("RemoteMachineOwner", fields: [ownerId], references: [id], onDelete: Cascade)
  grants   RemoteGrant[]
  sessions RemoteSession[]
  audit    RemoteAudit[]

  @@index([ownerId])
  @@map("remote_machines")
}

/// What one person may do to one machine. Absent means no access at all -
/// remote permissions are never implied by a server role.
model RemoteGrant {
  id          String    @id @default(uuid())
  machineId   String
  userId      String
  /// REMOTE_VIEW, REMOTE_CONTROL, REMOTE_FILE_TRANSFER, REMOTE_CLIPBOARD,
  /// REMOTE_AUDIO, REMOTE_ADMIN. Unknown strings are ignored when resolving,
  /// so a row written by a newer build cannot break an older one.
  permissions String[]  @default([])
  /// Temporary access: past this moment the grant resolves to nothing. Null is
  /// open-ended.
  expiresAt   DateTime?
  grantedById String?
  createdAt   DateTime  @default(now())
  updatedAt   DateTime  @updatedAt

  machine   RemoteMachine @relation(fields: [machineId], references: [id], onDelete: Cascade)
  user      User          @relation("RemoteGrantUser", fields: [userId], references: [id], onDelete: Cascade)
  grantedBy User?         @relation("RemoteGrantGrantedBy", fields: [grantedById], references: [id], onDelete: SetNull)

  @@unique([machineId, userId])
  @@index([userId])
  @@map("remote_grants")
}

/// One connection from one person to one machine. The permissions are frozen
/// when it starts, so revoking a grant mid-session is a decision the gateway
/// takes deliberately (it ends the session) rather than an accident of timing.
model RemoteSession {
  id          String    @id @default(uuid())
  machineId   String
  userId      String
  permissions String[]  @default([])
  startedAt   DateTime  @default(now())
  endedAt     DateTime?
  /// Why it stopped: "controller", "agent", "revoked", "agent-offline".
  endedReason String?

  machine RemoteMachine @relation(fields: [machineId], references: [id], onDelete: Cascade)
  user    User          @relation("RemoteSessionUser", fields: [userId], references: [id], onDelete: Cascade)
  audit   RemoteAudit[]

  @@index([machineId, startedAt])
  @@index([userId, startedAt])
  @@map("remote_sessions")
}

/// Append-only record of everything that happened to a machine. Nothing here is
/// ever updated or deleted by the application; a machine's owner can read it.
model RemoteAudit {
  id        String  @id @default(uuid())
  machineId String
  sessionId String?
  /// Who did it. Null when it was the agent itself rather than a person.
  actorId   String?
  /// machine.enrolled, machine.renamed, permission.changed, session.started,
  /// session.ended, session.refused.
  action    String
  detail    Json?

  createdAt DateTime @default(now())

  machine RemoteMachine  @relation(fields: [machineId], references: [id], onDelete: Cascade)
  session RemoteSession? @relation(fields: [sessionId], references: [id], onDelete: SetNull)
  actor   User?          @relation("RemoteAuditActor", fields: [actorId], references: [id], onDelete: SetNull)

  @@index([machineId, createdAt])
  @@map("remote_audit")
}

/// One person's stay in one call: how long they were in it, who else was there
/// while they were, and how much data their machine moved doing it.
///
/// Written by `call-service`, which holds the sockets and is therefore the only
/// thing that knows when somebody actually arrived and left - a client's own
/// account of that is a client that can write itself an hour-long call it never
/// joined.
///
/// The names are snapshots rather than joins on purpose. A call log is history,
/// and a channel that was deleted or a server that was left is exactly the
/// entry somebody is trying to remember; a foreign key would take those rows
/// away at the moment they became interesting.
model CallSession {
  id            String    @id @default(uuid())
  userId        String
  channelId     String
  channelName   String
  /// Null for a direct message, which belongs to no server.
  serverId      String?
  serverName    String?
  joinedAt      DateTime  @default(now())
  /// Null while the call is still up, and for a row whose process died mid-call.
  endedAt       DateTime?
  /// Everybody else who was in the call at any point while this person was, by
  /// user id. Resolved to current names when the log is read, so somebody who
  /// changed their display name reads back as who they are now.
  peerIds       String[]  @default([])
  /// Bytes sent and received across every peer connection of this call, as the
  /// client counted them - nothing else is in the media path to count. Zero
  /// when the client never got to report, which a window closed mid-call does.
  bytes         BigInt    @default(0)
  /// The same total split by direction. Kept beside `bytes` rather than derived
  /// from it because an older client reports only the total, and a split that
  /// guessed at halves would read as measurement rather than as the guess it is.
  bytesSent     BigInt    @default(0)
  bytesReceived BigInt    @default(0)
  /// One entry per person this client held a peer connection to: what that link
  /// moved, how it got there (direct or through a relay), its round trip and its
  /// loss. A `CallLinkReport[]` from shared-types, written verbatim after
  /// clamping - see `usage.ts`.
  ///
  /// ponytail: JSON rather than a table. It is read whole, per row, by the one
  /// person it belongs to, and nothing ever queries across it. A join table is
  /// the upgrade if a report is ever wanted for a whole deployment.
  links         Json?

  user User @relation("CallSessionUser", fields: [userId], references: [id], onDelete: Cascade)

  @@index([userId, joinedAt])
  @@map("call_sessions")
}

// --- Status (phase 30) --------------------------------------------------------
//
// A status is a post that expires. It is deliberately not a message: it has no
// channel, no conversation to belong to, no reply, and its audience is a set
// (accepted friends) rather than a room. Modelling it as a message in a hidden
// channel would have meant a channel per account, a membership row per friend
// kept in step with the friend list, and a message table where half the rows
// are not messages.
//
// **End-to-end encrypted, with the audience frozen at post time.** Sealing a
// post with no channel means choosing between re-wrapping a key for every new
// friendship and freezing the audience when it is written; freezing is the
// choice, and it is also the behaviour that was wanted - somebody who becomes
// your friend tomorrow does not see what you posted today. `status_keys` holds
// one wrap per recipient device and *is* the audience: no row, no key, nothing
// to read. See `docs/docs/security/e2ee.md`.

/// What a status is made of.
enum StatusKind {
  PHOTO
  VIDEO
  /// No media at all: a caption drawn on a colour, which is the third thing
  /// WhatsApp lets you post and the one that needs no upload.
  TEXT
}

/// One post, alive for 24 hours.
model Status {
  id         String     @id @default(uuid())
  authorId   String
  kind       StatusKind
  /// The storage key of the photo or video, rooted at `status/<authorId>/`.
  /// Null for TEXT. The `status/` prefix is what the download route reads to
  /// know this object is gated by friendship rather than by channel access.
  mediaKey   String?
  /// The IV the media was sealed with, base64. Null for TEXT.
  mediaIv    String?
  /// What the sealed bytes are once opened - `image/jpeg`, `video/mp4`. In the
  /// clear on purpose: the server holds ciphertext and cannot sniff it, and a
  /// client needs a type to hand the decoder.
  mediaType  String?
  /// The caption under a photo, or the whole of a TEXT status, sealed: an
  /// `EncryptedEnvelope` as JSON, never the words. Capped by the DTO at
  /// STATUS_CAPTION_SEALED_MAX_LENGTH, which is the only cap a ciphertext has.
  caption    String?
  /// The colour a TEXT status is drawn on, as a CSS hex the client picked from
  /// a fixed palette. Null for media, which is its own background.
  background String?
  /// How long a video runs, in milliseconds, as the client measured it. It is
  /// what times the progress bar; a photo uses the client's fixed step and
  /// leaves this null.
  durationMs Int?
  createdAt  DateTime   @default(now())
  /// createdAt + 24h, stamped at write time for the same reason a disappearing
  /// message stamps its own: the sweep then has nothing to decide.
  expiresAt  DateTime

  author User         @relation("StatusAuthor", fields: [authorId], references: [id], onDelete: Cascade)
  views  StatusView[]
  keys   StatusKey[]

  /// The feed reads one author's live posts, oldest first.
  @@index([authorId, createdAt])
  /// The sweep reads what is past its stamp.
  @@index([expiresAt])
  @@map("statuses")
}

/// One status key, sealed for one device.
///
/// This table is the audience, and that is the whole of the design: a status
/// has no channel to inherit membership from, so the author wraps its key for
/// every device of every friend it had *at the moment it was posted*. A
/// friendship made afterwards adds no row, which is why a new friend does not
/// see yesterday's post - the same rule every app with this feature has, here
/// enforced by arithmetic rather than by a query the server is trusted to run.
///
/// No epoch, unlike `ChannelKey`: a status is written once and gone in a day,
/// so there is nothing to rotate.
model StatusKey {
  id                String   @id @default(uuid())
  statusId          String
  recipientUserId   String
  /// Which of that user's devices this copy is sealed for. One row per device.
  recipientDeviceId String
  /// Which machine did the sealing, so a wrap can be attributed after the fact.
  senderDeviceId    String
  senderPublicKey   String
  wrappedKey        String
  iv                String
  createdAt         DateTime @default(now())

  status Status @relation(fields: [statusId], references: [id], onDelete: Cascade)

  @@unique([statusId, recipientDeviceId])
  /// The tray asks "which live posts is there a wrap for me on".
  @@index([recipientUserId])
  @@map("status_keys")
}

/// Somebody opened somebody else's status.
///
/// One row per pair, not one per open: "seen" is a fact, and a table that grew
/// a row every time a story was re-opened would be a view counter nobody asked
/// for. The author reads these as the viewer list; every other account can
/// only ever read its own.
model StatusView {
  id       String   @id @default(uuid())
  statusId String
  viewerId String
  viewedAt DateTime @default(now())

  status Status @relation(fields: [statusId], references: [id], onDelete: Cascade)
  viewer User   @relation("StatusViewer", fields: [viewerId], references: [id], onDelete: Cascade)

  @@unique([statusId, viewerId])
  @@index([viewerId])
  @@map("status_views")
}

/**
 * `/ws/chat` realtime gateway.
 *
 * Sockets subscribe to channels they may read; delivery is driven by the Redis
 * `message.created` event, so every chat-service instance broadcasts to its own
 * sockets and horizontal scaling needs no sticky sessions.
 */
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import type { Server as HttpServer } from 'node:http';
import { WebSocket, WebSocketServer } from 'ws';
import { prisma } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { PERMISSIONS } from '@betweenus/permissions';
import {
  CONTROL_MAX_PAYLOAD,
  RoomRegistry,
  authenticateHandshake,
  channelRoom,
  dropRevokedSockets,
  serverRoom,
  userRoom,
} from '@betweenus/websocket';
import { Logger } from '@betweenus/logger';
import type { ClientChatEvent, ServerChatEvent, UserSummary } from '@betweenus/shared-types';
import { MessagesService } from '../modules/messages/messages.service';

const HEARTBEAT_INTERVAL_MS = 30_000;

interface SocketState {
  userId: string;
  username: string;
  alive: boolean;
  /** `iat` of the token that opened this socket. See `dropRevokedSockets`. */
  issuedAt: number;
}

@Injectable()
export class ChatGateway implements OnModuleDestroy {
  private server: WebSocketServer | null = null;
  private heartbeat: NodeJS.Timeout | null = null;
  private readonly rooms = new RoomRegistry<WebSocket>();
  private readonly state = new WeakMap<WebSocket, SocketState>();

  constructor(
    private readonly messages: MessagesService,
    private readonly events: EventBus,
    private readonly logger: Logger,
  ) {}

  /**
   * Every socket this instance holds for one account.
   *
   * Scanned rather than looked up in a room, because the four gateways keep
   * different bookkeeping and `clients` is the one thing all of them have. A
   * revocation is rare; a scan of the sockets on one instance is nothing.
   */
  private socketsOf(userId: string): WebSocket[] {
    return [...(this.server?.clients ?? [])].filter(
      (socket) => this.state.get(socket)?.userId === userId,
    );
  }

  /** Called from main.ts once Nest owns a listening HTTP server. */
  async attach(httpServer: HttpServer): Promise<void> {
    this.server = new WebSocketServer({
      server: httpServer,
      path: '/ws/chat',
      maxPayload: CONTROL_MAX_PAYLOAD,
    });

    this.server.on('connection', (socket, request) => {
      const user = authenticateHandshake(request);
      if (!user) {
        // Never downgrade to anonymous: close with a policy-violation code.
        socket.close(4401, 'Unauthorized');
        return;
      }

      this.state.set(socket, {
        userId: user.id,
        username: user.username,
        alive: true,
        issuedAt: user.issuedAt,
      });
      // Everything addressed at a person rather than a place - a friend
      // request, an acceptance, being added to a server - is delivered here.
      this.rooms.join(userRoom(user.id), socket);
      this.send(socket, { type: 'ready', userId: user.id });
      this.logger.info('WebSocket connected', { userId: user.id });

      socket.on('pong', () => {
        const state = this.state.get(socket);
        if (state) state.alive = true;
      });

      socket.on('message', (raw) => {
        void this.handleClientEvent(socket, raw.toString());
      });

      socket.on('close', () => {
        this.rooms.leaveAll(socket);
        this.state.delete(socket);
        this.logger.info('WebSocket disconnected', { userId: user.id });
      });

      socket.on('error', (error) => {
        this.logger.warn('WebSocket error', { userId: user.id, reason: String(error) });
      });
    });

    // Drop sockets that stopped answering pings instead of leaking them.
    this.heartbeat = setInterval(() => {
      for (const socket of this.server?.clients ?? []) {
        const state = this.state.get(socket);
        if (!state) continue;
        if (!state.alive) {
          socket.terminate();
          continue;
        }
        state.alive = false;
        socket.ping();
      }
    }, HEARTBEAT_INTERVAL_MS);

    // An account whose authority was withdrawn loses the sockets it already
    // had, which is the half of a revocation that was missing: a handshake is
    // checked once and then trusted until it happens to disconnect.
    await dropRevokedSockets(
      this.events,
      (userId) => this.socketsOf(userId),
      (socket) => this.state.get(socket)?.issuedAt,
      (socket, code, reason) => socket.close(code, reason),
      (userId, count, reason) =>
        this.logger.info('Sockets revoked', { userId, count, reason }),
    );

    await this.events.subscribe(EVENTS.MESSAGE_CREATED, (envelope) => {
      const { message } = envelope.payload;
      this.broadcast(channelRoom(message.channelId), { type: 'message.created', message });
    });

    // An edit, a pin, a reaction and a deletion all reach the client as the
    // same event carrying the whole message - a deleted one is a tombstone with
    // `deletedAt` set, which is what the client has to draw.
    await this.events.subscribe(EVENTS.MESSAGE_UPDATED, (envelope) => {
      const { message } = envelope.payload;
      this.broadcast(channelRoom(message.channelId), { type: 'message.updated', message });
    });

    // Except when there is no tombstone. A one-time message that was opened,
    // and one whose disappearing window closed, are destroyed rather than
    // emptied - so what goes out is "forget this", not a message to redraw.
    await this.events.subscribe(EVENTS.MESSAGE_DELETED, (envelope) => {
      const { message, messageId, channelId } = envelope.payload;
      this.broadcast(
        channelRoom(channelId),
        message
          ? { type: 'message.updated', message }
          : { type: 'message.gone', messageId, channelId },
      );
    });

    // A read marker moved. Everyone subscribed to the channel is told, because
    // a read receipt is only useful to the person whose message was read - and
    // the marker is what every client derives "who has seen this" from.
    await this.events.subscribe(EVENTS.CHANNEL_READ, (envelope) => {
      const { channelId, userId, at } = envelope.payload;
      this.broadcast(channelRoom(channelId), { type: 'channel.read', channelId, userId, at });
    });

    // Somebody cleared their own history. It goes to that account's room and
    // nowhere else: every other participant's copy is exactly what it was, and
    // the only sockets that have anything to do are the ones holding this
    // account's own decrypted cache.
    await this.events.subscribe(EVENTS.CHATS_CLEARED, (envelope) => {
      const { userId, clearedAt, channelId } = envelope.payload;
      this.broadcast(userRoom(userId), { type: 'chats.cleared', clearedAt, channelId });
    });

    await this.events.subscribe(EVENTS.FRIEND_CHANGED, (envelope) => {
      for (const userId of envelope.payload.userIds) {
        this.broadcast(userRoom(userId), { type: 'friends.changed' });
      }
    });

    // Somebody posted, deleted, or aged out of a status. The audience was
    // worked out where the row was written - that is where the friend list
    // already was - so this only has to deliver it.
    await this.events.subscribe(EVENTS.STATUS_CHANGED, (envelope) => {
      const { userIds, authorId } = envelope.payload;
      this.deliver(userIds.map(userRoom), { type: 'status.changed', authorId });
    });

    // Every membership change reaches the same client event: the server's
    // watchers refresh their member list, and the person who joined, was
    // removed or had their permissions changed refreshes their own list of
    // servers - which is where the permissions their UI reads come from.
    for (const event of [
      EVENTS.SERVER_MEMBER_ADDED,
      EVENTS.SERVER_MEMBER_REMOVED,
      EVENTS.SERVER_MEMBER_UPDATED,
    ] as const) {
      await this.events.subscribe(event, (envelope) => {
        const { serverId, userId } = envelope.payload;
        this.deliver([serverRoom(serverId), userRoom(userId)], {
          type: 'server.members.changed',
          serverId,
        });
      });
    }

    // A renamed server, or one with a new picture. Everyone watching it is
    // holding the old one in a sidebar.
    await this.events.subscribe(EVENTS.SERVER_UPDATED, (envelope) => {
      const { serverId, name, iconUrl } = envelope.payload;
      this.broadcast(serverRoom(serverId), { type: 'server.updated', serverId, name, iconUrl });
    });

    // A changed profile has to reach everyone who draws it, which is a wider
    // set than any one room: the members of every server this account is in,
    // everyone it is friends with, and its own other devices.
    await this.events.subscribe(EVENTS.USER_UPDATED, (envelope) => {
      void this.broadcastProfile(envelope.payload.user);
    });

    this.logger.info('Chat WebSocket gateway ready', { path: '/ws/chat' });
  }

  private async handleClientEvent(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (!state) return;

    let event: ClientChatEvent;
    try {
      event = JSON.parse(raw) as ClientChatEvent;
    } catch {
      this.send(socket, { type: 'error', code: 'BAD_PAYLOAD', message: 'Malformed JSON' });
      return;
    }

    switch (event.type) {
      case 'ping':
        this.send(socket, { type: 'pong' });
        return;

      case 'channel.subscribe':
        try {
          // Re-check on every subscribe: permissions can change mid-session.
          await this.messages.requireChannelAccess(
            state.userId,
            event.channelId,
            PERMISSIONS.VIEW_CHANNEL,
          );
        } catch {
          this.send(socket, {
            type: 'error',
            code: 'CHANNEL_FORBIDDEN',
            message: 'Cannot subscribe to this channel',
          });
          return;
        }
        this.rooms.join(channelRoom(event.channelId), socket);
        return;

      case 'channel.unsubscribe':
        this.rooms.leave(channelRoom(event.channelId), socket);
        return;

      case 'server.subscribe': {
        // Membership, not permission: anyone in the server may know when its
        // member list changes, which is what the client re-reads.
        const membership = await prisma.serverMember.findUnique({
          where: { serverId_userId: { serverId: event.serverId, userId: state.userId } },
          select: { id: true },
        });
        if (!membership) {
          this.send(socket, {
            type: 'error',
            code: 'SERVER_FORBIDDEN',
            message: 'Cannot subscribe to this server',
          });
          return;
        }
        this.rooms.join(serverRoom(event.serverId), socket);
        return;
      }

      case 'server.unsubscribe':
        this.rooms.leave(serverRoom(event.serverId), socket);
        return;

      default:
        this.send(socket, { type: 'error', code: 'UNKNOWN_EVENT', message: 'Unsupported event' });
    }
  }

  /**
   * Who can see a profile: every server they share, plus every friendship.
   *
   * Friendships rather than DM channels because a direct message already
   * requires an accepted friendship - so the friend list is the same set, and
   * it is one query rather than two.
   */
  private async broadcastProfile(user: UserSummary): Promise<void> {
    const [memberships, friendships] = await Promise.all([
      prisma.serverMember.findMany({ where: { userId: user.id }, select: { serverId: true } }),
      prisma.friendship.findMany({
        where: { status: 'ACCEPTED', OR: [{ userAId: user.id }, { userBId: user.id }] },
        select: { userAId: true, userBId: true },
      }),
    ]);

    const rooms = [
      userRoom(user.id),
      ...memberships.map((row) => serverRoom(row.serverId)),
      ...friendships.map((row) => userRoom(row.userAId === user.id ? row.userBId : row.userAId)),
    ];
    this.deliver(rooms, { type: 'user.updated', user });
  }

  private broadcast(room: string, event: ServerChatEvent): void {
    for (const socket of this.rooms.members(room)) this.send(socket, event);
  }

  /** Several rooms, one delivery each - a socket in two of them is told once. */
  private deliver(rooms: string[], event: ServerChatEvent): void {
    const seen = new Set<WebSocket>();
    for (const room of rooms) {
      for (const socket of this.rooms.members(room)) seen.add(socket);
    }
    for (const socket of seen) this.send(socket, event);
  }

  private send(socket: WebSocket, event: ServerChatEvent): void {
    if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
  }

  onModuleDestroy(): void {
    if (this.heartbeat) clearInterval(this.heartbeat);
    this.server?.close();
  }
}

/**
 * `/ws/call`: the switchboard two clients use to find each other.
 *
 * This gateway introduces peers and then gets out of the way. It knows who is
 * in which channel's call, it forwards an offer, an answer or an ICE candidate
 * from one peer to another, and that is the whole of it. It never sees a frame
 * of media, cannot decode one, and is not in the path where one travels - the
 * peer connections it helps set up run directly between the two machines.
 *
 * That is also why this works through a Cloudflare Tunnel when an SFU did not.
 * Everything crossing this gateway is small, text and reliable, which is what a
 * tunnel carries; the large, continuous, loss-tolerant half never goes near it.
 *
 * Two things it deliberately does not do:
 *
 * - It does not read a signal. `data` is forwarded verbatim, so the SDP a peer
 *   receives is the SDP the other peer wrote. Anything else would put this
 *   service in a position to rewrite a DTLS fingerprint, which is exactly what
 *   the fingerprint signature exists to make useless.
 * - It does not trust `from`. The sender's peer id comes from the socket the
 *   message arrived on, never from the message, so a client cannot sign its
 *   traffic as somebody else.
 */
import { Injectable, OnModuleDestroy } from '@nestjs/common';
import { randomUUID } from 'node:crypto';
import type { Server as HttpServer } from 'node:http';
import { WebSocket, WebSocketServer } from 'ws';
import { resolveChannelAccess } from '@betweenus/database';
import { EVENTS, EventBus } from '@betweenus/events';
import { Logger } from '@betweenus/logger';
import { PERMISSIONS } from '@betweenus/permissions';
import {
  SIGNAL_MAX_PAYLOAD,
  authenticateHandshake,
  dropRevokedSockets,
} from '@betweenus/websocket';
import type {
  CallPeer,
  ClientCallEvent,
  GameSession,
  ListenSession,
  ServerCallEvent,
} from '@betweenus/shared-types';
import { apply as applyGame, type GameAction } from './game-session';
import { apply as applyListen, type ListenAction } from './listen-session';
import { otherDevicesInCall } from './devices';
import { deviceOf, peerIdFor } from './peer-identity';
import { CallsService, type ReportedUsage } from './modules/calls/calls.service';

const HEARTBEAT_INTERVAL_MS = 30_000;

/**
 * How long a peer's seat is held after its socket closes, before the others are
 * told it has gone.
 *
 * A phone loses its signalling socket constantly - a lift, a train, a screen
 * that went off, a doze the system decided on - and it comes back within a
 * second or two. Announcing `peer.left` the instant the socket drops made every
 * one of those a full mesh teardown: everybody closed their peer connection to
 * it, it rejoined, and everybody built a new one and renegotiated from nothing.
 * That is the call that connects, drops and connects again in a loop, and none
 * of it was ever about the media path.
 *
 * Inside this window a peer that comes back with the same id is not announced
 * as leaving or as arriving. Nobody's connection is touched, and ICE - which
 * has its own restart and its own deadline in every client - is left to do the
 * one job that is actually its own: find the media a path again.
 *
 * Shorter than the heartbeat, so a seat cannot outlive the roster that would
 * have corrected it, and much shorter than any client's signalling deadline.
 */
const REJOIN_GRACE_MS = 15_000;

/**
 * The ceiling the mesh imposes, enforced where it can be said clearly rather
 * than discovered as a call that degrades for everyone at once. Each
 * participant uploads one copy of its media per other participant, so the cost
 * of the tenth joiner is paid by the nine already talking.
 *
 * ponytail: a flat number for every channel. Per-channel limits are the fix if
 * a deployment ever wants voice-only rooms to go higher than video ones.
 */
const MAX_PEERS_PER_CALL = 8;

/**
 * How many numbers a move may carry beyond its index. A carrom shot needs
 * three; nothing needs more, and an array a client chose the length of is an
 * array a client chose the length of.
 */
const MAX_MOVE_PARAMS = 4;

/**
 * The numbers that complete a move, trimmed to something the rules can be
 * handed safely.
 *
 * This is the one field a client fills in with real numbers rather than an
 * index, and it goes straight into a physics simulation - so a NaN, an infinity
 * or an array of ten thousand entries would each be a shot that never comes to
 * rest, in a loop this process is running. Anything unusable becomes
 * `undefined`, which every rules module reads as "no aim given" and refuses.
 */
function sanitiseParams(params: unknown): number[] | undefined {
  if (!Array.isArray(params)) return undefined;
  if (params.length === 0 || params.length > MAX_MOVE_PARAMS) return undefined;
  const numbers = params.filter(
    (value): value is number => typeof value === 'number' && Number.isFinite(value),
  );
  if (numbers.length !== params.length) return undefined;
  return numbers;
}

interface SocketState extends CallPeer {
  channelId: string | null;
  alive: boolean;
  /** `iat` of the token that opened this socket. See `dropRevokedSockets`. */
  issuedAt: number;
  /** The open row in this person's call log, while they are in a call. */
  sessionId: string | null;
  /** Everybody else who has been in the call since this socket joined it. */
  metUserIds: Set<string>;
  /** What the client says it moved, reported on the way out. See `leave`. */
  usage: ReportedUsage;
}

@Injectable()
export class CallGateway implements OnModuleDestroy {
  private server: WebSocketServer | null = null;
  private heartbeat: NodeJS.Timeout | null = null;
  private readonly state = new WeakMap<WebSocket, SocketState>();
  /**
   * channelId -> the sockets in that call.
   *
   * ponytail: in process, so this holds for a single call-service replica -
   * which is what the compose deployment runs. Two replicas would each see half
   * a call and peers would never be introduced across them. The upgrade path is
   * the one presence-service already uses: Redis Pub/Sub, with the roster in
   * Redis and signals published to a channel keyed by peer id.
   */
  private readonly calls = new Map<string, Set<WebSocket>>();

  /**
   * channelId -> the socket currently sharing its screen, if any.
   *
   * One share per call. Two of them is a stage with two pictures on it and no
   * way to say which one anybody means; every product that has tried it ended
   * up here. Held beside the roster rather than derived from the peer data
   * channels, because arbitration needs one answer and the mesh has no ordering
   * to produce one - the last claim wins, and "last" is only a thing the
   * gateway can decide.
   */
  private readonly sharing = new Map<string, WebSocket>();

  /**
   * channelId -> the Listen Together session in that call, if there is one.
   *
   * Beside the roster for the same reason `sharing` is: two people pressing
   * pause at the same moment need one answer, and a mesh has no ordering to
   * produce one. This gateway holds the sockets, so it is the only thing that
   * can say which press happened second.
   *
   * The music itself is nowhere near here. Each client plays the track from the
   * provider over its own connection; what crosses this gateway is a queue and
   * a position - signalling, exactly like an SDP, and for exactly the same
   * reason it works through a tunnel. Sharing a browser tab with the sound on
   * would have made it media, one upload per listener, re-encoded through a
   * codec meant for speech.
   */
  private readonly listening = new Map<string, ListenSession>();

  /**
   * channelId -> the game being played in that call, if there is one.
   *
   * Here for the third time and for the same reason as `sharing` and
   * `listening`: two people clicking the same square at the same moment need
   * one answer, and a mesh has no ordering to produce one. This gateway holds
   * the sockets, so it is the only thing that can say which click was second -
   * and it is also the referee, because a board a client could set is a board a
   * client could set to won.
   *
   * Nothing here is persisted. The game lives beside the roster and dies with
   * the call, which is what it is: three rounds of Connect Four while two
   * people waited for a build has no meaning tomorrow.
   */
  private readonly playing = new Map<string, GameSession>();

  /**
   * `channelId\u0000peerId` -> the "they have gone" nobody has been told yet.
   *
   * A closed socket takes its seat off the roster straight away - a ghost in
   * the peer list is somebody a new joiner tries to call and never reaches -
   * but the *announcement* waits out [REJOIN_GRACE_MS]. A peer that comes back
   * with the same id cancels it, and the rest of the call never learns anything
   * happened.
   */
  private readonly departing = new Map<string, NodeJS.Timeout>();

  constructor(
    private readonly logger: Logger,
    private readonly events: EventBus,
    /** Where a call's log entry is opened and closed - `this.calls` is the roster. */
    private readonly history: CallsService,
  ) {}

  /**
   * Says who is in a call, for anybody drawing it.
   *
   * The roster used to be whatever each client told presence-service it was
   * doing, which meant a client could put itself in a channel it had never
   * signalled into, and a client that crashed stayed in one until its presence
   * socket noticed. This gateway is the only thing that knows the truth - it
   * holds the sockets - so it is the thing that says it, on every change,
   * including the changes nobody announced.
   */
  private announceRoster(channelId: string): void {
    const userIds = [
      ...new Set(
        [...(this.calls.get(channelId) ?? [])].flatMap((member) => {
          const peer = this.state.get(member);
          return peer ? [peer.userId] : [];
        }),
      ),
    ];

    // One account with two windows is one person in the room, which is why this
    // is a set: the peer list is per socket and the roster is per person.
    void this.events
      .publish(EVENTS.CALL_ROSTER, { voice: { channelId, userIds } })
      .catch((error) => {
        this.logger.warn('Could not publish a call roster', {
          channelId,
          reason: String(error),
        });
      });
  }

  /**
   * Every socket this instance holds for one account.
   *
   * Scanned rather than looked up in a room: the four gateways keep different
   * bookkeeping and `clients` is the one thing all of them have. A revocation is
   * rare, and a scan of one instance's sockets is nothing.
   */
  private socketsOf(userId: string): WebSocket[] {
    return [...(this.server?.clients ?? [])].filter(
      (socket) => this.state.get(socket)?.userId === userId,
    );
  }

  attach(httpServer: HttpServer): void {
    // The socket this matters most for, and the reason the fix is a revocation
    // event and not a shorter socket lifetime: closing a call socket ends a
    // call, so it must happen when somebody says so and never on a timer.
    // `close` runs the same teardown a dropped connection does - the roster is
    // re-announced and the call log row is closed - so the other people in the
    // call see them leave rather than freeze.
    void dropRevokedSockets(
      this.events,
      (userId) => this.socketsOf(userId),
      (socket) => this.state.get(socket)?.issuedAt,
      (socket, code, reason) => socket.close(code, reason),
      (userId, count, reason) => this.logger.info('Sockets revoked', { userId, count, reason }),
    );

    this.server = new WebSocketServer({
      server: httpServer,
      path: '/ws/call',
      maxPayload: SIGNAL_MAX_PAYLOAD,
    });

    this.server.on('connection', (socket, request) => {
      const user = authenticateHandshake(request);
      if (!user) {
        socket.close(4401, 'Unauthorized');
        return;
      }

      // A peer id per device, not per socket and not per user. Two windows on
      // one account are still two peers - that is what stops the second one
      // disconnecting the first - but a reconnect from the same window is the
      // same peer, which is what stops a tunnel from rebuilding the mesh. See
      // `peerIdFor`.
      const state: SocketState = {
        peerId: peerIdFor(user.id, deviceOf(request.url)),
        userId: user.id,
        username: user.username,
        channelId: null,
        alive: true,
        issuedAt: user.issuedAt,
        sessionId: null,
        metUserIds: new Set<string>(),
        usage: noUsage(),
      };
      this.state.set(socket, state);
      this.send(socket, { type: 'ready', peerId: state.peerId });

      socket.on('pong', () => {
        const current = this.state.get(socket);
        if (current) current.alive = true;
      });

      socket.on('message', (raw) => {
        void this.handle(socket, raw.toString());
      });

      // A socket that simply closed is a network, not a decision - and on a
      // phone it is a network that comes back in a second. The seat is held.
      socket.on('close', () => this.depart(socket, { hold: true }));

      socket.on('error', (error) => {
        this.logger.warn('Call socket error', { userId: user.id, reason: String(error) });
      });
    });

    this.heartbeat = setInterval(() => {
      for (const socket of this.server?.clients ?? []) {
        const state = this.state.get(socket);
        if (!state) continue;
        if (!state.alive) {
          // Terminating fires 'close', which is what takes them off the roster
          // and tells the others to tear their peer connection down.
          socket.terminate();
          continue;
        }
        state.alive = false;
        socket.ping();
      }

      // Said again, unchanged, on every beat.
      //
      // A roster is a replacement for one channel, so a channel that stops
      // being mentioned keeps whatever was last said about it - and if this
      // process restarted mid-call, what was last said about it was true of a
      // process that no longer exists. That is the ghost in a voice channel's
      // member list: somebody who left hours ago, listed forever, because the
      // only thing that could correct it never spoke about that channel again.
      //
      // Re-announcing turns the roster into something with a heartbeat, which
      // is what presence-service ages out. Nobody in this call means nothing is
      // published for it, which is exactly what "empty" has to look like.
      for (const channelId of this.calls.keys()) this.announceRoster(channelId);
    }, HEARTBEAT_INTERVAL_MS);

    this.logger.info('Call signalling gateway ready', { path: '/ws/call' });
  }

  private async handle(socket: WebSocket, raw: string): Promise<void> {
    const state = this.state.get(socket);
    if (!state) return;

    let event: ClientCallEvent;
    try {
      event = JSON.parse(raw) as ClientCallEvent;
    } catch {
      this.send(socket, { type: 'error', code: 'BAD_PAYLOAD', message: 'Malformed JSON' });
      return;
    }

    switch (event.type) {
      case 'join':
        await this.join(socket, state, event.channelId);
        return;

      case 'leave':
        // The only number in the log the server cannot take for itself: media
        // is peer to peer, so the client's own counters are the only counters.
        // It is clamped where it is written - see `usage.ts`.
        state.usage = {
          bytes: typeof event.bytes === 'number' ? event.bytes : 0,
          bytesSent: typeof event.bytesSent === 'number' ? event.bytesSent : 0,
          bytesReceived: typeof event.bytesReceived === 'number' ? event.bytesReceived : 0,
          links: event.links,
        };
        // Somebody pressed the button. No grace: they are not coming back, and
        // holding their seat is fifteen seconds of a frozen tile for everybody.
        this.depart(socket);
        return;

      case 'signal':
        this.relay(state, event.to, event.data);
        return;

      case 'screen.claim':
        this.claimScreen(socket, state);
        return;

      case 'screen.release':
        this.releaseScreen(socket, state);
        return;

      case 'ping':
        // The gateway's clock rides along, because a shared position is
        // meaningless without one: two machines disagree about what time it is
        // by whatever their clocks last drifted to, and this is the reference
        // every client measures its own offset against.
        this.send(socket, { type: 'pong', serverMs: Date.now() });
        return;

      case 'listen.add':
        this.listen(state, {
          kind: 'add',
          playNow: event.playNow === true,
          track: {
            // Minted here, not by the client: it is the identity two clients
            // agree a queue entry has, and a client that chose its own could
            // collide with one already in the queue - which is a `remove` that
            // takes away somebody else's track.
            id: randomUUID(),
            provider: event.provider,
            ref: event.ref,
            title: typeof event.title === 'string' ? event.title : '',
            durationMs: 0,
            addedByUserId: state.userId,
            addedByUsername: state.username,
          },
        });
        return;

      case 'listen.remove':
        this.listen(state, { kind: 'remove', trackId: event.trackId });
        return;

      case 'listen.play':
        this.listen(state, { kind: 'play', index: event.index });
        return;

      case 'listen.pause':
        this.listen(state, { kind: 'pause', positionMs: event.positionMs });
        return;

      case 'listen.seek':
        this.listen(state, { kind: 'seek', positionMs: event.positionMs });
        return;

      case 'listen.skip':
        this.listen(state, { kind: 'skip', delta: event.delta });
        return;

      case 'listen.stop':
        this.listen(state, { kind: 'stop' });
        return;

      case 'listen.ended':
        this.listen(state, { kind: 'ended', trackId: event.trackId });
        return;

      case 'listen.meta':
        this.listen(state, {
          kind: 'meta',
          trackId: event.trackId,
          title: event.title,
          durationMs: event.durationMs,
        });
        return;

      case 'game.open':
        this.game(state, { kind: 'open', gameId: event.gameId });
        return;

      case 'game.sit':
        this.game(state, { kind: 'sit', seat: event.seat });
        return;

      case 'game.move':
        this.game(state, {
          kind: 'move',
          move: event.move,
          // Bounded and cleaned here rather than trusted: this is the one field
          // a client fills in with real numbers, and it goes straight into a
          // physics simulation. A NaN, an array of ten thousand, or an infinity
          // would each be a shot that never comes to rest.
          params: sanitiseParams(event.params),
        });
        return;

      case 'game.rematch':
        this.game(state, { kind: 'rematch' });
        return;

      case 'game.close':
        this.game(state, { kind: 'close' });
        return;

      default:
        this.send(socket, { type: 'error', code: 'UNKNOWN_EVENT', message: 'Unsupported event' });
    }
  }

  private holdKey(channelId: string, peerId: string): string {
    return `${channelId}\u0000${peerId}`;
  }

  /**
   * Whether this join is the same peer coming back inside its grace window.
   *
   * True means the others still hold a live peer connection to it and must not
   * be told about any of this: no `peer.left` (cancelled here) and no
   * `peer.joined` (suppressed by the caller).
   */
  private resumeHeldSeat(channelId: string, peerId: string): boolean {
    const key = this.holdKey(channelId, peerId);
    const timer = this.departing.get(key);
    if (!timer) return false;
    clearTimeout(timer);
    this.departing.delete(key);
    return true;
  }

  private async join(socket: WebSocket, state: SocketState, channelId: string): Promise<void> {
    const access = await resolveChannelAccess(state.userId, channelId);
    if (!access) {
      // 404-shaped, for the same reason the REST path is: a non-member must not
      // learn the channel exists.
      this.send(socket, { type: 'error', code: 'CHANNEL_NOT_FOUND', message: 'Channel not found' });
      return;
    }
    if (!access.permissions.includes(PERMISSIONS.START_CALL)) {
      this.send(socket, {
        type: 'error',
        code: 'MISSING_PERMISSION',
        message: `Missing permission ${PERMISSIONS.START_CALL}`,
      });
      return;
    }

    // One call per socket. Leaving the old one first keeps a roster honest when
    // a client switches channels without saying goodbye to the first.
    if (state.channelId && state.channelId !== channelId) this.depart(socket, { keepOpen: true });

    // One call per *account*, across every device it is signed in on. A peer id
    // is still per socket - two windows are still two ends of two connections -
    // but only one of them may be in a call at a time, so joining on the laptop
    // takes the call off the desktop rather than putting the same person in the
    // room twice, talking over themselves through two microphones.
    //
    // The old device is told why before it is dropped: `superseded` is what
    // lets it say "this call moved" instead of "the connection was lost". Its
    // socket stays open, so it can join again - which is what moving the call
    // back looks like from the other end.
    const otherDevices = otherDevicesInCall(
      this.calls.values(),
      (member) => this.state.get(member)?.userId,
      state.userId,
      socket,
    );
    for (const other of otherDevices) {
      // The same peer id is this device reconnecting, not another one: an old
      // socket the far end has not finished closing while its replacement is
      // already joining. It is not superseded, it is replaced - so it goes
      // quietly, holding its seat for the join happening two lines below. Told
      // otherwise, a phone with a slow-closing socket would announce its own
      // departure and arrival on every reconnect, which is the rebuild this
      // whole change exists to stop.
      const replaced = this.state.get(other)?.peerId === state.peerId;
      if (replaced) {
        this.depart(other, { keepOpen: true, hold: true });
        continue;
      }
      this.send(other, { type: 'superseded', channelId });
      this.depart(other, { keepOpen: true });
      this.logger.info('Call moved to another device', { userId: state.userId, channelId });
    }

    const members = this.calls.get(channelId) ?? new Set<WebSocket>();
    if (!members.has(socket) && members.size >= MAX_PEERS_PER_CALL) {
      this.send(socket, {
        type: 'error',
        code: 'CALL_FULL',
        message:
          `This call already has ${MAX_PEERS_PER_CALL} people in it. Media goes directly between ` +
          'participants, so every extra person costs everyone already talking another upload.',
      });
      return;
    }

    // The roster is taken before this socket is added, so a joiner is not told
    // about itself and does not try to connect to its own peer id.
    const peers: CallPeer[] = [...members].flatMap((member) => {
      const peer = this.state.get(member);
      return peer ? [{ peerId: peer.peerId, userId: peer.userId, username: peer.username }] : [];
    });

    // Who they are in the call with, recorded both ways: this join meets
    // everybody already here, and everybody already here has now met them. A
    // log entry is "who was in it while I was", so somebody who leaves before
    // the end still belongs in it.
    for (const member of members) {
      const peer = this.state.get(member);
      if (!peer || peer.userId === state.userId) continue;
      state.metUserIds.add(peer.userId);
      peer.metUserIds.add(state.userId);
    }

    // Before the seat is taken back, because taking it back is what decides
    // whether anybody else is told about it.
    const resumed = this.resumeHeldSeat(channelId, state.peerId);

    members.add(socket);
    this.calls.set(channelId, members);
    state.channelId = channelId;

    this.send(socket, { type: 'joined', channelId, peers });
    // A peer coming back inside its grace window never left as far as anybody
    // else is concerned. Announcing it would be an arrival for a connection
    // every one of them already holds - and the tear-down and rebuild that
    // follows is the whole of a call that connects and drops in a loop.
    if (!resumed) {
      this.broadcast(
        channelId,
        {
          type: 'peer.joined',
          peer: { peerId: state.peerId, userId: state.userId, username: state.username },
        },
        socket,
      );
    }

    this.announceRoster(channelId);

    // Whatever is already playing, to the newcomer only. They get the position
    // and the instant it was true, so their player opens partway through the
    // track everybody else is partway through rather than at the beginning.
    const listening = this.listening.get(channelId);
    if (listening) this.send(socket, { type: 'listen.state', session: listening });

    // And whatever is on the table, to the newcomer only. They arrive at the
    // board as it stands rather than at an empty one, which is the difference
    // between joining a game and being told there is one.
    const playing = this.playing.get(channelId);
    if (playing) this.send(socket, { type: 'game.state', session: playing });

    // The log row is opened here because here is where the join is known to
    // have been allowed. If they left while this was being written - a socket
    // that closes mid-await - it is closed straight away rather than left open
    // forever, which is what an unattended `endedAt` of null means.
    state.sessionId = await this.history.startSession(state.userId, channelId);
    if (state.sessionId && state.channelId !== channelId) {
      void this.history.endSession(state.sessionId, [...state.metUserIds], state.usage);
      state.sessionId = null;
    }

    this.logger.info('Peer joined a call', {
      userId: state.userId,
      channelId,
      peers: members.size,
    });
  }

  /**
   * Hands the screen to whoever asked for it last.
   *
   * The previous holder is told the same thing everybody else is - who holds it
   * now - and stops on its own. It is not sent a private "stop": every client
   * needs the new holder anyway, and one message that says the whole truth
   * cannot be applied by half the room and missed by the rest.
   */
  private claimScreen(socket: WebSocket, state: SocketState): void {
    const channelId = state.channelId;
    if (!channelId) return;
    if (this.sharing.get(channelId) === socket) return;

    this.sharing.set(channelId, socket);
    this.announceScreen(channelId);
    this.logger.info('Screen share taken over', { userId: state.userId, channelId });
  }

  /** Gives it up, if this socket is the one holding it. */
  private releaseScreen(socket: WebSocket, state: SocketState): void {
    const channelId = state.channelId;
    if (!channelId) return;
    // Only the holder may release: a late "I stopped" from whoever was replaced
    // would otherwise take the screen away from the person who just took it.
    if (this.sharing.get(channelId) !== socket) return;

    this.sharing.delete(channelId);
    this.announceScreen(channelId);
  }

  /**
   * Runs one Listen Together action and tells the call what came of it.
   *
   * Membership is the only permission asked for, and deliberately: everybody in
   * the call can change what is playing. A host is a person who eventually
   * leaves and takes the music with them, and the point of listening together
   * is that two people are doing it, not that one is performing it.
   *
   * The whole session is broadcast rather than a delta. It is a few hundred
   * bytes, it changes when somebody presses a button rather than continuously,
   * and a client that missed one message would otherwise hold a queue nobody
   * else has - which is the failure that cannot be noticed from inside.
   */
  private listen(state: SocketState, action: ListenAction): void {
    const channelId = state.channelId;
    if (!channelId) return;

    const before = this.listening.get(channelId) ?? null;
    const after = applyListen(before, action, state.userId, Date.now());
    // Nothing happened: a `duration` for a track that already had one, or an
    // `ended` for a track that stopped being current before it arrived. Saying
    // so anyway would make every client re-seek for no reason.
    if (after === before) return;

    if (after) this.listening.set(channelId, after);
    else this.listening.delete(channelId);

    this.broadcast(channelId, { type: 'listen.state', session: after });
  }

  /**
   * Runs one Play Together action and tells the call what came of it.
   *
   * The gateway is the referee, and this is the only place a board is ever
   * made: a client sends "column four", never a board. The rules come from
   * `@betweenus/shared-types`, which is also where the clients read them, so
   * what everybody draws and what is agreed here cannot drift apart.
   *
   * Membership is the only permission asked for. Who may *move* is a question
   * about the seats rather than about the channel, and the reducer answers it.
   */
  private game(state: SocketState, action: GameAction): void {
    if (!state.channelId) return;
    this.runGame(state.channelId, { userId: state.userId, username: state.username }, action);
  }

  /**
   * The same thing, addressed by channel rather than by socket.
   *
   * `depart` needs this: it clears `state.channelId` before it does anything
   * else, so by the time a leaver's chair has to be freed the socket no longer
   * knows which call it was in.
   */
  private runGame(
    channelId: string,
    actor: { userId: string; username: string },
    action: GameAction,
  ): void {
    const before = this.playing.get(channelId) ?? null;
    const after = applyGame(before, action, actor);
    // Nothing happened: an illegal move, a chair that filled while the click
    // was in flight, a rematch from somebody watching. Broadcasting anyway
    // would make every client redraw a board it already has.
    if (after === before) return;

    if (after) this.playing.set(channelId, after);
    else this.playing.delete(channelId);

    this.broadcast(channelId, { type: 'game.state', session: after });
  }

  private announceScreen(channelId: string): void {
    const holder = this.sharing.get(channelId);
    const peer = holder ? this.state.get(holder) : undefined;
    this.broadcast(channelId, {
      type: 'screen.holder',
      peerId: peer?.peerId ?? null,
      userId: peer?.userId ?? null,
    });
  }

  /**
   * Forwards one signal to one peer in the same call.
   *
   * Same-call is the check that matters: without it, a peer id learned anywhere
   * would let a client offer a connection into a channel it cannot see.
   */
  private relay(from: SocketState, to: string, data: unknown): void {
    if (!from.channelId) return;

    for (const member of this.calls.get(from.channelId) ?? []) {
      const peer = this.state.get(member);
      if (peer?.peerId !== to) continue;
      this.send(member, {
        type: 'signal',
        from: from.peerId,
        data: data as never,
      });
      return;
    }
  }

  /**
   * Takes a socket off its call and tells the others.
   *
   * `keepOpen` is the channel-switch case: the socket lives on, so its state is
   * kept and only its membership is dropped.
   */
  private depart(socket: WebSocket, options: DepartOptions = {}): void {
    const { keepOpen = false, hold = false } = options;
    const state = this.state.get(socket);
    if (!state) return;

    const { channelId, sessionId } = state;
    state.channelId = null;

    // Closed before anything else can throw, and before the state is dropped:
    // this is the only moment the duration is knowable, and a row left open is
    // an entry that reads as a call that never ended.
    if (sessionId) {
      state.sessionId = null;
      void this.history.endSession(sessionId, [...state.metUserIds], state.usage);
    }
    // A socket that stays open to join elsewhere starts a fresh log entry, so
    // it starts with a fresh idea of who it has met and what it has moved.
    state.metUserIds = new Set<string>();
    state.usage = noUsage();

    if (!keepOpen) this.state.delete(socket);
    if (!channelId) return;

    const members = this.calls.get(channelId);
    if (!members) return;
    members.delete(socket);
    if (members.size === 0) {
      this.calls.delete(channelId);
      // Nobody is listening, so there is nothing to listen to. The queue was a
      // thing this call built and it goes when the call does - keeping it would
      // mean the next person to join a quiet channel is played whatever the
      // last people left half-finished.
      this.listening.delete(channelId);
      // Same for the board: nobody is at the table, so there is no game. A kept
      // one would be a half-finished Reversi position waiting for whoever walks
      // into a quiet channel next.
      this.playing.delete(channelId);
    }

    // Somebody who left is not still sharing. Without this the screen stays
    // claimed by a socket that has gone, and the next person to press the
    // button is the only one who ever finds out.
    if (this.sharing.get(channelId) === socket) {
      this.sharing.delete(channelId);
      this.announceScreen(channelId);
    }

    // Everyone still in the call has a peer connection to this peer that will
    // never produce another frame. Saying so is what closes it; waiting for ICE
    // to time out is thirty seconds of a frozen tile.
    //
    // Unless nobody has said they are leaving. A socket that simply closed is a
    // network, not a decision, and on a phone it is a network that comes back
    // in a second - so the seat is held and the announcement waits. See
    // REJOIN_GRACE_MS.
    //
    // The chair at the game table is held on exactly the same terms, and it
    // has to be: freeing it the instant a socket blinks would let somebody else
    // sit down mid-game while the player it belongs to is still reconnecting.
    const actor = { userId: state.userId, username: state.username };
    if (!hold) {
      this.announceDeparture(channelId, state.peerId);
      this.runGame(channelId, actor, { kind: 'vacate', userId: state.userId });
    } else {
      const key = this.holdKey(channelId, state.peerId);
      const held = state.peerId;
      clearTimeout(this.departing.get(key));
      this.departing.set(
        key,
        setTimeout(() => {
          this.departing.delete(key);
          this.announceDeparture(channelId, held);
          this.runGame(channelId, actor, { kind: 'vacate', userId: actor.userId });
        }, REJOIN_GRACE_MS),
      );
    }

    this.logger.info('Peer left a call', {
      userId: state.userId,
      channelId,
      peers: members.size,
      held: hold,
    });
  }

  /** They are not coming back: tell the call, and correct the roster. */
  private announceDeparture(channelId: string, peerId: string): void {
    this.broadcast(channelId, { type: 'peer.left', peerId });
    this.announceRoster(channelId);
  }

  private broadcast(channelId: string, event: ServerCallEvent, except?: WebSocket): void {
    for (const member of this.calls.get(channelId) ?? []) {
      if (member === except) continue;
      this.send(member, event);
    }
  }

  private send(socket: WebSocket, event: ServerCallEvent): void {
    if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify(event));
  }

  onModuleDestroy(): void {
    if (this.heartbeat) clearInterval(this.heartbeat);
    for (const timer of this.departing.values()) clearTimeout(timer);
    this.departing.clear();
    this.server?.close();
  }
}

/**
 * How a socket is being taken off a call.
 *
 * `keepOpen` says the socket lives on - a channel switch, or a device being
 * replaced - so its state is kept and only its membership dropped. `hold` says
 * nobody has announced anything: the seat is kept for [REJOIN_GRACE_MS] and the
 * rest of the call is told only if it is not claimed back.
 */
interface DepartOptions {
  keepOpen?: boolean;
  hold?: boolean;
}

/** A stay nobody reported on: a window closed mid-call, or an older client. */
function noUsage(): ReportedUsage {
  return { bytes: 0, bytesSent: 0, bytesReceived: 0, links: [] };
}

package com.aatech.betweenus.core.crypto

import android.content.Context
import com.aatech.betweenus.core.data.ApiError
import com.aatech.betweenus.core.data.ChannelKeyEntry
import com.aatech.betweenus.core.data.ChannelKeys
import com.aatech.betweenus.core.data.DeviceKey
import com.aatech.betweenus.core.data.IdentityBackup
import com.aatech.betweenus.core.data.StatusEntry
import com.aatech.betweenus.core.data.StatusKeyEntry
import com.aatech.betweenus.core.data.BetweenUsApi
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import org.json.JSONObject
import java.util.concurrent.ConcurrentHashMap

/** What opens an identity backup. Held only for the moment a sign-in needs it. */
data class BackupSecret(val value: String, val kind: String) {
    companion object {
        fun password(value: String) = BackupSecret(value, "password")
        fun passphrase(value: String) = BackupSecret(value, "passphrase")
    }
}

class MissingChannelKeyError : Exception("No channel key on this device yet")

/**
 * There is no `Locked`. A device that cannot open the account backup mints a
 * key of its own and signs in anyway - see [E2ee.initIdentity] - so there is no
 * state in which the app is signed in and waiting to be told a secret. That
 * fork used to be permanent; it is provisional now, and every later sign-in
 * with a secret that opens the backup undoes it.
 */
sealed interface IdentityStatus {
    data object Absent : IdentityStatus

    /**
     * `backedUp` is whether *this device's* key is the one in the backup.
     *
     * `provisional` is this device having minted its own because it could not
     * open the account's - so it reads what arrives from now on, and history is
     * still sealed to an identity it does not hold.
     */
    data class Ready(val backedUp: Boolean, val provisional: Boolean = false) : IdentityStatus

    /**
     * The owner revoked this machine from another one. Nothing new is wrapped
     * for it, so it reads what it already had and nothing since - saying so
     * beats a screen full of "no key on this device yet".
     */
    data object Revoked : IdentityStatus
}

/**
 * The end-to-end encryption service: this device's identity, the channel keys
 * it can open, and sealing and opening content with them.
 *
 * The port of `apps/desktop/src/services/e2ee.ts`. Every decision here about
 * *when* to mint an epoch, when to re-wrap for a member, and what to do when a
 * key cannot be opened is that file's, because the three clients share one
 * channel and disagreeing about any of it locks somebody out of their history.
 */
object E2ee {
    /**
     * Shown instead of a message this device holds no key for.
     *
     * Two words: it is drawn once per message, and a sentence repeated down a
     * whole screen is not eight times as informative as one. Why, and what to
     * do about it, is said once for the channel.
     */
    const val UNDECRYPTABLE = "🔒 Encrypted"

    private lateinit var store: SecureStore

    private var identity: Crypto.KeyPairJwk? = null
    private var userId: String? = null

    /**
     * The secret this session signed in with, kept for the length of the session.
     *
     * It used to be an argument and nothing else, so a sign-in whose identity
     * setup failed once - the network dropped, the token was a moment late -
     * lost it. [currentIdentity] then retried with no secret, could not open the
     * account backup, and minted a device-local key instead, which was
     * permanent. A password typed into a login form is dropped when the session
     * ends, and that is the only thing keeping it here has to guarantee.
     */
    @Volatile
    private var signInSecret: BackupSecret? = null

    private val identityLock = Mutex()
    private val channelLocks = ConcurrentHashMap<String, Mutex>()

    /** Every epoch this device can open, per channel, so old history stays readable. */
    private class ChannelKeyState(val epoch: Int, val keys: Map<Int, String>)

    private val channels = ConcurrentHashMap<String, ChannelKeyState>()

    /**
     * Channels this session has already tried to re-key for itself. Without it,
     * a device that cannot open its own wrapped keys would mint a fresh epoch
     * every time the channel is opened and drag the whole channel along with it.
     */
    private val rekeyed = ConcurrentHashMap.newKeySet<String>()

    /**
     * Epochs this client has already gone back to the directory for and still
     * not found. Without it, a channel holding one genuinely unreadable message
     * would re-read the key directory every time that message is drawn.
     */
    private val missedEpochs = ConcurrentHashMap.newKeySet<String>()

    private val _status = MutableStateFlow<IdentityStatus>(IdentityStatus.Absent)
    val status: StateFlow<IdentityStatus> = _status.asStateFlow()

    fun init(context: Context) {
        store = SecureStore(context)
    }

    // --- identity ---

    /**
     * Loads this device's identity key and publishes the public half. Called
     * once per sign-in, with the password when there is one to hand.
     *
     * It never fails for want of a secret, and it never asks for one.
     */
    suspend fun initIdentity(userId: String, secret: BackupSecret? = null): Crypto.KeyPairJwk =
        identityLock.withLock {
            identity?.let { if (this.userId == userId) return@withLock it }
            this.userId = userId
            // Held past this call on purpose: [currentIdentity] retries with no
            // secret of its own, and a retry without one forks permanently.
            if (secret != null) signInSecret = secret
            val opener = secret ?: signInSecret

            val storageKey = "identity:$userId"
            store.get(storageKey)?.let { stored ->
                val saved = runCatching { readStored(stored) }.getOrNull()
                if (saved != null) {
                    // A device that forked gets another go, every time a secret
                    // is at hand. This is the whole of "sign in on a new phone
                    // and your messages are there": the fork below is silent and
                    // one-way, so the only thing that makes it recoverable is
                    // trying the backup again on the next sign-in rather than
                    // short-circuiting on the key the fork left behind.
                    if (saved.provisional && opener != null) {
                        restoreFromBackup(storageKey, opener)?.let { return@withLock it }
                    }
                    adopt(saved.pair, provisional = saved.provisional)
                    // A device that already worked may still have no backup.
                    // Fix it quietly when a secret is at hand rather than
                    // waiting for the next reinstall to notice.
                    ensureBackup(saved.pair, opener)
                    return@withLock saved.pair
                }
            }

            // A failed fetch must not be read as "there is no backup": that
            // would seal a fresh key over one that exists. It throws, and the
            // sign-in retries.
            val backups = BetweenUsApi.identityBackups()

            // The account's own key, when the secret that opens it is at hand.
            // The good path and the only instant one: every epoch already
            // sealed for that identity opens the moment it lands.
            if (opener != null) {
                restoreFromBackup(storageKey, opener, backups)?.let { return@withLock it }
            }

            // Otherwise this device gets a key of its own and the sign-in
            // carries on. It used to stop and ask - and asking is not something
            // every sign-in can answer: a provider sign-in has no account
            // password to offer, and an account that has only ever used one has
            // no password at all.
            //
            // Minting is safe because a channel key is wrapped per *device*:
            // this device publishes its own public key under its own device id
            // and takes nothing from the devices already in the directory.
            // History arrives from them - `fillGaps` hands every epoch a device
            // holds to the owner's devices missing it - so the account
            // converges without anyone typing anything. What it costs is that
            // history is not instant; it appears as the other devices open
            // those channels. See apps/desktop/src/services/e2ee.ts.
            //
            // The fork is marked when the account *had* a backup this device
            // could not open, and that mark is what lets the next sign-in undo
            // it. Unmarked means there was nothing to restore from, so this key
            // is the account's own.
            val provisional = backups.isNotEmpty()
            val pair = Crypto.generateIdentity()
            store.put(storageKey, writePair(pair, provisional))
            adopt(pair, provisional = provisional)
            ensureBackup(pair, opener)
            pair
        }

    /**
     * Opens whichever backup [secret] fits and makes it this device's identity.
     *
     * Null means "not this secret" - a wrong password, or a passphrase-only
     * account signing in with a password - which is an ordinary outcome here,
     * not a failure.
     *
     * Every channel key held on this device is dropped on the way out. They are
     * still valid, but they are the *subset* a forked identity could reach, and
     * the caches in front of them - memory and the sealed store both - would
     * keep serving that subset while the wraps this identity can now open sat
     * unread in the directory. Dropping them costs one re-read of a directory
     * we have just been talking to.
     */
    private suspend fun restoreFromBackup(
        storageKey: String,
        secret: BackupSecret,
        known: List<IdentityBackup>? = null,
    ): Crypto.KeyPairJwk? {
        val backups = known ?: runCatching { BetweenUsApi.identityBackups() }.getOrNull() ?: return null
        val sealed = backups.firstOrNull { it.kind == secret.kind } ?: return null
        val pair = openBackup(sealed, secret) ?: return null

        store.put(storageKey, writePair(pair))
        forgetAllKeys()
        adopt(pair, backedUp = true)
        return pair
    }

    /** Seals the current identity under a secret the user chose. */
    suspend fun backupIdentity(secret: BackupSecret) {
        val pair = currentIdentity()
        BetweenUsApi.putIdentityBackup(seal(pair, secret))
        _status.value = IdentityStatus.Ready(backedUp = true)
    }

    /**
     * Re-seals the backup after a password change. Skipped silently when the
     * backup is keyed to a passphrase, which a password change does not touch.
     */
    suspend fun rewrapBackupForPassword(newPassword: String) {
        if (BetweenUsApi.identityBackups().none { it.kind == "password" }) return
        backupIdentity(BackupSecret.password(newPassword))
        // The secret this session holds is now the old one, and a retry using it
        // would fail to open the blob it has just re-sealed.
        signInSecret = BackupSecret.password(newPassword)
    }

    /**
     * Whether the account password can still recover this identity on a device
     * that has never seen it.
     *
     * The one thing a settings screen has to be able to say plainly: it is the
     * difference between "sign in anywhere" and "sign in anywhere and type a
     * passphrase you wrote down once".
     */
    suspend fun passwordRecoveryEnabled(): Boolean =
        BetweenUsApi.identityBackups().any { it.kind == "password" }

    /**
     * Turns the password path off, for somebody who set a recovery passphrase
     * *because* a live server sees the password at sign-in and they would rather
     * it could never open the backup.
     *
     * Refuses when it would leave the account with no backup at all. That is not
     * a security setting, it is losing every message on the next reinstall.
     */
    suspend fun disablePasswordRecovery() {
        if (BetweenUsApi.identityBackups().none { it.kind == "passphrase" }) {
            error("Set a recovery passphrase first, or this account has no way back at all")
        }
        BetweenUsApi.deleteIdentityBackup("password")
    }

    fun reset() {
        // Key material is per-user; a sign-out must not leak it into the next
        // session. What is on disk stays - it is sealed, and the same account
        // signing back in should not have to fetch its backup again.
        identity = null
        userId = null
        signInSecret = null
        channels.clear()
        channelLocks.clear()
        rekeyed.clear()
        missedEpochs.clear()
        _status.value = IdentityStatus.Absent
    }

    private suspend fun adopt(
        pair: Crypto.KeyPairJwk,
        backedUp: Boolean = false,
        provisional: Boolean = false,
    ) {
        identity = pair
        try {
            // Idempotent: re-publishing keeps the directory correct if the row
            // was lost, and refreshes when this phone was last seen.
            BetweenUsApi.registerDeviceKey(DeviceIdentity.id(), pair.publicKey, DeviceIdentity.label())
        } catch (error: ApiError) {
            // Revoked from another machine. Not a thing to retry, and not a
            // reason to mint a new id - minting one is how a revoked phone
            // would walk straight back into the directory.
            if (error.code == "DEVICE_REVOKED") {
                _status.value = IdentityStatus.Revoked
            }
            throw error
        }
        _status.value = IdentityStatus.Ready(backedUp, provisional)
    }

    /**
     * Uploads a backup when the account has none for this identity and a secret
     * is available to seal it with. Never throws into a sign-in: an account
     * without a backup still works, it is only unrecoverable, and settings says so.
     */
    private suspend fun ensureBackup(pair: Crypto.KeyPairJwk, secret: BackupSecret?) {
        runCatching {
            val backups = BetweenUsApi.identityBackups()
            val backedUp = backups.any { it.publicKey == pair.publicKey }

            // A backup that already stands is not this device's to replace
            // unless it is this device's key in it. Since a device that could
            // not open one mints its own, sealing over it here would take the
            // account's recoverable identity away from every device still
            // restoring from it. Deliberate re-sealing is [backupIdentity]'s.
            //
            // Scoped to the *kind* now. An account holding a passphrase backup
            // and no password one is exactly the account that cannot recover on
            // a fresh sign-in, so filling that gap when the password is at hand
            // is the point rather than an overreach - and it only ever seals the
            // key this device already holds, which is the identity the other
            // devices restore from whenever `backedUp` says so.
            if (secret == null || backups.any { it.kind == secret.kind } || !backedUp) {
                _status.value = IdentityStatus.Ready(
                    backedUp = backedUp,
                    provisional = backups.isNotEmpty() && !backedUp,
                )
                return
            }
            BetweenUsApi.putIdentityBackup(seal(pair, secret))
            _status.value = IdentityStatus.Ready(backedUp = true)
        }
        // Offline, or a server older than this client. Nothing is lost that was
        // not already missing.
    }

    private fun seal(pair: Crypto.KeyPairJwk, secret: BackupSecret): IdentityBackup {
        val (salt, iv, ct) = Crypto.sealIdentity(pair, secret.value)
        return IdentityBackup(
            kind = secret.kind,
            iterations = Crypto.BACKUP_ITERATIONS,
            salt = salt,
            iv = iv,
            ct = ct,
            publicKey = pair.publicKey,
        )
    }

    /** The wrong secret is an ordinary outcome here, not an error: null, and on. */
    private fun openBackup(backup: IdentityBackup, secret: BackupSecret): Crypto.KeyPairJwk? =
        runCatching {
            Crypto.openIdentity(backup.salt, backup.iv, backup.ct, secret.value, backup.iterations)
        }.getOrNull()

    /**
     * What the sealed store holds. `provisional` marks a key this device minted
     * for itself *while the account had a backup it could not open* - the fork
     * described in [initIdentity]. It is the flag that makes the fork
     * recoverable: without it the stored key short-circuits every later launch
     * and the backup is never tried again, on any sign-in, ever.
     */
    private class StoredIdentity(val pair: Crypto.KeyPairJwk, val provisional: Boolean)

    private fun writePair(pair: Crypto.KeyPairJwk, provisional: Boolean = false) = JSONObject()
        .put("publicKey", pair.publicKey)
        .put("privateKey", pair.privateKey)
        .put("provisional", provisional)
        .toString()

    private fun readStored(stored: String): StoredIdentity {
        val json = JSONObject(stored)
        return StoredIdentity(
            pair = Crypto.KeyPairJwk(json.getString("publicKey"), json.getString("privateKey")),
            // Absent on a blob written before the fork was recoverable. False is
            // the safe reading: it was minted under rules that had no mark, and
            // a sign-in that opens the backup replaces it either way.
            provisional = json.optBoolean("provisional", false),
        )
    }

    private suspend fun currentIdentity(): Crypto.KeyPairJwk =
        identity
            // With the session's secret, not without it. A retry that dropped it
            // opened no backup, minted a device-local key, and forked for good.
            ?: userId?.let { initIdentity(it, signInSecret) }
            ?: throw MissingChannelKeyError()

    // --- content ---

    suspend fun encryptForChannel(channelId: String, plaintext: String): String {
        val state = ensureChannelKey(channelId)
        val key = state.keys[state.epoch] ?: throw MissingChannelKeyError()
        val sealed = Crypto.encrypt(plaintext, key)
        return JSONObject()
            .put("v", 1)
            .put("epoch", state.epoch)
            .put("iv", sealed.iv)
            .put("ct", Crypto.base64(sealed.ciphertext))
            .toString()
    }

    /**
     * Reads a stored message body. Anything that is not an envelope is returned
     * as it stands, so plaintext rows written before E2EE still render.
     */
    suspend fun decryptForChannel(channelId: String, content: String): String {
        val envelope = parseEnvelope(content) ?: return content
        val key = keyForEpoch(channelId, envelope.epoch) ?: return UNDECRYPTABLE
        return runCatching { Crypto.decrypt(envelope.ct, envelope.iv, key) }
            .getOrDefault(UNDECRYPTABLE)
    }

    suspend fun encryptFileForChannel(channelId: String, plaintext: ByteArray): Pair<Crypto.Sealed, Int> {
        val state = ensureChannelKey(channelId)
        val key = state.keys[state.epoch] ?: throw MissingChannelKeyError()
        return Crypto.encryptBytes(plaintext, key) to state.epoch
    }

    suspend fun decryptFileForChannel(
        channelId: String,
        ciphertext: ByteArray,
        iv: String,
        epoch: Int,
    ): ByteArray {
        val key = keyForEpoch(channelId, epoch) ?: throw MissingChannelKeyError()
        return Crypto.decryptBytes(ciphertext, iv, key)
    }

    /**
     * The key a call's DTLS fingerprint is signed with. It is the channel key,
     * which the server has never held - which is exactly why a signature made
     * with it proves the relay did not substitute a fingerprint of its own.
     */
    suspend fun callKeyForChannel(channelId: String, refresh: Boolean = false): String {
        // `refresh` is what a call asks for when somebody new arrives. Joining a
        // channel you hold no key for mints the next epoch - that is the only
        // way a new member gets one - so the newcomer's key is a generation
        // ahead of the one everybody already in the call read when they joined,
        // and without the re-read the two sides sign fingerprints with
        // different keys and refuse each other for good.
        if (refresh) forgetKeys(channelId)
        val state = ensureChannelKey(channelId)
        return state.keys[state.epoch] ?: throw MissingChannelKeyError()
    }


    // --- statuses ---
    //
    // A status has no channel, so it has no epoch and nothing to rotate: one
    // key per post, wrapped once per device that may read it, and gone in a
    // day. None of the channel machinery above applies - there is no state to
    // load, no gap to fill and no rekey.
    //
    // The wrap list is the audience, built from the directory at the moment of
    // posting. A friendship made afterwards adds nothing to a post already
    // written, which is why a new friend does not see yesterday's moment.

    /** A post, sealed and ready to send. */
    class SealedStatus(
        val caption: String?,
        val media: Crypto.Sealed?,
        val keys: List<StatusKeyEntry>,
        val senderDeviceId: String,
    )

    /**
     * Seals one post for one audience.
     *
     * This phone may not be in the directory yet - one that signed in a moment
     * ago has not been listed - so we always wrap for ourselves. Posting
     * something we cannot open is the one failure with no way back.
     */
    suspend fun sealStatus(
        caption: String?,
        media: ByteArray?,
        devices: List<DeviceKey>,
    ): SealedStatus {
        val self = currentIdentity()
        val key = Crypto.generateChannelKey()
        val mine = DeviceIdentity.id()
        val recipients = if (devices.any { it.userId == userId && it.deviceId == mine }) {
            devices
        } else {
            devices + DeviceKey(userId.orEmpty(), mine, self.publicKey)
        }

        val keys = recipients.mapNotNull { device ->
            runCatching {
                val wrapped = Crypto.wrapChannelKey(key, self.privateKey, device.publicKey)
                StatusKeyEntry(
                    recipientUserId = device.userId,
                    recipientDeviceId = device.deviceId,
                    senderPublicKey = self.publicKey,
                    wrappedKey = wrapped.wrappedKey,
                    iv = wrapped.iv,
                )
            }.getOrNull()
            // A directory row with a malformed public key must not stop the
            // post being sealed for everybody else.
        }

        // Epoch 0 in the envelope: a status has no generations, and the field
        // is there because the shape is shared with messages.
        val sealedCaption = caption?.takeIf { it.isNotBlank() }?.let {
            val sealed = Crypto.encrypt(it, key)
            JSONObject()
                .put("v", 1)
                .put("epoch", 0)
                .put("iv", sealed.iv)
                .put("ct", Crypto.base64(sealed.ciphertext))
                .toString()
        }
        return SealedStatus(
            caption = sealedCaption,
            media = media?.let { Crypto.encryptBytes(it, key) },
            keys = keys,
            senderDeviceId = mine,
        )
    }

    /**
     * The key to one post, from whichever wrap this phone's private half opens.
     *
     * Null rather than a throw for the ordinary cases: a post written before
     * this device existed, or before the friendship did, carries no wrap for
     * us. Both happen, and neither is an error.
     */
    suspend fun statusKey(post: StatusEntry): String? {
        if (post.keys.isEmpty()) return null
        val self = currentIdentity()
        for (wrap in post.keys) {
            val opened = runCatching {
                Crypto.unwrapChannelKey(
                    Crypto.Wrapped(wrap.wrappedKey, wrap.iv),
                    self.privateKey,
                    wrap.senderPublicKey,
                )
            }.getOrNull()
            if (opened != null) return opened
        }
        return null
    }

    /** A post's caption in the clear, or the placeholder. Never throws. */
    suspend fun openStatusCaption(post: StatusEntry): String? {
        val caption = post.caption ?: return null
        // Written before statuses were sealed. It expires within the day.
        val envelope = parseEnvelope(caption) ?: return caption
        val key = statusKey(post) ?: return UNDECRYPTABLE
        return runCatching { Crypto.decrypt(envelope.ct, envelope.iv, key) }
            .getOrDefault(UNDECRYPTABLE)
    }

    /** A post's media in the clear. Null when this device holds no key for it. */
    suspend fun openStatusMedia(post: StatusEntry, ciphertext: ByteArray): ByteArray? {
        // No IV means it was stored in the clear, before this. Hand it back.
        val iv = post.mediaIv ?: return ciphertext
        val key = statusKey(post) ?: return null
        return runCatching { Crypto.decryptBytes(ciphertext, iv, key) }.getOrNull()
    }

    private class Envelope(val epoch: Int, val iv: String, val ct: String)

    private fun parseEnvelope(content: String): Envelope? {
        if (!content.startsWith("{")) return null
        return runCatching {
            val json = JSONObject(content)
            if (json.optInt("v") != 1) return null
            val iv = json.optString("iv")
            val ct = json.optString("ct")
            if (iv.isEmpty() || ct.isEmpty() || !json.has("epoch")) return null
            Envelope(json.getInt("epoch"), iv, ct)
        }.getOrNull()
    }

    // --- channel keys ---

    /**
     * Re-wraps the current key for members who have none. Called when a channel
     * is opened, so somebody who joined after the key was minted becomes able to
     * read without anyone restarting the app.
     */
    suspend fun syncChannelKeys(channelId: String) {
        val state = runCatching { ensureChannelKey(channelId) }.getOrNull() ?: return
        val latest = BetweenUsApi.channelKeys(channelId)

        // Held state now survives a restart, so it can be days rather than
        // minutes behind. A different epoch means somebody re-keyed the channel
        // while this device was closed: ours is stale and theirs is the one
        // that counts. Without this the client would go on sealing under a dead
        // epoch until something else happened to invalidate it.
        if (latest.epoch != state.epoch) {
            forgetKeys(channelId)
            runCatching { ensureChannelKey(channelId) }
            return
        }

        fillGaps(channelId, state, latest)
    }

    /**
     * Hands every epoch this phone holds to the machines that are missing it.
     *
     * This is what lets a second machine read *history* rather than only what
     * is written after it arrives. Re-wrapping the current epoch and nothing
     * else left a machine that signed in today missing every epoch before
     * today - it holds none of them so it cannot repair itself, and with nobody
     * looking on its behalf it minted a fresh epoch and the whole conversation
     * before that moment stayed a padlock for good.
     *
     * The server only ever lists a machine whose *owner* already holds that
     * epoch, so this repairs one person's own second machine and hands nothing
     * to somebody who joined last week.
     *
     * Failures are per epoch and never fatal: a racing rotation or a device
     * revoked between the read and the write fails one wrap, and neither is a
     * reason to stop opening the channel.
     */
    private suspend fun fillGaps(channelId: String, state: ChannelKeyState, latest: ChannelKeys) {
        // Belt and braces for a server older than `gaps`, where this is the
        // only re-wrap that happens.
        state.keys[state.epoch]?.let { key ->
            if (latest.missingRecipients.isNotEmpty()) {
                runCatching { shareKey(channelId, state.epoch, key, latest.missingRecipients) }
            }
        }

        for (gap in latest.gaps) {
            // An epoch we cannot open is not ours to hand out, and the server
            // would refuse it anyway: only a holder may add to an existing one.
            val key = state.keys[gap.epoch] ?: continue
            if (gap.devices.isEmpty()) continue
            runCatching { shareKey(channelId, gap.epoch, key, gap.devices) }
        }
    }

    /** Keys a channel that was just created, so whoever opens it first can read. */
    suspend fun keyChannel(channelId: String) {
        runCatching { ensureChannelKey(channelId) }
    }

    private suspend fun keyForEpoch(channelId: String, epoch: Int): String? {
        channels[channelId]?.keys?.get(epoch)?.let { return it }
        runCatching { ensureChannelKey(channelId) }.getOrNull()?.keys?.get(epoch)?.let { return it }

        // An epoch we hold nothing for, on a channel we have already loaded.
        // Somebody re-keyed it while we were holding the old one - which is
        // exactly what a member who joined after the key was minted does, since
        // waiting for a re-wrap is not a fix - and our cached state is behind.
        //
        // Without re-reading here, the two clients sit on different epochs
        // until one of them is restarted: each renders the other's messages as
        // "no key on this device", and each keeps *sending* under its own stale
        // epoch so the reply is unreadable too. Reloading also moves this
        // client onto the newer epoch, which is what makes the conversation
        // work in both directions again.
        if (!missedEpochs.add("$channelId#$epoch")) return null
        forgetKeys(channelId)

        val fresh = runCatching { ensureChannelKey(channelId) }.getOrNull()?.keys?.get(epoch)
        // It was there after all, so anything else given up on for this channel
        // deserves another go.
        if (fresh != null) missedEpochs.removeAll { it.startsWith("$channelId#") }
        return fresh
    }

    /**
     * Resolves the channel's key, creating and distributing one if the channel
     * has never been keyed. Concurrent callers share one round trip.
     */
    private suspend fun ensureChannelKey(channelId: String): ChannelKeyState {
        channels[channelId]?.let { return it }
        val lock = channelLocks.getOrPut(channelId) { Mutex() }
        return lock.withLock {
            channels[channelId]
                ?: recallKeys(channelId)?.also { channels[channelId] = it }
                ?: loadChannelKey(channelId).also {
                    channels[channelId] = it
                    rememberKeys(channelId, it)
                }
        }
    }

    // --- channel keys at rest ---
    //
    // Without these, the message cache is useless: every cached row is an
    // envelope, and opening one meant a round trip to the key directory first.
    // A conversation would come back off disk instantly and then sit there
    // saying it had no key until the network answered - and say it for good
    // when there was no network to answer.
    //
    // They go in the same Keystore-sealed store the identity does, and not in
    // the cache database, which is deliberately worth nothing on its own.

    private fun keyStorageKey(channelId: String): String? =
        userId?.let { "channelkeys:$it:$channelId" }

    private fun rememberKeys(channelId: String, state: ChannelKeyState) {
        val name = keyStorageKey(channelId) ?: return
        runCatching {
            val keys = JSONObject()
            state.keys.forEach { (epoch, key) -> keys.put(epoch.toString(), key) }
            store.put(name, JSONObject().put("epoch", state.epoch).put("keys", keys).toString())
        }
    }

    private fun recallKeys(channelId: String): ChannelKeyState? {
        val name = keyStorageKey(channelId) ?: return null
        return runCatching {
            val json = JSONObject(store.get(name) ?: return null)
            val keys = json.getJSONObject("keys")
            ChannelKeyState(
                epoch = json.getInt("epoch"),
                keys = keys.keys().asSequence().associate { it.toInt() to keys.getString(it) },
            )
        }.getOrNull()
    }

    /** Drops a channel's keys from memory and from disk, so the next read refetches. */
    private fun forgetKeys(channelId: String) {
        channels.remove(channelId)
        keyStorageKey(channelId)?.let { runCatching { store.remove(it) } }
    }

    /**
     * Drops every channel key this device holds, in memory and at rest.
     *
     * Called when the identity changes under it - [restoreFromBackup]. The keys
     * are still valid, but they are the *subset* the old identity could reach,
     * and both caches would go on serving that subset while the wraps the new
     * identity can open sat unread in the directory.
     */
    private fun forgetAllKeys() {
        channels.clear()
        rekeyed.clear()
        missedEpochs.clear()
        userId?.let { runCatching { store.removeByPrefix("channelkeys:$it:") } }
    }

    private suspend fun loadChannelKey(channelId: String): ChannelKeyState {
        val self = currentIdentity()
        var response = BetweenUsApi.channelKeys(channelId)
        var keys = openKeys(response.keys, self)

        // We hold nothing for the current epoch. Either nobody has keyed the
        // channel yet, or it was keyed before we joined and every holder who
        // could re-wrap it for us is offline. Waiting on them is not a fix, so
        // mint the next epoch and wrap it for everybody - which is exactly what
        // the server lets any member who may send a message do. Earlier epochs
        // are untouched, so history from before we were a member stays closed.
        if (!keys.containsKey(response.epoch) && rekeyed.add(channelId)) {
            createChannelKey(channelId, response.epoch + 1)
            // Re-read rather than trusting our own write: another member may
            // have won the race, and then theirs is the epoch that counts.
            response = BetweenUsApi.channelKeys(channelId)
            keys = openKeys(response.keys, self)
        }

        if (!keys.containsKey(response.epoch)) throw MissingChannelKeyError()

        // Members who joined after the key was minted cannot read anything
        // until a holder re-wraps it for them. We hold it, so we do it.
        if (response.missingRecipients.isNotEmpty()) {
            keys[response.epoch]?.let {
                runCatching { shareKey(channelId, response.epoch, it, response.missingRecipients) }
            }
        }

        return ChannelKeyState(response.epoch, keys)
    }

    /** Opens every entry sealed for us, keyed by epoch. */
    private fun openKeys(
        entries: List<ChannelKeyEntry>,
        self: Crypto.KeyPairJwk,
    ): MutableMap<Int, String> {
        val keys = mutableMapOf<Int, String>()
        for (entry in entries) {
            runCatching {
                keys[entry.epoch] = Crypto.unwrapChannelKey(
                    Crypto.Wrapped(entry.wrappedKey, entry.iv),
                    self.privateKey,
                    entry.senderPublicKey,
                )
            }
            // A key sealed for another of our machines, or for an identity we
            // have since replaced. Both are rows this private half cannot open.
        }
        return keys
    }

    /**
     * Mints an epoch for a channel this device holds no key for - one nobody has
     * keyed, or one that was keyed before we were a member.
     */
    private suspend fun createChannelKey(channelId: String, epoch: Int) {
        val self = currentIdentity()
        val key = Crypto.generateChannelKey()
        val devices = BetweenUsApi.channelDevices(channelId)

        // Our own row may not be in the directory yet on a device that signed in
        // a moment ago. Minting a key we cannot open - or, with an empty
        // directory, publishing nothing at all - leaves the channel unkeyed and
        // the sender told there is no key, so always seal one for ourselves.
        // Being listed under our user id is no longer enough: the directory is a
        // row per machine, and that row may be the other laptop.
        val mine = DeviceIdentity.id()
        val recipients = if (devices.any { it.userId == userId && it.deviceId == mine }) {
            devices
        } else {
            devices + DeviceKey(userId.orEmpty(), mine, self.publicKey)
        }

        try {
            shareKey(channelId, epoch, key, recipients)
        } catch (error: ApiError) {
            // Another member keyed it first: harmless, the caller re-reads and
            // finds theirs. Which code comes back depends on whether they landed
            // on the epoch we wanted or ran past it. Anything else is a real
            // failure and must not be mistaken for "this device has no key".
            val raced = error.code == "EPOCH_OUT_OF_ORDER" || error.code == "EPOCH_NOT_HELD"
            if (!raced) throw error
        }
    }

    private suspend fun shareKey(
        channelId: String,
        epoch: Int,
        key: String,
        recipients: List<DeviceKey>,
    ) {
        if (recipients.isEmpty()) return
        val self = currentIdentity()
        val entries = recipients.mapNotNull { recipient ->
            runCatching {
                val wrapped = Crypto.wrapChannelKey(key, self.privateKey, recipient.publicKey)
                ChannelKeyEntry(
                    recipientUserId = recipient.userId,
                    recipientDeviceId = recipient.deviceId,
                    senderUserId = userId.orEmpty(),
                    senderDeviceId = DeviceIdentity.id(),
                    senderPublicKey = self.publicKey,
                    wrappedKey = wrapped.wrappedKey,
                    iv = wrapped.iv,
                    epoch = epoch,
                )
            }.getOrNull()
            // A directory row with a malformed public key must not stop the
            // channel being keyed for everybody else.
        }
        if (entries.isEmpty()) return
        BetweenUsApi.publishChannelKeys(channelId, epoch, DeviceIdentity.id(), entries)
    }
}

/**
 * The carrom board, as physics.
 *
 * Twenty discs on a square with four holes in the corners, sliding, colliding
 * and slowing down. This file is the simulation: rigid bodies, Coulomb
 * friction, elastic collisions with restitution, cushions, and a piece that
 * disappears when its centre reaches a pocket.
 *
 * ## Why the simulation is in the contract
 *
 * Because both ends run it, and they must agree exactly.
 *
 * The gateway runs it to decide what the board became - that is the refereeing,
 * and it is the only answer that counts. The client runs the *same function on
 * the same numbers* to animate the shot, because a shot that arrived as a set
 * of final positions would be twenty coins teleporting. What it shows is
 * therefore not a guess at the physics: it is the physics, replayed.
 *
 * That only works because this is deterministic. Fixed timestep, fixed
 * iteration order, no clock, no randomness, no `Set` iteration and no
 * floating-point that depends on how fast a machine is. Two IEEE-754 doubles
 * doing the same operations in the same order give the same answer on every
 * machine that will ever run this, so the last frame the client draws is the
 * position the gateway already sent.
 *
 * ## The units
 *
 * The playing surface is 1 x 1. Everything else is in fractions of it, taken
 * from a real board (74 cm playing area, 3.18 cm men, 4.13 cm striker, 4.45 cm
 * pockets), so the coins are the size they are relative to the board rather
 * than the size that felt right.
 */

/** Playing surface, corner to corner. Everything is a fraction of this. */
export const BOARD = 1;

/** A carrom man: 3.18 cm across on a 74 cm board. */
export const COIN_RADIUS = 0.0215;
/** The striker: 4.13 cm, and heavier, which is what makes a break work. */
export const STRIKER_RADIUS = 0.0279;
/** A pocket: 4.45 cm across, centred on the corner circle. */
export const POCKET_RADIUS = 0.0301;
/** How far a pocket's centre sits from each edge. */
export const POCKET_INSET = 0.043;

/** Grams. The ratio is what matters: a striker outweighs a man three to one. */
const COIN_MASS = 5.5;
const STRIKER_MASS = 15;

/**
 * Sliding friction, as a deceleration in board-widths per second squared.
 *
 * Coulomb rather than viscous - a real coin loses speed at a constant rate and
 * stops, where a `v *= 0.99` per step never quite does and leaves the board
 * creeping for ever. This is the number that decides whether a gentle shot
 * crosses the board, so it is the one to change if the board feels wrong.
 */
const FRICTION = 0.62;

/** Coin on coin. Ivory-ish: lively, not perfectly elastic. */
const RESTITUTION = 0.94;
/** Cushions take more out of a shot than a coin does. */
const WALL_RESTITUTION = 0.72;

/** Below this a piece has stopped, and the shot is over when they all have. */
const REST_SPEED = 0.012;

/** Fixed step. Small enough that a fast striker cannot pass through a coin. */
export const DT = 1 / 480;
/** Longest a shot may run before it is declared over, in seconds. */
const MAX_SECONDS = 9;
/** How many steps make one drawn frame, so a client animates at about 60 Hz. */
export const STEPS_PER_FRAME = 8;

/** One disc on the board. */
export interface Piece {
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  mass: number;
  /** False once it has gone down a hole. It stops being simulated. */
  onBoard: boolean;
}

/** Where the four pockets are. Ordered, because everything here is ordered. */
export const POCKETS: { x: number; y: number }[] = [
  { x: POCKET_INSET, y: POCKET_INSET },
  { x: BOARD - POCKET_INSET, y: POCKET_INSET },
  { x: POCKET_INSET, y: BOARD - POCKET_INSET },
  { x: BOARD - POCKET_INSET, y: BOARD - POCKET_INSET },
];

/** What one shot did, once everything has stopped. */
export interface ShotResult {
  pieces: Piece[];
  /** Indices that went down a hole, in the order they did. */
  pocketed: number[];
  /** Every `STEPS_PER_FRAME`th step, for a client to animate. */
  frames: number[][];
  /** Whether the striker touched anything at all. Missing entirely is a foul. */
  contact: boolean;
}

function speedSquared(piece: Piece): number {
  return piece.vx * piece.vx + piece.vy * piece.vy;
}

/**
 * Runs a shot to a standstill.
 *
 * `frames` is the whole point of returning more than the final position: the
 * client draws them in order and the coins move the way they actually moved.
 * They are sampled rather than kept per step, because a nine-second shot at
 * 480 Hz is four thousand snapshots of twenty coins and only sixty of them a
 * second are ever drawn.
 */
export function simulate(input: Piece[], striker: number): ShotResult {
  const pieces = input.map((piece) => ({ ...piece }));
  const pocketed: number[] = [];
  const frames: number[][] = [];
  let contact = false;
  let step = 0;
  const maxSteps = Math.round(MAX_SECONDS / DT);

  while (step < maxSteps) {
    step += 1;

    // 1. Move, and slow down. Friction is applied along the direction of
    //    travel and clamped at zero, so a coin stops rather than reversing -
    //    which is what subtracting more than the remaining speed would do.
    for (const piece of pieces) {
      if (!piece.onBoard) continue;
      const speed = Math.sqrt(speedSquared(piece));
      if (speed > 0) {
        const drop = FRICTION * DT;
        const scale = speed > drop ? (speed - drop) / speed : 0;
        piece.vx *= scale;
        piece.vy *= scale;
      }
      piece.x += piece.vx * DT;
      piece.y += piece.vy * DT;
    }

    // 2. Cushions. Position is corrected as well as velocity, or a coin driven
    //    into a wall sticks to it: it would be pushed back in one step and out
    //    again the next, for ever.
    for (const piece of pieces) {
      if (!piece.onBoard) continue;
      if (piece.x - piece.radius < 0) {
        piece.x = piece.radius;
        piece.vx = Math.abs(piece.vx) * WALL_RESTITUTION;
      } else if (piece.x + piece.radius > BOARD) {
        piece.x = BOARD - piece.radius;
        piece.vx = -Math.abs(piece.vx) * WALL_RESTITUTION;
      }
      if (piece.y - piece.radius < 0) {
        piece.y = piece.radius;
        piece.vy = Math.abs(piece.vy) * WALL_RESTITUTION;
      } else if (piece.y + piece.radius > BOARD) {
        piece.y = BOARD - piece.radius;
        piece.vy = -Math.abs(piece.vy) * WALL_RESTITUTION;
      }
    }

    // 3. Collisions, every pair, in index order. Order matters for
    //    reproducibility far more than it matters for realism: a three-coin
    //    pile-up resolved in a different order is a different board.
    for (let a = 0; a < pieces.length; a += 1) {
      const first = pieces[a]!;
      if (!first.onBoard) continue;
      for (let b = a + 1; b < pieces.length; b += 1) {
        const second = pieces[b]!;
        if (!second.onBoard) continue;

        const dx = second.x - first.x;
        const dy = second.y - first.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        const overlap = first.radius + second.radius - distance;
        if (overlap <= 0 || distance === 0) continue;

        const nx = dx / distance;
        const ny = dy / distance;

        // Push them apart in proportion to mass, so a struck coin moves more
        // than the striker does. Without this discs sink into each other and
        // the next step resolves the same collision again.
        const total = first.mass + second.mass;
        first.x -= nx * overlap * (second.mass / total);
        first.y -= ny * overlap * (second.mass / total);
        second.x += nx * overlap * (first.mass / total);
        second.y += ny * overlap * (first.mass / total);

        // Only the component along the line of centres is exchanged. The
        // tangential part is untouched, which is what makes a cut shot cut.
        const relative = (second.vx - first.vx) * nx + (second.vy - first.vy) * ny;
        if (relative > 0) continue;

        const impulse = (-(1 + RESTITUTION) * relative) / (1 / first.mass + 1 / second.mass);
        first.vx -= (impulse * nx) / first.mass;
        first.vy -= (impulse * ny) / first.mass;
        second.vx += (impulse * nx) / second.mass;
        second.vy += (impulse * ny) / second.mass;

        if (a === striker || b === striker) contact = true;
      }
    }

    // 4. Pockets. A piece is down when its *centre* is inside the hole, which
    //    is how a real one behaves - a coin overhanging the pocket stays up.
    for (let index = 0; index < pieces.length; index += 1) {
      const piece = pieces[index]!;
      if (!piece.onBoard) continue;
      for (const pocket of POCKETS) {
        const dx = piece.x - pocket.x;
        const dy = piece.y - pocket.y;
        if (dx * dx + dy * dy <= POCKET_RADIUS * POCKET_RADIUS) {
          piece.onBoard = false;
          piece.vx = 0;
          piece.vy = 0;
          pocketed.push(index);
          break;
        }
      }
    }

    if (step % STEPS_PER_FRAME === 0) frames.push(snapshot(pieces));

    // 5. Still? Then the shot is over. Checked after everything else so a
    //    collision in this very step is not mistaken for a standstill.
    let moving = false;
    for (const piece of pieces) {
      if (piece.onBoard && speedSquared(piece) > REST_SPEED * REST_SPEED) {
        moving = true;
        break;
      }
    }
    if (!moving) break;
  }

  // Anything still crawling is stopped, so the board the gateway stores is a
  // board at rest rather than one that would carry on if it were asked again.
  for (const piece of pieces) {
    piece.vx = 0;
    piece.vy = 0;
  }
  frames.push(snapshot(pieces));

  return { pieces, pocketed, frames, contact };
}

/** One frame: x, y and on-board for every piece, flat. */
function snapshot(pieces: Piece[]): number[] {
  const flat: number[] = [];
  for (const piece of pieces) {
    flat.push(piece.x, piece.y, piece.onBoard ? 1 : 0);
  }
  return flat;
}

/** A carrom man at rest. */
export function coin(x: number, y: number): Piece {
  return { x, y, vx: 0, vy: 0, radius: COIN_RADIUS, mass: COIN_MASS, onBoard: true };
}

/** The striker, aimed and struck. */
export function striker(x: number, y: number, vx: number, vy: number): Piece {
  return { x, y, vx, vy, radius: STRIKER_RADIUS, mass: STRIKER_MASS, onBoard: true };
}
